    @staticmethod
    def now_iso() -> str:
        return utc_now()

    def load_recent_live_inventory_execution_loss_bps(self) -> None:
        orders_file = getattr(self, "orders_file", None)
        if orders_file is None or not orders_file.exists():
            return
        samples: deque[Decimal] = deque(maxlen=self.live_inventory_execution_loss_bps_samples.maxlen)
        try:
            with orders_file.open("r", encoding="utf-8") as handle:
                for line in handle:
                    if '"event": "live_inventory_final_pnl"' not in line:
                        continue
                    try:
                        row = json.loads(line)
                    except json.JSONDecodeError:
                        continue
                    if not str(row.get("strategy_version") or "").startswith(
                        "basis-v4-live"
                    ):
                        continue
                    if str(row.get("asset") or "").upper() != "ETH":
                        continue
                    if row.get("direction") != DIRECTION_SHORT_VAR_LONG_LIGHTER:
                        continue
                    if row.get("final_pnl_status") != "var_and_lighter_final_fills_confirmed":
                        continue
                    loss_bps = to_decimal(row.get("entry_edge_capture_loss_bps"))
                    if loss_bps is not None:
                        # Zero-loss fills are observations and must contribute to
                        # calibration maturity instead of biasing P80 upward.
                        samples.append(max(loss_bps, Decimal("0")))
        except OSError as exc:
            self.logger.warning("Could not load recent live inventory execution loss samples: %s", exc)
            return
        self.live_inventory_execution_loss_bps_samples.extend(samples)

    @staticmethod
    def percentile_decimal(values: Iterable[Decimal], percentile: int) -> Decimal | None:
        ordered = sorted(value for value in values if value is not None)
        if not ordered:
            return None
        rank = ((len(ordered) * percentile) + 99) // 100
        index = max(0, min(len(ordered) - 1, rank - 1))
        return ordered[index]

    def live_inventory_recent_execution_loss_buffer_bps(self) -> Decimal:
        return self.percentile_decimal(getattr(self, "live_inventory_execution_loss_bps_samples", []), 80) or Decimal("0")

    def live_inventory_basis_v4_entry_calibration_context(self) -> dict[str, Any]:
        samples = list(
            getattr(self, "live_inventory_execution_loss_bps_samples", [])
        )
        sample_count = len(samples)
        raw_p80_bps = self.percentile_decimal(samples, 80) or Decimal("0")
        ready = sample_count >= LIVE_INVENTORY_BASIS_V4_ENTRY_CAPTURE_MIN_SAMPLES
        fully_mature = (
            sample_count >= LIVE_INVENTORY_BASIS_V4_ENTRY_CAPTURE_FULL_SAMPLES
        )
        capped_raw_p80_bps = min(
            raw_p80_bps,
            LIVE_INVENTORY_BASIS_V4_ENTRY_CAPTURE_CAP_BPS,
        )
        if not ready:
            applied_bps = LIVE_INVENTORY_BASIS_V4_ENTRY_CAPTURE_PRIOR_BPS
            calibration_weight = Decimal("0")
        elif fully_mature:
            applied_bps = capped_raw_p80_bps
            calibration_weight = Decimal("1")
        else:
            calibration_weight = Decimal(
                sample_count - LIVE_INVENTORY_BASIS_V4_ENTRY_CAPTURE_MIN_SAMPLES
            ) / Decimal(
                LIVE_INVENTORY_BASIS_V4_ENTRY_CAPTURE_FULL_SAMPLES
                - LIVE_INVENTORY_BASIS_V4_ENTRY_CAPTURE_MIN_SAMPLES
            )
            applied_bps = (
                LIVE_INVENTORY_BASIS_V4_ENTRY_CAPTURE_PRIOR_BPS
                * (Decimal("1") - calibration_weight)
                + capped_raw_p80_bps * calibration_weight
            )
        return {
            "sample_count": sample_count,
            "min_samples": LIVE_INVENTORY_BASIS_V4_ENTRY_CAPTURE_MIN_SAMPLES,
            "full_samples": LIVE_INVENTORY_BASIS_V4_ENTRY_CAPTURE_FULL_SAMPLES,
            "ready": ready,
            "fully_mature": fully_mature,
            "raw_p80_bps": raw_p80_bps,
            "prior_bps": LIVE_INVENTORY_BASIS_V4_ENTRY_CAPTURE_PRIOR_BPS,
            "calibration_weight": calibration_weight,
            "cap_bps": LIVE_INVENTORY_BASIS_V4_ENTRY_CAPTURE_CAP_BPS,
            "applied_bps": applied_bps,
        }

    def live_inventory_basis_v4_entry_calibration_payload(self) -> dict[str, Any]:
        context = self.live_inventory_basis_v4_entry_calibration_context()
        return {
            "v4_entry_capture_sample_count": context["sample_count"],
            "v4_entry_capture_min_samples": context["min_samples"],
            "v4_entry_capture_full_samples": context["full_samples"],
            "v4_entry_capture_calibration_ready": context["ready"],
            "v4_entry_capture_fully_mature": context["fully_mature"],
            "v4_entry_capture_raw_p80_bps": decimal_to_str(
                context["raw_p80_bps"]
            ),
            "v4_entry_capture_prior_bps": decimal_to_str(
                context["prior_bps"]
            ),
            "v4_entry_capture_calibration_weight": decimal_to_str(
                context["calibration_weight"]
            ),
            "v4_entry_capture_cap_bps": decimal_to_str(context["cap_bps"]),
            "v4_entry_capture_applied_bps": decimal_to_str(
                context["applied_bps"]
            ),
        }

    def live_inventory_basis_v4_entry_execution_reserve_bps(self) -> Decimal:
        return self.live_inventory_basis_v4_entry_calibration_context()[
            "applied_bps"
        ]

    def load_recent_live_inventory_exit_shortfall_bps(self) -> None:
        orders_file = getattr(self, "orders_file", None)
        if orders_file is None or not orders_file.exists():
            return
        samples: deque[Decimal] = deque(maxlen=self.live_inventory_exit_estimate_shortfall_bps_samples.maxlen)
        strong_single_target = getattr(
            self,
            "live_inventory_strong_single_shortfall_bps_samples",
            None,
        )
        if strong_single_target is None:
            strong_single_target = deque(maxlen=20)
            self.live_inventory_strong_single_shortfall_bps_samples = (
                strong_single_target
            )
        strong_single_samples: deque[Decimal] = deque(
            maxlen=strong_single_target.maxlen
        )
        try:
            with orders_file.open("r", encoding="utf-8") as handle:
                for line in handle:
                    if '"event": "live_inventory_actual_pnl"' not in line:
                        continue
                    try:
                        row = json.loads(line)
                    except json.JSONDecodeError:
                        continue
                    if str(row.get("strategy_version") or "") not in (
                        LIVE_INVENTORY_BASIS_V4_EXIT_CALIBRATION_STRATEGY_VERSIONS
                    ):
                        continue
                    if str(row.get("asset") or "").upper() != "ETH":
                        continue
                    if row.get("direction") != DIRECTION_SHORT_VAR_LONG_LIGHTER:
                        continue
                    if row.get("actual_pnl_status") != "lighter_final_fill_confirmed":
                        continue
                    estimated_bps = to_decimal(row.get("estimated_pnl_bps"))
                    actual_bps = to_decimal(row.get("actual_pnl_bps"))
                    if estimated_bps is None or actual_bps is None:
                        continue
                    # Zero-shortfall fills are real observations and must count
                    # toward calibration maturity instead of biasing the sample.
                    shortfall_bps = max(
                        estimated_bps - actual_bps,
                        Decimal("0"),
                    )
                    samples.append(shortfall_bps)
                    if row.get("exit_confirmation_mode") == "strong_single":
                        strong_single_samples.append(shortfall_bps)
        except OSError as exc:
            self.logger.warning("Could not load recent live inventory exit shortfall samples: %s", exc)
            return
        self.live_inventory_exit_estimate_shortfall_bps_samples.extend(samples)
        self.live_inventory_strong_single_shortfall_bps_samples.extend(
            strong_single_samples
        )

    def live_inventory_dynamic_exit_buffer_bps(self) -> Decimal:
        if not self.live_inventory_basis_dynamic_exit_buffer:
            return Decimal("0")
        return self.percentile_decimal(getattr(self, "live_inventory_exit_estimate_shortfall_bps_samples", []), 80) or Decimal("0")

    def live_inventory_basis_v4_exit_calibration_context(self) -> dict[str, Any]:
        samples = list(
            getattr(self, "live_inventory_exit_estimate_shortfall_bps_samples", [])
        )
        sample_count = len(samples)
        raw_p80_bps = self.percentile_decimal(samples, 80) or Decimal("0")
        enabled = bool(
            getattr(self, "live_inventory_basis_dynamic_exit_buffer", False)
        )
        ready = bool(
            enabled
            and sample_count >= LIVE_INVENTORY_BASIS_V4_EXIT_SHORTFALL_MIN_SAMPLES
        )
        fully_mature = bool(
            enabled
            and sample_count >= LIVE_INVENTORY_BASIS_V4_EXIT_SHORTFALL_FULL_SAMPLES
        )
        capped_raw_p80_bps = min(
            raw_p80_bps,
            LIVE_INVENTORY_BASIS_V4_EXIT_SHORTFALL_CAP_BPS,
        )
        if not enabled:
            applied_dynamic_bps = Decimal("0")
            calibration_weight = Decimal("0")
            stage_floor_bps = LIVE_INVENTORY_BASIS_V4_SHORTFALL_RESERVE_BPS
        elif not ready:
            applied_dynamic_bps = LIVE_INVENTORY_BASIS_V4_EXIT_SHORTFALL_PRIOR_BPS
            calibration_weight = Decimal("0")
            stage_floor_bps = LIVE_INVENTORY_BASIS_V4_EXIT_SHORTFALL_PRIOR_BPS
        elif fully_mature:
            applied_dynamic_bps = capped_raw_p80_bps
            calibration_weight = Decimal("1")
            stage_floor_bps = LIVE_INVENTORY_BASIS_V4_SHORTFALL_RESERVE_BPS
        else:
            # Once ten fills exist, use observed execution shortfall directly.
            # A bounded floor protects the still-young sample without carrying
            # the conservative 3.5 bps cold-start prior all the way to sample 20.
            calibration_weight = Decimal("1")
            stage_floor_bps = (
                LIVE_INVENTORY_BASIS_V4_EXIT_SHORTFALL_EARLY_READY_FLOOR_BPS
            )
            applied_dynamic_bps = max(
                capped_raw_p80_bps,
                stage_floor_bps,
            )
        reserve_bps = max(
            stage_floor_bps,
            applied_dynamic_bps,
        )
        return {
            "sample_count": sample_count,
            "min_samples": LIVE_INVENTORY_BASIS_V4_EXIT_SHORTFALL_MIN_SAMPLES,
            "full_samples": LIVE_INVENTORY_BASIS_V4_EXIT_SHORTFALL_FULL_SAMPLES,
            "ready": ready,
            "fully_mature": fully_mature,
            "raw_p80_bps": raw_p80_bps,
            "prior_bps": LIVE_INVENTORY_BASIS_V4_EXIT_SHORTFALL_PRIOR_BPS,
            "calibration_weight": calibration_weight,
            "stage_floor_bps": stage_floor_bps,
            "cap_bps": LIVE_INVENTORY_BASIS_V4_EXIT_SHORTFALL_CAP_BPS,
            "applied_dynamic_bps": applied_dynamic_bps,
            "reserve_bps": reserve_bps,
        }

    def live_inventory_basis_v4_exit_calibration_payload(self) -> dict[str, Any]:
        context = self.live_inventory_basis_v4_exit_calibration_context()
        return {
            "v4_exit_shortfall_sample_count": context["sample_count"],
            "v4_exit_shortfall_min_samples": context["min_samples"],
            "v4_exit_shortfall_full_samples": context["full_samples"],
            "v4_exit_shortfall_calibration_ready": context["ready"],
            "v4_exit_shortfall_fully_mature": context["fully_mature"],
            "v4_exit_shortfall_raw_p80_bps": decimal_to_str(
                context["raw_p80_bps"]
            ),
            "v4_exit_shortfall_prior_bps": decimal_to_str(
                context["prior_bps"]
            ),
            "v4_exit_shortfall_calibration_weight": decimal_to_str(
                context["calibration_weight"]
            ),
            "v4_exit_shortfall_stage_floor_bps": decimal_to_str(
                context["stage_floor_bps"]
            ),
            "v4_exit_shortfall_cap_bps": decimal_to_str(context["cap_bps"]),
            "v4_exit_shortfall_applied_dynamic_bps": decimal_to_str(
                context["applied_dynamic_bps"]
            ),
            "v4_exit_shortfall_reserve_bps": decimal_to_str(
                context["reserve_bps"]
            ),
        }

    def live_inventory_basis_v4_exit_shortfall_reserve_bps(self) -> Decimal:
        return self.live_inventory_basis_v4_exit_calibration_context()["reserve_bps"]

    def live_inventory_basis_v4_effective_exit_target_bps(self) -> Decimal:
        return (
            LIVE_INVENTORY_BASIS_V4_NET_EXIT_TARGET_BPS
            + self.live_inventory_basis_v4_exit_shortfall_reserve_bps()
        )

    def live_inventory_basis_v4_strong_single_context(
        self,
        *,
        effective_min_exit_pnl_bps: Decimal,
    ) -> dict[str, Any]:
        samples = list(
            getattr(
                self,
                "live_inventory_strong_single_shortfall_bps_samples",
                [],
            )
        )
        sample_count = len(samples)
        raw_p80_bps = self.percentile_decimal(samples, 80) or Decimal("0")
        ready = sample_count >= LIVE_INVENTORY_BASIS_V4_EXIT_STRONG_SHORTFALL_MIN_SAMPLES
        mode_reserve_bps = (
            min(
                raw_p80_bps,
                LIVE_INVENTORY_BASIS_V4_EXIT_STRONG_SHORTFALL_CAP_BPS,
            )
            if ready
            else LIVE_INVENTORY_BASIS_V4_EXIT_STRONG_SHORTFALL_PRIOR_BPS
        )
        general_reserve_bps = self.live_inventory_basis_v4_exit_shortfall_reserve_bps()
        incremental_reserve_bps = max(
            mode_reserve_bps - general_reserve_bps,
            Decimal("0"),
        )
        threshold_bps = (
            effective_min_exit_pnl_bps
            + incremental_reserve_bps
            + LIVE_INVENTORY_BASIS_V4_EXIT_STRONG_SINGLE_MARGIN_BPS
        )
        return {
            "enabled": bool(
                getattr(self, "live_inventory_v4_strong_single_enabled", True)
            ),
            "disabled_reason": getattr(
                self,
                "live_inventory_v4_strong_single_disabled_reason",
                None,
            ),
            "sample_count": sample_count,
            "min_samples": LIVE_INVENTORY_BASIS_V4_EXIT_STRONG_SHORTFALL_MIN_SAMPLES,
            "ready": ready,
            "raw_p80_bps": raw_p80_bps,
            "prior_bps": LIVE_INVENTORY_BASIS_V4_EXIT_STRONG_SHORTFALL_PRIOR_BPS,
            "cap_bps": LIVE_INVENTORY_BASIS_V4_EXIT_STRONG_SHORTFALL_CAP_BPS,
            "mode_reserve_bps": mode_reserve_bps,
            "incremental_reserve_bps": incremental_reserve_bps,
            "threshold_bps": threshold_bps,
        }

    @staticmethod
    def live_inventory_basis_v4_confirm_exit_candidate(
        lot: dict[str, Any],
        *,
        eligible: bool,
    ) -> tuple[bool, int]:
        window = list(lot.get("v4_exit_confirmation_window") or [])
        window.append(bool(eligible))
        window = window[-LIVE_INVENTORY_BASIS_V4_EXIT_CONFIRM_WINDOW_SAMPLES:]
        confirmation_count = sum(1 for value in window if value)
        lot["v4_exit_confirmation_window"] = window
        lot["v4_exit_confirmation_count"] = confirmation_count
        return (
            bool(
                eligible
                and confirmation_count
                >= LIVE_INVENTORY_BASIS_V4_EXIT_CONFIRM_SAMPLES
            ),
            confirmation_count,
        )

    @staticmethod
    def live_inventory_basis_v4_reset_exit_confirmation(
        lot: dict[str, Any],
    ) -> None:
        lot.pop("v4_exit_confirmation_count", None)
        lot.pop("v4_exit_confirmation_window", None)
        lot.pop("v4_exit_strong_stability_values", None)

    def load_recent_live_inventory_actual_pnl_stats(self) -> None:
        orders_file = getattr(self, "orders_file", None)
        if orders_file is None or not orders_file.exists():
            return
        by_direction: dict[str, deque[Decimal]] = {
            DIRECTION_LONG_VAR_SHORT_LIGHTER: deque(maxlen=20),
            DIRECTION_SHORT_VAR_LONG_LIGHTER: deque(maxlen=20),
        }
        latency_samples: deque[Decimal] = deque(maxlen=20)
        quote_age_samples: deque[Decimal] = deque(maxlen=50)
        try:
            with orders_file.open("r", encoding="utf-8") as handle:
                for line in handle:
                    if '"event": "live_inventory_' not in line:
                        continue
                    try:
                        row = json.loads(line)
                    except json.JSONDecodeError:
                        continue
                    event = str(row.get("event") or "")
                    if event in {"live_inventory_basis_state", "live_inventory_entry_blocked", "live_inventory_entered", "live_inventory_exited"}:
                        quote_age = to_decimal(row.get("var_quote_age_seconds"))
                        if quote_age is not None and quote_age >= 0:
                            quote_age_samples.append(quote_age)
                    if event != "live_inventory_actual_pnl":
                        continue
                    direction = str(row.get("direction") or "")
                    pnl_bps = to_decimal(row.get("actual_pnl_bps"))
                    if direction in by_direction and pnl_bps is not None:
                        by_direction[direction].append(pnl_bps)
                    latency_ms = to_decimal(row.get("exit_var_fill_to_lighter_fill_ms"))
                    if latency_ms is not None and latency_ms >= 0:
                        latency_samples.append(latency_ms)
        except OSError as exc:
            self.logger.warning("Could not load recent live inventory actual PnL stats: %s", exc)
            return
        for direction, samples in by_direction.items():
            self.live_inventory_actual_pnl_bps_by_direction[direction].extend(samples)
        self.live_inventory_exit_fill_latency_ms_samples.extend(latency_samples)
        self.live_inventory_var_quote_age_seconds_samples.extend(quote_age_samples)

    def live_inventory_direction_avg_pnl_bps(self, direction: str) -> Decimal | None:
        samples = list(getattr(self, "live_inventory_actual_pnl_bps_by_direction", {}).get(direction, []))
        if not samples:
            return None
        return sum(samples) / Decimal(len(samples))

    def live_inventory_direction_paused(self, direction: str) -> tuple[bool, dict[str, Any]]:
        samples = list(getattr(self, "live_inventory_actual_pnl_bps_by_direction", {}).get(direction, []))
        avg = sum(samples) / Decimal(len(samples)) if samples else None
        context = {
            "direction": direction,
            "direction_sample_count": len(samples),
            "direction_avg_actual_pnl_bps": decimal_to_str(avg),
            "direction_min_samples": self.live_inventory_basis_direction_min_samples,
            "direction_min_avg_pnl_bps": decimal_to_str(self.live_inventory_basis_direction_min_avg_pnl_bps),
        }
        if not self.live_inventory_basis_disable_negative_direction:
            return False, context
        if len(samples) < self.live_inventory_basis_direction_min_samples:
            return False, context
        return avg is not None and avg < self.live_inventory_basis_direction_min_avg_pnl_bps, context

    def live_inventory_direction_entry_threshold_bps(self, direction: str) -> Decimal:
        if direction == DIRECTION_LONG_VAR_SHORT_LIGHTER and self.live_inventory_basis_long_min_entry_edge_bps > 0:
            return self.live_inventory_basis_long_min_entry_edge_bps
        if direction == DIRECTION_SHORT_VAR_LONG_LIGHTER and self.live_inventory_basis_short_min_entry_edge_bps > 0:
            return self.live_inventory_basis_short_min_entry_edge_bps
        return self.live_inventory_basis_min_entry_edge_bps

    def live_inventory_calibration_direction_for_cycle(self) -> str:
        configured = getattr(self, "live_inventory_calibration_direction", "alternate")
        if configured != "alternate":
            return configured
        return (
            DIRECTION_LONG_VAR_SHORT_LIGHTER
            if self.live_inventory_completed_cycles % 2 == 0
            else DIRECTION_SHORT_VAR_LONG_LIGHTER
        )

    def live_inventory_calibration_entry_time_allowed(
        self,
        now_utc: datetime | None = None,
    ) -> bool:
        if not getattr(self, "live_inventory_calibration_weekdays_only", False):
            return True
        current = now_utc or datetime.now(timezone.utc)
        return current.astimezone(timezone.utc).weekday() < 5

    def live_inventory_basis_v4_entry_time_allowed(
        self,
        now_utc: datetime | None = None,
    ) -> bool:
        # V4 trades continuously. Weekend boundary risk is handled by the
        # multi-window threshold transition rather than a calendar shutdown.
        return True

    @staticmethod
    def spread_bps_from_bid_ask(bid: Decimal | None, ask: Decimal | None) -> Decimal | None:
        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return None
        if ask < bid:
            bid, ask = ask, bid
        mid = (bid + ask) / Decimal("2")
        if mid <= 0:
            return None
        return (ask - bid) / mid * Decimal("10000")

    def live_inventory_basis_dynamic_entry_threshold_bps(
        self,
        *,
        static_floor_bps: Decimal,
        var_spread_bps: Decimal | None,
        lighter_spread_bps: Decimal | None,
    ) -> tuple[Decimal, dict[str, Any]]:
        var_spread = var_spread_bps or Decimal("0")
        lighter_spread = lighter_spread_bps or Decimal("0")
        slippage_buffer = max(
            self.live_inventory_recent_execution_loss_buffer_bps(),
            self.live_inventory_dynamic_exit_buffer_bps(),
        )
        var_median = self.percentile_decimal(self.live_inventory_basis_var_spread_bps_samples, 50)
        var_p80 = self.percentile_decimal(self.live_inventory_basis_var_spread_bps_samples, 80)
        var_p95 = self.percentile_decimal(self.live_inventory_basis_var_spread_bps_samples, 95)
        lighter_median = self.percentile_decimal(self.live_inventory_basis_lighter_spread_bps_samples, 50)
        lighter_p80 = self.percentile_decimal(self.live_inventory_basis_lighter_spread_bps_samples, 80)
        lighter_p95 = self.percentile_decimal(self.live_inventory_basis_lighter_spread_bps_samples, 95)

        spread_penalty = Decimal("0")
        var_regime = "unknown"
        if var_p95 is not None and var_median is not None and var_spread > var_p95:
            var_regime = "extreme"
            spread_penalty += max(Decimal("0"), var_spread - var_median)
        elif var_p80 is not None and var_median is not None and var_spread > var_p80:
            var_regime = "wide"
            spread_penalty += max(Decimal("0"), var_spread - var_median)
        elif var_spread_bps is not None:
            var_regime = "normal"

        lighter_regime = "unknown"
        if lighter_p95 is not None and lighter_median is not None and lighter_spread > lighter_p95:
            lighter_regime = "extreme"
            spread_penalty += max(Decimal("0"), lighter_spread - lighter_median)
        elif lighter_p80 is not None and lighter_median is not None and lighter_spread > lighter_p80:
            lighter_regime = "wide"
            spread_penalty += max(Decimal("0"), lighter_spread - lighter_median)
        elif lighter_spread_bps is not None:
            lighter_regime = "normal"

        spread_penalty *= self.live_inventory_basis_spread_regime_penalty_multiplier
        dynamic_required = (
            var_spread
            + lighter_spread
            + slippage_buffer
            + self.live_inventory_basis_min_signal_reverted_exit_pnl_bps
            + self.live_inventory_basis_dynamic_entry_noise_buffer_bps
            + spread_penalty
        )
        threshold = max(static_floor_bps, dynamic_required) if self.live_inventory_basis_dynamic_entry_threshold else static_floor_bps
        return threshold, {
            "dynamic_entry_threshold_enabled": self.live_inventory_basis_dynamic_entry_threshold,
            "dynamic_entry_static_floor_bps": decimal_to_str(static_floor_bps),
            "dynamic_entry_required_bps": decimal_to_str(dynamic_required),
            "dynamic_entry_threshold_bps": decimal_to_str(threshold),
            "dynamic_entry_var_spread_bps": decimal_to_str(var_spread_bps),
            "dynamic_entry_lighter_spread_bps": decimal_to_str(lighter_spread_bps),
            "dynamic_entry_slippage_buffer_bps": decimal_to_str(slippage_buffer),
            "dynamic_entry_exit_profit_bps": decimal_to_str(self.live_inventory_basis_min_signal_reverted_exit_pnl_bps),
            "dynamic_entry_noise_buffer_bps": decimal_to_str(self.live_inventory_basis_dynamic_entry_noise_buffer_bps),
            "dynamic_entry_spread_penalty_bps": decimal_to_str(spread_penalty),
            "dynamic_entry_var_spread_p50_bps": decimal_to_str(var_median),
            "dynamic_entry_var_spread_p80_bps": decimal_to_str(var_p80),
            "dynamic_entry_var_spread_p95_bps": decimal_to_str(var_p95),
            "dynamic_entry_lighter_spread_p50_bps": decimal_to_str(lighter_median),
            "dynamic_entry_lighter_spread_p80_bps": decimal_to_str(lighter_p80),
            "dynamic_entry_lighter_spread_p95_bps": decimal_to_str(lighter_p95),
            "dynamic_entry_var_spread_regime": var_regime,
            "dynamic_entry_lighter_spread_regime": lighter_regime,
        }

    def live_inventory_basis_dynamic_sample_move_threshold_bps(self) -> tuple[Decimal, dict[str, Any]]:
        static_floor = self.live_inventory_basis_max_sample_move_bps
        if static_floor <= 0:
            return static_floor, {
                "basis_dynamic_sample_move_enabled": False,
                "basis_static_max_sample_move_bps": decimal_to_str(static_floor),
                "basis_dynamic_max_sample_move_bps": decimal_to_str(static_floor),
                "basis_sample_move_p80_bps": None,
                "basis_sample_move_p90_bps": None,
            }
        sample_p80 = self.percentile_decimal(self.live_inventory_basis_sample_move_bps_samples, 80)
        sample_p90 = self.percentile_decimal(self.live_inventory_basis_sample_move_bps_samples, 90)
        dynamic_threshold = max(static_floor, sample_p80 or Decimal("0"))
        dynamic_cap = max(static_floor, Decimal("6"))
        dynamic_threshold = min(dynamic_threshold, dynamic_cap)
        return dynamic_threshold, {
            "basis_dynamic_sample_move_enabled": True,
            "basis_static_max_sample_move_bps": decimal_to_str(static_floor),
            "basis_dynamic_max_sample_move_bps": decimal_to_str(dynamic_threshold),
            "basis_sample_move_p80_bps": decimal_to_str(sample_p80),
            "basis_sample_move_p90_bps": decimal_to_str(sample_p90),
            "basis_sample_move_dynamic_cap_bps": decimal_to_str(dynamic_cap),
        }

    def live_inventory_open_notional_usd(self) -> Decimal:
        total = Decimal("0")
        for lot in self.live_inventory_open_lots:
            qty = to_decimal(lot.get("qty"))
            entry_price = to_decimal(lot.get("entry_var_fill_price"))
            if qty is not None and qty > 0 and entry_price is not None and entry_price > 0:
                total += qty * entry_price
            else:
                # Older persisted lots may lack final fill fields; reserve one lot conservatively.
                total += self.live_inventory_lot_notional_usd
        return total

    def live_inventory_direction_abs_threshold_bps(self, direction: str) -> Decimal:
        if direction == DIRECTION_LONG_VAR_SHORT_LIGHTER and self.live_inventory_basis_long_min_abs_entry_bps > 0:
            return self.live_inventory_basis_long_min_abs_entry_bps
        if direction == DIRECTION_SHORT_VAR_LONG_LIGHTER and self.live_inventory_basis_short_min_abs_entry_bps > 0:
            return self.live_inventory_basis_short_min_abs_entry_bps
        return self.live_inventory_basis_min_abs_entry_bps

    def live_inventory_negative_direction_penalties(self, direction: str) -> tuple[bool, Decimal, Decimal, dict[str, Any]]:
        samples = list(getattr(self, "live_inventory_actual_pnl_bps_by_direction", {}).get(direction, []))
        avg = sum(samples) / Decimal(len(samples)) if samples else None
        is_negative = (
            len(samples) >= self.live_inventory_basis_direction_min_samples
            and avg is not None
            and avg < self.live_inventory_basis_direction_min_avg_pnl_bps
        )
        context = {
            "direction": direction,
            "negative_direction_mode": self.live_inventory_basis_negative_direction_mode,
            "direction_sample_count": len(samples),
            "direction_avg_actual_pnl_bps": decimal_to_str(avg),
            "direction_is_negative": is_negative,
            "negative_direction_entry_penalty_bps": decimal_to_str(self.live_inventory_basis_negative_direction_entry_penalty_bps if is_negative else Decimal("0")),
            "negative_direction_abs_penalty_bps": decimal_to_str(self.live_inventory_basis_negative_direction_abs_penalty_bps if is_negative else Decimal("0")),
        }
        if not is_negative or self.live_inventory_basis_negative_direction_mode != LIVE_INVENTORY_NEGATIVE_DIRECTION_MODE_PENALIZE:
            return is_negative, Decimal("0"), Decimal("0"), context
        return is_negative, self.live_inventory_basis_negative_direction_entry_penalty_bps, self.live_inventory_basis_negative_direction_abs_penalty_bps, context

    def live_inventory_entry_quality_score_bps(
        self,
        *,
        edge_bps: Decimal,
        min_entry_bps: Decimal,
        dynamic_buffer_bps: Decimal,
        basis_sample_move_bps: Decimal | None,
        roundtrip_bps: Decimal,
    ) -> tuple[Decimal, dict[str, Any]]:
        sample_move_penalty = (
            Decimal("0")
            if basis_sample_move_bps is None
            else basis_sample_move_bps * self.live_inventory_basis_sample_move_penalty_multiplier
        )
        roundtrip_penalty = max(Decimal("0"), -roundtrip_bps)
        score = edge_bps - min_entry_bps - dynamic_buffer_bps - sample_move_penalty - roundtrip_penalty
        return score, {
            "entry_quality_score_bps": decimal_to_str(score),
            "entry_quality_min_score_bps": decimal_to_str(self.live_inventory_basis_min_entry_quality_score_bps),
            "entry_quality_min_entry_bps": decimal_to_str(min_entry_bps),
            "entry_quality_dynamic_buffer_bps": decimal_to_str(dynamic_buffer_bps),
            "entry_quality_sample_move_penalty_bps": decimal_to_str(sample_move_penalty),
            "entry_quality_roundtrip_penalty_bps": decimal_to_str(roundtrip_penalty),
        }

    def live_inventory_stablecoin_edge_context(
        self,
        *,
        raw_edge_bps: Decimal | None,
        normalized_edge_bps: Decimal | None,
    ) -> tuple[bool, dict[str, Any]]:
        raw_edge = raw_edge_bps if raw_edge_bps is not None else Decimal("0")
        adjustment_bps = None if normalized_edge_bps is None else raw_edge - normalized_edge_bps
        share = None
        if adjustment_bps is not None and raw_edge != 0:
            share = abs(adjustment_bps) / abs(raw_edge)
        context = {
            "stablecoin_filter_enabled": self.live_inventory_basis_min_normalized_filter_edge_bps is not None
            or self.live_inventory_basis_max_stablecoin_edge_share > 0,
            "stablecoin_filter_min_normalized_edge_bps": decimal_to_str(self.live_inventory_basis_min_normalized_filter_edge_bps),
            "stablecoin_filter_max_edge_share": decimal_to_str(self.live_inventory_basis_max_stablecoin_edge_share),
            "stablecoin_edge_adjustment_bps": decimal_to_str(adjustment_bps),
            "stablecoin_edge_adjustment_abs_bps": decimal_to_str(None if adjustment_bps is None else abs(adjustment_bps)),
            "stablecoin_edge_share": decimal_to_str(share),
        }
        if not context["stablecoin_filter_enabled"]:
            return True, context
        if normalized_edge_bps is None:
            return False, {**context, "stablecoin_filter_reason": "normalized_edge_unavailable"}
        if (
            self.live_inventory_basis_min_normalized_filter_edge_bps is not None
            and normalized_edge_bps < self.live_inventory_basis_min_normalized_filter_edge_bps
        ):
            return False, {**context, "stablecoin_filter_reason": "normalized_edge_below_filter"}
        if self.live_inventory_basis_max_stablecoin_edge_share > 0 and share is not None and share > self.live_inventory_basis_max_stablecoin_edge_share:
            return False, {**context, "stablecoin_filter_reason": "stablecoin_edge_share_too_high"}
        return True, {**context, "stablecoin_filter_reason": "ok"}

    @staticmethod
    def live_inventory_stablecoin_alignment(
        *,
        raw_edge_bps: Decimal | None,
        normalized_edge_bps: Decimal | None,
        neutral_band_bps: Decimal = Decimal("0.25"),
    ) -> str:
        if raw_edge_bps is None or normalized_edge_bps is None:
            return "unknown"
        contribution = raw_edge_bps - normalized_edge_bps
        if abs(contribution) <= neutral_band_bps:
            return "neutral"
        return "aligned" if contribution > 0 else "opposed"

    def live_inventory_record_stablecoin_basis_sample(self, stablecoin_context: dict[str, Any]) -> None:
        basis_bps = to_decimal(stablecoin_context.get("stablecoin_basis_bps"))
        if basis_bps is not None:
            self.live_inventory_stablecoin_basis_bps_samples.append(basis_bps)

    def live_inventory_stablecoin_regime_context(
        self,
        *,
        raw_edge_bps: Decimal | None,
        normalized_edge_bps: Decimal | None,
        stablecoin_context: dict[str, Any],
    ) -> tuple[bool, dict[str, Any]]:
        enabled = self.live_inventory_basis_stablecoin_regime_entry
        stablecoin_basis_bps = to_decimal(stablecoin_context.get("stablecoin_basis_bps"))
        raw_edge = raw_edge_bps if raw_edge_bps is not None else None
        required_raw_edge_bps = None if stablecoin_basis_bps is None else abs(stablecoin_basis_bps) + self.live_inventory_basis_stablecoin_regime_buffer_bps
        lookback = max(1, self.live_inventory_basis_stablecoin_regime_lookback_samples)
        recent = list(self.live_inventory_stablecoin_basis_bps_samples)[-lookback:]
        recent_abs = [abs(value) for value in recent]
        recent_min_abs = min(recent_abs) if recent_abs else None
        recent_max_abs = max(recent_abs) if recent_abs else None
        recent_change_bps = None if recent_min_abs is None or recent_max_abs is None else recent_max_abs - recent_min_abs
        context = {
            "stablecoin_regime_entry_enabled": enabled,
            "stablecoin_regime_min_stablecoin_basis_bps": decimal_to_str(self.live_inventory_basis_min_stablecoin_basis_bps),
            "stablecoin_regime_buffer_bps": decimal_to_str(self.live_inventory_basis_stablecoin_regime_buffer_bps),
            "stablecoin_regime_min_normalized_edge_bps": decimal_to_str(self.live_inventory_basis_stablecoin_regime_min_normalized_edge_bps),
            "stablecoin_regime_lookback_samples": lookback,
            "stablecoin_regime_samples": len(recent),
            "stablecoin_regime_max_change_bps": decimal_to_str(self.live_inventory_basis_stablecoin_regime_max_change_bps),
            "stablecoin_regime_recent_min_abs_basis_bps": decimal_to_str(recent_min_abs),
            "stablecoin_regime_recent_max_abs_basis_bps": decimal_to_str(recent_max_abs),
            "stablecoin_regime_recent_change_bps": decimal_to_str(recent_change_bps),
            "stablecoin_regime_required_raw_edge_bps": decimal_to_str(required_raw_edge_bps),
            "stablecoin_regime_raw_margin_bps": decimal_to_str(None if raw_edge is None or required_raw_edge_bps is None else raw_edge - required_raw_edge_bps),
        }
        if not enabled:
            return False, {**context, "stablecoin_regime_reason": "disabled"}
        if stablecoin_basis_bps is None:
            return False, {**context, "stablecoin_regime_reason": "stablecoin_basis_unavailable"}
        if abs(stablecoin_basis_bps) < self.live_inventory_basis_min_stablecoin_basis_bps:
            return False, {**context, "stablecoin_regime_reason": "stablecoin_basis_below_min"}
        if len(recent) < lookback:
            return False, {**context, "stablecoin_regime_reason": "stablecoin_basis_insufficient_history"}
        if recent_min_abs is None or recent_min_abs < self.live_inventory_basis_min_stablecoin_basis_bps:
            return False, {**context, "stablecoin_regime_reason": "stablecoin_basis_not_persistent"}
        if recent_change_bps is not None and recent_change_bps > self.live_inventory_basis_stablecoin_regime_max_change_bps:
            return False, {**context, "stablecoin_regime_reason": "stablecoin_basis_too_unstable"}
        if raw_edge is None or required_raw_edge_bps is None or raw_edge < required_raw_edge_bps:
            return False, {**context, "stablecoin_regime_reason": "raw_edge_below_stablecoin_regime_requirement"}
        if normalized_edge_bps is None:
            return False, {**context, "stablecoin_regime_reason": "normalized_edge_unavailable"}
        if normalized_edge_bps < self.live_inventory_basis_stablecoin_regime_min_normalized_edge_bps:
            return False, {**context, "stablecoin_regime_reason": "normalized_edge_below_stablecoin_regime_min"}
        return True, {**context, "stablecoin_regime_reason": "ok"}

    def live_inventory_update_watch_candidate(
        self,
        *,
        direction: str,
        edge_bps: Decimal,
        quality_score_bps: Decimal,
        now: float,
    ) -> tuple[bool, dict[str, Any]]:
        if not self.live_inventory_basis_watch_candidate:
            return True, {"watch_candidate_enabled": False}
        if edge_bps < self.live_inventory_basis_watch_edge_bps:
            self.live_inventory_basis_watch_candidates.pop(direction, None)
            return False, {
                "watch_candidate_enabled": True,
                "watch_candidate_status": "below_watch_edge",
                "watch_edge_bps": decimal_to_str(self.live_inventory_basis_watch_edge_bps),
                "watch_promote_edge_bps": decimal_to_str(self.live_inventory_basis_watch_promote_edge_bps),
            }
        watch = self.live_inventory_basis_watch_candidates.get(direction)
        if watch is None or now - float(watch.get("created_at_monotonic") or now) > self.live_inventory_basis_watch_max_age_seconds:
            watch = {
                "created_at_monotonic": now,
                "first_edge_bps": edge_bps,
                "best_edge_bps": edge_bps,
                "best_quality_score_bps": quality_score_bps,
                "promote_confirm_count": 0,
            }
            self.live_inventory_basis_watch_candidates[direction] = watch
        watch["best_edge_bps"] = max(to_decimal(watch.get("best_edge_bps")) or edge_bps, edge_bps)
        watch["best_quality_score_bps"] = max(to_decimal(watch.get("best_quality_score_bps")) or quality_score_bps, quality_score_bps)
        promoted_sample = edge_bps >= self.live_inventory_basis_watch_promote_edge_bps and quality_score_bps >= self.live_inventory_basis_watch_min_quality_score_bps
        watch["promote_confirm_count"] = int(watch.get("promote_confirm_count") or 0) + 1 if promoted_sample else 0
        age_seconds = now - float(watch.get("created_at_monotonic") or now)
        context = {
            "watch_candidate_enabled": True,
            "watch_candidate_status": "promoted" if watch["promote_confirm_count"] >= self.live_inventory_basis_watch_confirm_samples else "watching",
            "watch_candidate_age_seconds": f"{age_seconds:.6f}",
            "watch_candidate_confirm_count": watch["promote_confirm_count"],
            "watch_candidate_required_confirm_samples": self.live_inventory_basis_watch_confirm_samples,
            "watch_edge_bps": decimal_to_str(self.live_inventory_basis_watch_edge_bps),
            "watch_promote_edge_bps": decimal_to_str(self.live_inventory_basis_watch_promote_edge_bps),
            "watch_min_quality_score_bps": decimal_to_str(self.live_inventory_basis_watch_min_quality_score_bps),
            "watch_best_edge_bps": decimal_to_str(watch.get("best_edge_bps")),
            "watch_best_quality_score_bps": decimal_to_str(watch.get("best_quality_score_bps")),
        }
        if watch["promote_confirm_count"] >= self.live_inventory_basis_watch_confirm_samples:
            return True, context
        return False, context

    async def fetch_live_inventory_stablecoin_context(self) -> dict[str, Any]:
        if not self.live_inventory_basis_stablecoin_normalization:
            return {"stablecoin_normalization_enabled": False}
        now = time.monotonic()
        cached_at = self.live_inventory_stablecoin_rate_cache.get("monotonic")
        if cached_at is not None and now - float(cached_at) <= self.live_inventory_basis_stablecoin_rate_ttl_seconds:
            return dict(self.live_inventory_stablecoin_rate_cache.get("context") or {})
        context: dict[str, Any] = {
            "stablecoin_normalization_enabled": True,
            "stablecoin_rate_source": "binance_usdcusdt",
            "stablecoin_rate_url": BINANCE_USDCUSDT_TICKER_URL,
        }
        try:
            response = await asyncio.to_thread(requests.get, BINANCE_USDCUSDT_TICKER_URL, timeout=3)
            response.raise_for_status()
            payload = response.json()
            usdcusdt = to_decimal(payload.get("price"))
            if usdcusdt is None or usdcusdt <= 0:
                raise ValueError(f"invalid USDCUSDT price: {payload!r}")
            usdt_per_usdc = usdcusdt
            stablecoin_basis_bps = (usdt_per_usdc - Decimal("1")) * Decimal("10000")
            context.update(
                {
                    "stablecoin_rate_status": "ok",
                    "usdcusdt_price": decimal_to_str(usdcusdt),
                    "usdt_per_usdc": decimal_to_str(usdt_per_usdc),
                    "stablecoin_basis_bps": decimal_to_str(stablecoin_basis_bps),
                    "stablecoin_rate_fetched_at": utc_now(),
                }
            )
        except Exception as exc:
            context.update({"stablecoin_rate_status": "unavailable", "stablecoin_rate_error": str(exc)})
        self.live_inventory_stablecoin_rate_cache = {"monotonic": now, "context": context}
        return context

    async def refresh_live_inventory_external_reference(self, asset: str) -> None:
        asset = asset.upper()
        context: dict[str, Any] = {
            "external_reference_asset": asset,
            "external_reference_source": "binance_book_ticker",
            "external_reference_status": "unsupported",
        }
        try:
            if asset != "ETH":
                return
            response = await asyncio.to_thread(
                requests.get,
                BINANCE_ETHUSDT_BOOK_TICKER_URL,
                timeout=3,
            )
            response.raise_for_status()
            payload = response.json()
            bid = to_decimal(payload.get("bidPrice"))
            ask = to_decimal(payload.get("askPrice"))
            if bid is None or ask is None or bid <= 0 or ask <= 0:
                raise ValueError(f"invalid ETHUSDT book ticker: {payload!r}")
            context.update(
                {
                    "external_reference_status": "ok",
                    "external_reference_bid": decimal_to_str(bid),
                    "external_reference_ask": decimal_to_str(ask),
                    "external_reference_mid": decimal_to_str((bid + ask) / Decimal("2")),
                    "external_reference_fetched_at": utc_now(),
                }
            )
        except Exception as exc:
            context.update(
                {
                    "external_reference_status": "unavailable",
                    "external_reference_error": str(exc),
                }
            )
        finally:
            self.live_inventory_external_reference_cache = {
                "monotonic": time.monotonic(),
                "context": context,
            }

    def live_inventory_external_reference_context(
        self,
        *,
        asset: str,
        var_mid: Decimal | None,
        lighter_mid: Decimal | None,
    ) -> dict[str, Any]:
        cache = getattr(self, "live_inventory_external_reference_cache", {})
        cached_at = float(cache.get("monotonic") or 0.0)
        task = getattr(self, "live_inventory_external_reference_task", None)
        if (
            time.monotonic() - cached_at >= 10.0
            and (task is None or task.done())
        ):
            self.live_inventory_external_reference_task = asyncio.create_task(
                self.refresh_live_inventory_external_reference(asset)
            )
        context = dict(cache.get("context") or {})
        reference_mid = to_decimal(context.get("external_reference_mid"))
        context["external_reference_var_mid_deviation_bps"] = decimal_to_str(
            self.live_inventory_price_drift_bps(var_mid, reference_mid)
        )
        context["external_reference_lighter_mid_deviation_bps"] = decimal_to_str(
            self.live_inventory_price_drift_bps(lighter_mid, reference_mid)
        )
        context["external_reference_shadow_only"] = True
        return context

    @staticmethod
    def normalize_usdc_price_to_usdt(price: Decimal, stablecoin_context: dict[str, Any]) -> Decimal | None:
        usdcusdt = to_decimal(stablecoin_context.get("usdcusdt_price"))
        if usdcusdt is None or usdcusdt <= 0:
            return None
        return price * usdcusdt

    def live_inventory_dynamic_entry_quality_buffer_bps(self, *, var_quote_age_seconds: float | None = None) -> Decimal:
        buffer = self.percentile_decimal(getattr(self, "live_inventory_exit_estimate_shortfall_bps_samples", []), 80) or Decimal("0")
        latency_p90 = self.percentile_decimal(getattr(self, "live_inventory_exit_fill_latency_ms_samples", []), 90)
        if (
            latency_p90 is not None
            and self.live_inventory_basis_latency_buffer_p90_ms > 0
            and latency_p90 > self.live_inventory_basis_latency_buffer_p90_ms
        ):
            buffer += self.live_inventory_basis_latency_buffer_bps
        if (
            var_quote_age_seconds is not None
            and self.live_inventory_basis_quote_age_buffer_ms > 0
            and Decimal(str(var_quote_age_seconds * 1000.0)) > self.live_inventory_basis_quote_age_buffer_ms
        ):
            buffer += self.live_inventory_basis_quote_age_buffer_bps
        return buffer

    def live_inventory_time_decayed_min_exit_pnl_bps(self, *, holding_samples: int, base_min_exit_pnl_bps: Decimal) -> Decimal:
        decay_samples = self.live_inventory_basis_time_decay_exit_samples
        floor = self.live_inventory_basis_time_decay_min_exit_pnl_bps
        if decay_samples <= 0 or holding_samples <= self.live_inventory_min_hold_samples:
            return base_min_exit_pnl_bps
        progress = min(Decimal("1"), Decimal(holding_samples - self.live_inventory_min_hold_samples) / Decimal(decay_samples))
        return base_min_exit_pnl_bps - (base_min_exit_pnl_bps - floor) * progress

    def live_inventory_signal_reverted_exit_min_pnl_bps(self, *, time_decayed_min_exit_pnl_bps: Decimal) -> Decimal:
        if getattr(self, "live_inventory_basis_reversion_mode", False):
            return self.live_inventory_basis_reversion_signal_exit_min_pnl_bps
        return max(
            time_decayed_min_exit_pnl_bps,
            self.live_inventory_basis_min_signal_reverted_exit_pnl_bps,
        )

    def should_log_live_inventory_exit_blocked(self, *, lot_id: Any, reason: str) -> bool:
        throttle = self.live_inventory_exit_blocked_log_throttle_seconds
        if throttle <= 0:
            return True
        key = (lot_id, reason)
        now = time.monotonic()
        last = self._last_live_inventory_exit_blocked_log.get(key)
        if last is not None and now - last < throttle:
            return False
        self._last_live_inventory_exit_blocked_log[key] = now
        return True

    @staticmethod
    def set_record_stage(
        record: OrderLifecycle,
        stage: str,
        *,
        failure_stage: str | None = None,
        failure_reason: str | None = None,
        clear_failure: bool = False,
    ) -> None:
        record.processing_stage = stage
        if not record.stage_history or record.stage_history[-1] != stage:
            record.stage_history.append(stage)
        record.last_updated_at = utc_now()
        if clear_failure:
            record.failure_stage = None
            record.failure_reason = None
        if failure_stage is not None:
            record.failure_stage = failure_stage
        if failure_reason is not None:
            record.failure_reason = failure_reason

    def is_observe_mode(self) -> bool:
        return self.mode == MODE_OBSERVE

    def is_dry_run_mode(self) -> bool:
        return self.mode == MODE_DRY_RUN

    def is_live_mode(self) -> bool:
        return self.mode == MODE_LIVE

    def is_paper_mode(self) -> bool:
        return self.mode == MODE_PAPER

    def is_auto_live_enabled(self) -> bool:
        return self.is_live_mode() and (self.auto_live_entry or self.auto_live_exit)

    def is_live_inventory_enabled(self) -> bool:
        return self.is_live_mode() and self.live_inventory

    def sync_live_inventory_memory_from_state(self) -> None:
        state = self.load_live_inventory_state()
        open_lots = state.get("open_lots")
        self.live_inventory_open_lots = open_lots if isinstance(open_lots, list) else []
        self.live_inventory_next_lot_id = int(state.get("next_lot_id") or 1)
        self.live_inventory_realized_pnl_usd = to_decimal(state.get("realized_pnl_usd")) or Decimal("0")
        self.live_inventory_completed_cycles = int(state.get("completed_cycles") or 0)
        self.live_inventory_v4_episode_id = state.get("v4_episode_id") or None
        self.live_inventory_v4_next_tranche_index = int(
            state.get("v4_next_tranche_index") or 1
        )
        self.live_inventory_v4_rearm_required = bool(
            state.get("v4_rearm_required", False)
        )
        self.live_inventory_v4_rearm_confirmation_count = int(
            state.get("v4_rearm_confirmation_count") or 0
        )
        self.live_inventory_v4_rearm_reason = state.get("v4_rearm_reason") or None
        self.live_inventory_v4_rearm_threshold_bps = to_decimal(
            state.get("v4_rearm_threshold_bps")
        )
        self.live_inventory_v4_last_exit_reason = (
            state.get("v4_last_exit_reason") or None
        )
        self.live_inventory_v4_last_exit_at = state.get("v4_last_exit_at") or None
        self.live_inventory_v4_batch_halted_reason = (
            state.get("v4_batch_halted_reason") or None
        )
        shadow_tranche = state.get("v4_shadow_tranche")
        self.live_inventory_v4_shadow_tranche = (
            shadow_tranche if isinstance(shadow_tranche, dict) else None
        )
        shadow_tranches = state.get("v4_shadow_tranches")
        self.live_inventory_v4_shadow_tranches = (
            {
                str(key): value
                for key, value in shadow_tranches.items()
                if isinstance(value, dict)
            }
            if isinstance(shadow_tranches, dict)
            else {}
        )
        self.live_inventory_v4_shadow_completed_keys = {
            str(value)
            for value in list(state.get("v4_shadow_completed_keys") or [])
            if value
        }
        self.live_inventory_basis_v4_shadow_tranches_state()
        self.live_inventory_v4_shadow_completed_episode_id = (
            state.get("v4_shadow_completed_episode_id") or None
        )

        if self.live_inventory_v4_shadow_completed_episode_id:
            legacy_level = self.live_inventory_basis_v4_shadow_level_key(
                LIVE_INVENTORY_BASIS_V4_SHADOW_TRANCHE_IMPROVEMENT_BPS
            )
            self.live_inventory_v4_shadow_completed_keys.add(
                self.live_inventory_basis_v4_shadow_completion_key(
                    self.live_inventory_v4_shadow_completed_episode_id,
                    legacy_level,
                )
            )
        if "v4_strong_single_enabled" in state:
            self.live_inventory_v4_strong_single_enabled = bool(
                state.get("v4_strong_single_enabled")
            )
        self.live_inventory_v4_strong_single_disabled_reason = (
            state.get("v4_strong_single_disabled_reason") or None
        )
        self.live_inventory_v4_strong_single_disabled_at = (
            state.get("v4_strong_single_disabled_at") or None
        )
        self.live_inventory_v4_portfolio_exit_lot_ids = {
            self.live_inventory_normalized_lot_id(value)
            for value in list(state.get("v4_portfolio_exit_lot_ids") or [])
        }
        current_lot_ids = {
            self.live_inventory_normalized_lot_id(lot.get("lot_id"))
            for lot in self.live_inventory_open_lots
            if isinstance(lot, dict) and lot.get("lot_id") is not None
        }
        self.live_inventory_v4_stale_portfolio_exit_lot_ids = sorted(
            self.live_inventory_v4_portfolio_exit_lot_ids - current_lot_ids
        )
        if self.live_inventory_v4_stale_portfolio_exit_lot_ids:
            self.live_inventory_v4_portfolio_exit_lot_ids = set()
        else:
            self.live_inventory_v4_portfolio_exit_lot_ids.intersection_update(
                current_lot_ids
            )
        portfolio_exit_context = state.get("v4_portfolio_exit_context")
        self.live_inventory_v4_portfolio_exit_context = (
            dict(portfolio_exit_context)
            if isinstance(portfolio_exit_context, dict)
            else {}
        )
        if not self.live_inventory_v4_portfolio_exit_lot_ids:
            self.live_inventory_v4_portfolio_exit_context = {}
        persisted_tier_states = state.get("v4_gradient_tier_states")
        if isinstance(persisted_tier_states, dict):
            self.live_inventory_v4_gradient_tier_states = {
                tier: {
                    "armed": bool(
                        (persisted_tier_states.get(str(tier)) or {}).get(
                            "armed",
                            True,
                        )
                    ),
                    "reset_seen": bool(
                        (persisted_tier_states.get(str(tier)) or {}).get(
                            "reset_seen",
                            False,
                        )
                    ),
                    **{
                        key: value
                        for key, value in (
                            persisted_tier_states.get(str(tier)) or {}
                        ).items()
                        if key in {"closed_at", "rearmed_at"}
                    },
                }
                for tier in range(
                    1,
                    LIVE_INVENTORY_BASIS_V4_REAL_GRADIENT_MAX_TIERS + 1,
                )
            }

    def sync_live_inventory_pnl_tracking_baseline(self) -> None:
        baseline_file = getattr(
            self,
            "live_inventory_pnl_baseline_file",
            None,
        )
        if baseline_file is None:
            return
        baseline = load_pnl_baseline(baseline_file)
        if baseline is None:
            return
        baseline_asset = str(baseline.get("asset") or "").upper()
        state_asset = self.live_inventory_state_asset().upper()
        if baseline_asset and state_asset and baseline_asset != state_asset:
            return
        self.live_inventory_pnl_tracking_started_at = (
            baseline.get("started_at") or None
        )
        self.live_inventory_pnl_tracking_realized_baseline_usd = to_decimal(
            baseline.get("realized_pnl_baseline_usd")
        )
        completed_baseline = baseline.get("completed_cycles_baseline")
        self.live_inventory_pnl_tracking_completed_cycles_baseline = (
            int(completed_baseline)
            if completed_baseline is not None
            else None
        )
        self.live_inventory_pnl_tracking_confirmed_pnl_usd = to_decimal(
            baseline.get("confirmed_pnl_usd")
        )
        self.live_inventory_pnl_tracking_completed_cycles = int(
            baseline.get("tracked_completed_cycles") or 0
        )
        self.live_inventory_pnl_beijing_day = (
            baseline.get("current_beijing_day") or None
        )
        self.live_inventory_pnl_daily_confirmed_pnl_usd = to_decimal(
            baseline.get("daily_confirmed_pnl_usd")
        )
        self.live_inventory_pnl_daily_completed_cycles = int(
            baseline.get("daily_tracked_completed_cycles") or 0
        )
        self.live_inventory_pnl_account_baseline_equity_usd = to_decimal(
            baseline.get("account_baseline_equity_usd")
        )
        self.live_inventory_pnl_account_baseline_at = (
            baseline.get("account_baseline_at") or None
        )

    def live_inventory_v4_episode_payload(self) -> dict[str, Any]:
        if not getattr(self, "live_inventory_basis_v4_mode", False):
            return {}
        strong_single_context = self.live_inventory_basis_v4_strong_single_context(
            effective_min_exit_pnl_bps=(
                self.live_inventory_basis_v4_effective_exit_target_bps()
            )
        )
        rearm_required = bool(
            getattr(self, "live_inventory_v4_rearm_required", False)
        )
        batch_halted_reason = getattr(
            self,
            "live_inventory_v4_batch_halted_reason",
            None,
        )
        if getattr(self, "live_inventory_open_lots", []):
            episode_state = "active"
        elif batch_halted_reason:
            episode_state = "halted"
        elif rearm_required:
            episode_state = "disarmed"
        else:
            episode_state = "armed"
        return {
            "v4_episode_state": episode_state,
            "v4_episode_id": getattr(self, "live_inventory_v4_episode_id", None),
            "v4_next_tranche_index": int(
                getattr(self, "live_inventory_v4_next_tranche_index", 1)
            ),
            "v4_shadow_gradient_enabled": bool(
                getattr(self, "live_inventory_basis_v4_shadow_gradient", False)
            ),
            "v4_shadow_tranche_active": bool(
                self.live_inventory_basis_v4_shadow_tranches_state()
            ),
            "v4_shadow_active_levels_bps": sorted(
                self.live_inventory_basis_v4_shadow_tranches_state(),
                key=Decimal,
            ),
            "v4_shadow_tranche_index": LIVE_INVENTORY_BASIS_V4_SHADOW_TRANCHE_INDEX,
            "v4_shadow_tranche_improvement_bps": decimal_to_str(
                LIVE_INVENTORY_BASIS_V4_SHADOW_TRANCHE_IMPROVEMENT_BPS
            ),
            "v4_shadow_tranche_improvement_levels_bps": [
                decimal_to_str(value)
                for value in LIVE_INVENTORY_BASIS_V4_SHADOW_TRANCHE_IMPROVEMENT_LEVELS_BPS
            ],
            "v4_exit_confirmation_policy": "latest_and_2_of_3",
            "v4_exit_confirmation_required": (
                LIVE_INVENTORY_BASIS_V4_EXIT_CONFIRM_SAMPLES
            ),
            "v4_exit_confirmation_window": (
                LIVE_INVENTORY_BASIS_V4_EXIT_CONFIRM_WINDOW_SAMPLES
            ),
            "v4_portfolio_exit_active": bool(
                getattr(self, "live_inventory_v4_portfolio_exit_lot_ids", set())
            ),
            "v4_portfolio_exit_lot_ids": sorted(
                getattr(self, "live_inventory_v4_portfolio_exit_lot_ids", set())
            ),
            "v4_portfolio_exit_context": dict(
                getattr(self, "live_inventory_v4_portfolio_exit_context", {})
            ),
            "v4_gradient_tier_states": {
                str(tier): dict(value)
                for tier, value in getattr(
                    self,
                    "live_inventory_v4_gradient_tier_states",
                    {},
                ).items()
            },
            "v4_strong_single_enabled": bool(
                getattr(self, "live_inventory_v4_strong_single_enabled", True)
            ),
            "v4_strong_single_disabled_reason": getattr(
                self,
                "live_inventory_v4_strong_single_disabled_reason",
                None,
            ),
            "v4_strong_single_disabled_at": getattr(
                self,
                "live_inventory_v4_strong_single_disabled_at",
                None,
            ),
            "v4_strong_single_shortfall_sample_count": strong_single_context[
                "sample_count"
            ],
            "v4_strong_single_shortfall_min_samples": strong_single_context[
                "min_samples"
            ],
            "v4_strong_single_shortfall_ready": strong_single_context["ready"],
            "v4_strong_single_shortfall_raw_p80_bps": decimal_to_str(
                strong_single_context["raw_p80_bps"]
            ),
            "v4_strong_single_shortfall_reserve_bps": decimal_to_str(
                strong_single_context["mode_reserve_bps"]
            ),
            "v4_strong_single_threshold_bps": decimal_to_str(
                strong_single_context["threshold_bps"]
            ),
            "v4_rearm_required": rearm_required,
            "v4_rearm_confirmation_count": (
                int(
                    getattr(
                        self,
                        "live_inventory_v4_rearm_confirmation_count",
                        0,
                    )
                )
            ),
            "v4_rearm_confirm_samples": LIVE_INVENTORY_BASIS_V4_REARM_CONFIRM_SAMPLES,
            "v4_rearm_buffer_bps": decimal_to_str(
                LIVE_INVENTORY_BASIS_V4_REARM_BUFFER_BPS
            ),
            "v4_rearm_reason": getattr(
                self,
                "live_inventory_v4_rearm_reason",
                None,
            ),
            "v4_rearm_threshold_bps": decimal_to_str(
                getattr(self, "live_inventory_v4_rearm_threshold_bps", None)
            ),
            "v4_last_exit_reason": getattr(
                self,
                "live_inventory_v4_last_exit_reason",
                None,
            ),
            "v4_last_exit_at": getattr(
                self,
                "live_inventory_v4_last_exit_at",
                None,
            ),
            "v4_batch_halted_reason": batch_halted_reason,
        }

    @staticmethod
    def _read_last_json_line(path: Path) -> dict[str, Any] | None:
        try:
            with path.open("rb") as handle:
                handle.seek(0, 2)
                position = handle.tell()
                buffer = bytearray()
                while position > 0:
                    position -= 1
                    handle.seek(position)
                    byte = handle.read(1)
                    if byte == b"\n" and buffer:
                        break
                    if byte not in {b"\n", b"\r"}:
                        buffer.extend(byte)
                if not buffer:
                    return None
                payload = json.loads(bytes(reversed(buffer)).decode("utf-8"))
                return payload if isinstance(payload, dict) else None
        except (OSError, ValueError, json.JSONDecodeError):
            return None

    def live_inventory_robinhood_regime_context(
        self,
        *,
        asset: str,
        primary_short_edge_bps: Decimal,
    ) -> dict[str, Any]:
        now_monotonic = time.monotonic()
        cached_at = float(
            getattr(self, "live_inventory_robinhood_context_cached_at", 0.0)
            or 0.0
        )
        cached = getattr(self, "live_inventory_robinhood_context_cache", {})
        if cached and now_monotonic - cached_at < 30.0:
            return dict(cached)
        context: dict[str, Any] = {
            "v4_robinhood_status": "unavailable",
            "v4_robinhood_fresh": False,
            "v4_robinhood_threshold_penalty_bps": "0",
        }
        output_dir = getattr(self, "output_dir", None)
        if output_dir is None:
            return context
        try:
            health = json.loads(
                (output_dir / "robinhood_basis_health.json").read_text(
                    encoding="utf-8"
                )
            )
        except (OSError, ValueError, json.JSONDecodeError):
            health = {}
        last_sample_at = self._parse_iso_ts(str(health.get("last_sample_at") or ""))
        sample_age_seconds = (
            max(
                0.0,
                (datetime.now(timezone.utc) - last_sample_at).total_seconds(),
            )
            if last_sample_at is not None
            else None
        )
        fresh = bool(
            health.get("status") == "running"
            and health.get("book_ready") is True
            and not health.get("errors")
            and sample_age_seconds is not None
            and sample_age_seconds <= 120.0
        )
        sample: dict[str, Any] | None = None
        if fresh:
            sample_day = last_sample_at.astimezone(timezone.utc).date().isoformat()
            sample = self._read_last_json_line(
                output_dir
                / "robinhood_basis_samples"
                / asset.upper()
                / f"{sample_day}.jsonl"
            )
        robinhood_short_edge = to_decimal(
            sample.get("short_edge_bps") if sample else None
        )
        divergence = (
            primary_short_edge_bps - robinhood_short_edge
            if robinhood_short_edge is not None
            else None
        )
        context = {
            "v4_robinhood_status": (
                "fresh" if fresh and sample is not None else "stale_or_missing"
            ),
            "v4_robinhood_fresh": bool(fresh and sample is not None),
            "v4_robinhood_sample_at": (
                sample.get("logged_at") if sample else health.get("last_sample_at")
            ),
            "v4_robinhood_sample_age_seconds": sample_age_seconds,
            "v4_robinhood_short_edge_bps": decimal_to_str(robinhood_short_edge),
            "v4_robinhood_edge_divergence_bps": decimal_to_str(divergence),
            "v4_robinhood_threshold_penalty_bps": "0",
            "v4_robinhood_policy": "independent_observation_only",
        }
        self.live_inventory_robinhood_context_cached_at = now_monotonic
        self.live_inventory_robinhood_context_cache = dict(context)
        return context

    def live_inventory_state_asset(self) -> str:
        for lot in getattr(self, "live_inventory_open_lots", []) or []:
            if isinstance(lot, dict) and lot.get("asset"):
                return str(lot.get("asset")).upper()
        if len(getattr(self, "live_allowed_assets", set()) or set()) == 1:
            return next(iter(self.live_allowed_assets)).upper()
        return "BTC"

    def pending_live_inventory_actions_payload(self) -> list[dict[str, Any]]:
        actions: list[dict[str, Any]] = []
        for item in getattr(self, "pending_live_inventory_var_fill_matches", []) or []:
            context = item.context if isinstance(item.context, dict) else {}
            actions.append(
                {
                    "asset": item.asset.upper(),
                    "side": item.side.lower(),
                    "qty": decimal_to_str(item.qty),
                    "lot_id": item.lot_id,
                    "role": item.role,
                    "direction": context.get("direction"),
                    "submitted_at": context.get("submitted_at"),
                    "rfq_id": context.get("rfq_id"),
                    "submitted_order_id": context.get("submitted_order_id"),
                    "lighter_started": bool(context.get("lighter_started")),
                    "lighter_record_key": context.get("lighter_record_key"),
                }
            )
        return actions

    @staticmethod
    def live_inventory_position_qty_tolerance(expected_qty: Decimal) -> Decimal:
        return max(Decimal("0.00000001"), abs(expected_qty) * Decimal("0.0001"))

    async def fetch_lighter_account(self) -> dict[str, Any]:
        if self.account_index is None:
            raise RuntimeError("LIGHTER_ACCOUNT_INDEX is not loaded")
        client = self.initialize_lighter_client()
        from lighter import AccountApi

        result = await AccountApi(client.api_client).account(
            by="index",
            value=str(self.account_index),
            _request_timeout=10.0,
        )
        if hasattr(result, "to_dict"):
            result = result.to_dict()
        elif hasattr(result, "model_dump"):
            result = result.model_dump(mode="json")
        if not isinstance(result, dict):
            raise RuntimeError("Lighter account response is not an object")
        if result.get("code") not in {None, 0, 200}:
            raise RuntimeError(
                f"Lighter account request failed: code={result.get('code')} message={result.get('message')}"
            )
        return result

    def apply_live_inventory_account_recovery_gate(
        self,
        context: dict[str, Any],
        *,
        advance_confirmation: bool = False,
    ) -> dict[str, Any]:
        result = dict(context)
        fresh = bool(
            result.get("variational_account_snapshot_fresh")
            and result.get("variational_equity_usd") not in (None, "")
            and result.get("lighter_equity_usd") not in (None, "")
        )
        required_samples = max(
            1,
            int(
                getattr(
                    self,
                    "live_inventory_account_recovery_confirm_samples",
                    LIVE_INVENTORY_ACCOUNT_RECOVERY_CONFIRM_SAMPLES,
                )
            ),
        )
        if not fresh:
            self.live_inventory_account_recovery_required = True
            self.live_inventory_account_recovery_confirm_count = 0
            self.live_inventory_account_recovery_reason = str(
                result.get("risk_reason")
                or result.get("variational_account_snapshot_freshness_reason")
                or "variational_account_snapshot_stale"
            )
            self.clear_live_inventory_entry_confirmations_after_account_recovery()
        elif getattr(self, "live_inventory_account_recovery_required", False):
            if advance_confirmation:
                self.live_inventory_account_recovery_confirm_count = min(
                    required_samples,
                    int(
                        getattr(
                            self,
                            "live_inventory_account_recovery_confirm_count",
                            0,
                        )
                    )
                    + 1,
                )
            if self.live_inventory_account_recovery_confirm_count >= required_samples:
                self.live_inventory_account_recovery_required = False
                self.live_inventory_account_recovery_reason = None
                self.clear_live_inventory_entry_confirmations_after_account_recovery()
            else:
                result["risk_action"] = "block_entry"
                result["risk_reason"] = (
                    "variational_account_recovery_confirmation_pending"
                )
                self.clear_live_inventory_entry_confirmations_after_account_recovery()

        result["account_recovery_required"] = bool(
            getattr(self, "live_inventory_account_recovery_required", False)
        )
        result["account_recovery_confirm_count"] = int(
            getattr(
                self,
                "live_inventory_account_recovery_confirm_count",
                0,
            )
        )
        result["account_recovery_confirm_samples"] = required_samples
        result["account_recovery_reason"] = getattr(
            self,
            "live_inventory_account_recovery_reason",
            None,
        )
        return result

    def clear_live_inventory_entry_confirmations_after_account_recovery(
        self,
    ) -> None:
        entry_confirmations = getattr(
            self,
            "live_inventory_basis_entry_confirm_counts",
            None,
        )
        if isinstance(entry_confirmations, dict):
            entry_confirmations.clear()
        gradient_window = getattr(
            self,
            "live_inventory_v4_gradient_entry_tier_window",
            None,
        )
        if gradient_window is not None and hasattr(gradient_window, "clear"):
            gradient_window.clear()

    async def live_inventory_account_risk_context(
        self,
        *,
        proposed_notional_usd: Decimal | None = None,
        advance_recovery_confirmation: bool = False,
    ) -> dict[str, Any]:
        if not hasattr(self, "live_inventory_max_venue_leverage"):
            return {
                "asset": self.live_inventory_state_asset(),
                "risk_action": "normal",
                "risk_reason": "account_risk_not_configured",
            }
        monitor = getattr(getattr(self, "runtime", None), "monitor", None)
        monitor_lock = getattr(monitor, "_lock", None)
        if monitor_lock is not None:
            async with monitor_lock:
                portfolio_summary = dict(
                    getattr(monitor, "portfolio_summary", {}) or {}
                )
        else:
            portfolio_summary = getattr(monitor, "portfolio_summary", {})
        if not isinstance(portfolio_summary, dict):
            portfolio_summary = {}
        variational_metrics = extract_variational_account_metrics(portfolio_summary)
        variational_freshness = account_snapshot_freshness(
            portfolio_summary.get("published_at")
        )
        raw_variational_equity = to_decimal(
            variational_metrics.get("equity_usd")
        )
        if not variational_freshness["fresh"]:
            variational_metrics = dict(variational_metrics)
            variational_metrics["equity_usd"] = None
        lighter_metrics: dict[str, Any]
        try:
            lighter_metrics = extract_lighter_account_metrics(
                await self.fetch_lighter_account()
            )
        except Exception as exc:
            lighter_metrics = extract_lighter_account_metrics(None)
            lighter_metrics["risk_fetch_error"] = f"{type(exc).__name__}:{exc}"
        context = account_risk_context(
            variational_metrics=variational_metrics,
            lighter_metrics=lighter_metrics,
            current_notional_usd=self.live_inventory_open_notional_usd(),
            proposed_notional_usd=proposed_notional_usd,
            max_venue_leverage=self.live_inventory_max_venue_leverage,
            margin_warning_pct=self.live_inventory_margin_warning_pct,
            margin_block_entry_pct=self.live_inventory_margin_block_entry_pct,
            margin_reduce_pct=self.live_inventory_margin_reduce_pct,
            margin_emergency_pct=self.live_inventory_margin_emergency_pct,
            balance_warning_ratio=self.live_inventory_equity_balance_warning_ratio,
            balance_block_ratio=self.live_inventory_equity_balance_block_ratio,
        )
        context["asset"] = self.live_inventory_state_asset()
        context["open_lots_total"] = len(self.live_inventory_open_lots)
        context["variational_account_snapshot_fresh"] = variational_freshness[
            "fresh"
        ]
        context["variational_account_snapshot_age_seconds"] = (
            variational_freshness["age_seconds"]
        )
        context["variational_account_snapshot_max_age_seconds"] = (
            variational_freshness["max_age_seconds"]
        )
        context["variational_account_snapshot_freshness_reason"] = (
            variational_freshness["reason"]
        )
        context["variational_raw_equity_usd"] = decimal_to_str(
            raw_variational_equity
        )
        if not variational_freshness["fresh"]:
            context["risk_action"] = "block_entry"
            context["risk_reason"] = "variational_account_snapshot_stale"
        if lighter_metrics.get("risk_fetch_error"):
            context["lighter_risk_fetch_error"] = lighter_metrics["risk_fetch_error"]
        return self.apply_live_inventory_account_recovery_gate(
            context,
            advance_confirmation=advance_recovery_confirmation,
        )

    async def live_inventory_account_risk_loop(self) -> None:
        while not self.stop_flag:
            try:
                context = await self.live_inventory_account_risk_context(
                    advance_recovery_confirmation=True
                )
                self.live_inventory_account_risk_latest_context = dict(context)
                action = str(context.get("risk_action") or "normal")
                reason = str(context.get("risk_reason") or "account_risk_normal")
                if action in {"force_reduce", "emergency_exit"} and self.live_inventory_open_lots:
                    self.live_inventory_account_risk_exit_reason = reason
                    self.live_inventory_account_risk_exit_action = action
                elif action not in {"force_reduce", "emergency_exit"}:
                    self.live_inventory_account_risk_exit_reason = None
                    self.live_inventory_account_risk_exit_action = None
                alert_key = (action, reason)
                if action != "normal" and alert_key != self.live_inventory_account_risk_last_alert_key:
                    self.live_inventory_account_risk_last_alert_key = alert_key
                    await self.append_live_inventory_log(
                        "live_inventory_account_risk_alert",
                        context,
                    )
                elif action == "normal":
                    if self.live_inventory_account_risk_last_alert_key is not None:
                        await self.append_live_inventory_log(
                            "live_inventory_account_risk_recovered",
                            context,
                        )
                    self.live_inventory_account_risk_last_alert_key = None
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                self.logger.warning(
                    "live_inventory_account_risk_check_failed error=%s",
                    f"{type(exc).__name__}:{exc}",
                )
            await asyncio.sleep(
                LIVE_INVENTORY_ACCOUNT_RISK_OPEN_INTERVAL_SECONDS
                if self.live_inventory_open_lots
                else LIVE_INVENTORY_ACCOUNT_RISK_INTERVAL_SECONDS
            )

    async def capture_live_inventory_account_snapshot(
        self,
        *,
        stage: str,
        asset: str,
        lot_id: Any = None,
        lighter_account_result: dict[str, Any] | None = None,
        settle_seconds: float = 0.0,
    ) -> None:
        requested_at = utc_now()
        if settle_seconds > 0:
            await asyncio.sleep(settle_seconds)
        errors: dict[str, str] = {}
        monitor = getattr(getattr(self, "runtime", None), "monitor", None)
        monitor_lock = getattr(monitor, "_lock", None)
        if monitor_lock is not None:
            async with monitor_lock:
                portfolio_summary = dict(
                    getattr(monitor, "portfolio_summary", {}) or {}
                )
        else:
            portfolio_summary = getattr(monitor, "portfolio_summary", {})
        if not isinstance(portfolio_summary, dict):
            portfolio_summary = {}
        variational_metrics = extract_variational_account_metrics(
            portfolio_summary
        )
        variational_freshness = account_snapshot_freshness(
            portfolio_summary.get("published_at")
        )
        if variational_metrics.get("equity_usd") is None:
            errors["variational"] = "portfolio_summary_balance_missing"
        elif not variational_freshness["fresh"]:
            errors["variational"] = "portfolio_summary_stale"

        if lighter_account_result is None:
            try:
                lighter_account_result = await self.fetch_lighter_account()
            except Exception as exc:
                errors["lighter"] = f"{type(exc).__name__}:{exc}"
        lighter_metrics = extract_lighter_account_metrics(
            lighter_account_result
        )
        if (
            lighter_metrics.get("equity_usd") is None
            and "lighter" not in errors
        ):
            errors["lighter"] = "account_collateral_missing"

        raw_variational_equity = to_decimal(
            variational_metrics.get("equity_usd")
        )
        variational_equity = (
            raw_variational_equity
            if variational_freshness["fresh"]
            else None
        )
        lighter_equity = to_decimal(lighter_metrics.get("equity_usd"))
        total_equity = (
            variational_equity + lighter_equity
            if variational_equity is not None and lighter_equity is not None
            else None
        )
        equity_balance_ratio = (
            min(variational_equity, lighter_equity)
            / max(variational_equity, lighter_equity)
            if variational_equity is not None
            and lighter_equity is not None
            and variational_equity > 0
            and lighter_equity > 0
            else None
        )
        open_lots_total = len(
            getattr(self, "live_inventory_open_lots", []) or []
        )
        captured_at = utc_now()
        await self.append_live_inventory_log(
            "live_inventory_account_snapshot",
            {
                "asset": asset.upper(),
                "lot_id": lot_id,
                "snapshot_stage": stage,
                "snapshot_requested_at": requested_at,
                "snapshot_captured_at": captured_at,
                "snapshot_settle_seconds": settle_seconds,
                "snapshot_status": "complete" if not errors else "partial",
                "snapshot_errors": errors,
                "open_lots_total": open_lots_total,
                "account_snapshot_flat": open_lots_total == 0,
                "variational_balance_usd": decimal_to_str(
                    to_decimal(variational_metrics.get("balance_usd"))
                ),
                "variational_upnl_usd": decimal_to_str(
                    to_decimal(variational_metrics.get("upnl_usd"))
                ),
                "variational_equity_usd": decimal_to_str(
                    variational_equity
                ),
                "variational_raw_equity_usd": decimal_to_str(
                    raw_variational_equity
                ),
                "variational_equity_formula": variational_metrics.get(
                    "equity_formula"
                ),
                "variational_initial_margin_usage_pct": decimal_to_str(
                    to_decimal(variational_metrics.get("initial_margin_usage_pct"))
                ),
                "variational_maintenance_margin_usage_pct": decimal_to_str(
                    to_decimal(
                        variational_metrics.get("maintenance_margin_usage_pct")
                    )
                ),
                "variational_published_at": portfolio_summary.get(
                    "published_at"
                ),
                "variational_snapshot_fresh": variational_freshness["fresh"],
                "variational_snapshot_age_seconds": (
                    variational_freshness["age_seconds"]
                ),
                "variational_snapshot_max_age_seconds": (
                    variational_freshness["max_age_seconds"]
                ),
                "variational_snapshot_freshness_reason": (
                    variational_freshness["reason"]
                ),
                "lighter_collateral_usd": decimal_to_str(
                    to_decimal(lighter_metrics.get("collateral_usd"))
                ),
                "lighter_available_balance_usd": decimal_to_str(
                    to_decimal(
                        lighter_metrics.get("available_balance_usd")
                    )
                ),
                "lighter_total_asset_value_usd": decimal_to_str(
                    to_decimal(
                        lighter_metrics.get("total_asset_value_usd")
                    )
                ),
                "lighter_equity_usd": decimal_to_str(lighter_equity),
                "lighter_equity_formula": lighter_metrics.get(
                    "equity_formula"
                ),
                "lighter_initial_margin_usage_pct": decimal_to_str(
                    to_decimal(lighter_metrics.get("initial_margin_usage_pct"))
                ),
                "lighter_maintenance_margin_usage_pct": decimal_to_str(
                    to_decimal(
                        lighter_metrics.get("maintenance_margin_usage_pct")
                    )
                ),
                "combined_equity_usd": decimal_to_str(total_equity),
                "equity_balance_ratio": decimal_to_str(equity_balance_ratio),
            },
        )
        if (
            stage in {"startup_flat", "exit_confirmed_flat"}
            and total_equity is not None
            and open_lots_total == 0
            and not errors
        ):
            baseline_file = getattr(
                self,
                "live_inventory_pnl_baseline_file",
                None,
            )
            tracking_baseline = (
                load_pnl_baseline(baseline_file)
                if baseline_file is not None
                else None
            )
            if tracking_baseline is not None:
                if stage == "exit_confirmed_flat":
                    actual_payload = getattr(
                        self,
                        "live_inventory_last_actual_pnl_payload",
                        None,
                    ) or {}
                    if (
                        self.live_inventory_normalized_lot_id(
                            actual_payload.get("lot_id")
                        )
                        == self.live_inventory_normalized_lot_id(lot_id)
                        and actual_payload.get("actual_pnl_status")
                        == "lighter_final_fill_confirmed"
                        and actual_payload.get("actual_pnl_usd") is not None
                    ):
                        record_pnl_cycle(
                            baseline_file,
                            run_id=str(
                                getattr(self, "live_inventory_run_id", "unknown")
                            ),
                            asset=asset,
                            lot_id=lot_id,
                            actual_pnl_usd=actual_payload.get("actual_pnl_usd"),
                            observed_at=(
                                actual_payload.get("logged_at") or captured_at
                            ),
                        )
                        tracking_baseline = (
                            load_pnl_baseline(baseline_file)
                            or tracking_baseline
                        )
                baseline_equity = to_decimal(
                    tracking_baseline.get("account_baseline_equity_usd")
                )
                confirmed_pnl = to_decimal(
                    tracking_baseline.get("confirmed_pnl_usd")
                ) or Decimal("0")
                recorded_cashflow = to_decimal(
                    tracking_baseline.get("external_cashflow_usd")
                ) or Decimal("0")
                unexplained_change = (
                    total_equity
                    - baseline_equity
                    - confirmed_pnl
                    - recorded_cashflow
                    if baseline_equity is not None
                    else Decimal("0")
                )
                cashflow_threshold = (
                    max(Decimal("1"), baseline_equity * Decimal("0.02"))
                    if baseline_equity is not None
                    else None
                )
                if (
                    cashflow_threshold is not None
                    and abs(unexplained_change) >= cashflow_threshold
                ):
                    record_external_cashflow(
                        baseline_file,
                        amount_usd=unexplained_change,
                        observed_at=captured_at,
                        reason=(
                            "startup_flat_unexplained_equity_change"
                            if stage == "startup_flat"
                            else "runtime_flat_unexplained_equity_change"
                        ),
                    )
                    await self.append_live_inventory_log(
                        "live_inventory_external_cashflow_detected",
                        {
                            "asset": asset.upper(),
                            "external_cashflow_usd": decimal_to_str(
                                unexplained_change
                            ),
                            "combined_equity_usd": decimal_to_str(total_equity),
                            "account_baseline_equity_usd": decimal_to_str(
                                baseline_equity
                            ),
                            "confirmed_pnl_usd": decimal_to_str(confirmed_pnl),
                            "prior_external_cashflow_usd": decimal_to_str(
                                recorded_cashflow
                            ),
                            "detection_threshold_usd": decimal_to_str(
                                cashflow_threshold
                            ),
                            "snapshot_stage": stage,
                        },
                    )
                set_pnl_account_baseline(
                    baseline_file,
                    combined_equity_usd=total_equity,
                    captured_at=captured_at,
                )
                self.sync_live_inventory_pnl_tracking_baseline()
            else:
                self.live_inventory_pnl_account_baseline_equity_usd = (
                    total_equity
                )
                self.live_inventory_pnl_account_baseline_at = captured_at
        if stage == "exit_confirmed_flat":
            await self.append_live_inventory_log(
                "live_inventory_pnl_summary",
                self.live_inventory_pnl_summary_payload(
                    asset=asset,
                    lot_id=lot_id,
                    variational_equity_usd=variational_equity,
                    lighter_equity_usd=lighter_equity,
                    combined_equity_usd=total_equity,
                    captured_at=captured_at,
                    account_snapshot_flat=open_lots_total == 0,
                ),
            )

    def live_inventory_pnl_summary_payload(
        self,
        *,
        asset: str,
        lot_id: Any,
        variational_equity_usd: Decimal | None,
        lighter_equity_usd: Decimal | None,
        combined_equity_usd: Decimal | None,
        captured_at: str,
        account_snapshot_flat: bool = True,
    ) -> dict[str, Any]:
        actual_payload = getattr(
            self,
            "live_inventory_last_actual_pnl_payload",
            None,
        ) or {}
        actual_lot_id = self.live_inventory_normalized_lot_id(
            actual_payload.get("lot_id")
        )
        expected_lot_id = self.live_inventory_normalized_lot_id(lot_id)
        cycle_actual_pnl = (
            to_decimal(actual_payload.get("actual_pnl_usd"))
            if actual_lot_id == expected_lot_id
            and actual_payload.get("actual_pnl_status")
            == "lighter_final_fill_confirmed"
            else None
        )
        baseline_file = getattr(
            self,
            "live_inventory_pnl_baseline_file",
            None,
        )
        if baseline_file is not None and cycle_actual_pnl is not None:
            record_pnl_cycle(
                baseline_file,
                run_id=str(getattr(self, "live_inventory_run_id", "unknown")),
                asset=asset,
                lot_id=lot_id,
                actual_pnl_usd=cycle_actual_pnl,
                observed_at=(actual_payload.get("logged_at") or captured_at),
            )
            self.sync_live_inventory_pnl_tracking_baseline()
        realized_pnl = to_decimal(
            getattr(self, "live_inventory_realized_pnl_usd", None)
        )
        run_start_pnl = to_decimal(
            getattr(
                self,
                "live_inventory_v4_run_start_realized_pnl_usd",
                None,
            )
        )
        tracking_start_pnl = to_decimal(
            getattr(
                self,
                "live_inventory_pnl_tracking_realized_baseline_usd",
                None,
            )
        )
        run_actual_pnl = (
            getattr(
                self,
                "live_inventory_pnl_tracking_confirmed_pnl_usd",
                None,
            )
            if getattr(
                self,
                "live_inventory_pnl_tracking_confirmed_pnl_usd",
                None,
            )
            is not None
            else realized_pnl - tracking_start_pnl
            if realized_pnl is not None and tracking_start_pnl is not None
            else realized_pnl - run_start_pnl
            if realized_pnl is not None and run_start_pnl is not None
            else cycle_actual_pnl
        )
        daily_actual_pnl = (
            getattr(
                self,
                "live_inventory_pnl_daily_confirmed_pnl_usd",
                None,
            )
            if getattr(
                self,
                "live_inventory_pnl_daily_confirmed_pnl_usd",
                None,
            )
            is not None
            else cycle_actual_pnl
        )
        baseline_equity = to_decimal(
            getattr(
                self,
                "live_inventory_pnl_account_baseline_equity_usd",
                None,
            )
        )
        tracking_baseline = (
            load_pnl_baseline(baseline_file)
            if baseline_file is not None
            else None
        )
        external_cashflow = to_decimal(
            tracking_baseline.get("external_cashflow_usd")
            if tracking_baseline is not None
            else None
        ) or Decimal("0")
        raw_account_change = (
            combined_equity_usd - baseline_equity
            if account_snapshot_flat
            and combined_equity_usd is not None
            and baseline_equity is not None
            else None
        )
        account_net_change = (
            raw_account_change - external_cashflow
            if raw_account_change is not None
            else None
        )
        configured_capital = to_decimal(os.getenv("PNL_REPORT_CAPITAL_USD"))
        if configured_capital is not None and configured_capital > 0:
            capital_usd = configured_capital
            capital_source = "PNL_REPORT_CAPITAL_USD"
        else:
            capital_usd = baseline_equity
            capital_source = (
                "startup_flat_combined_equity"
                if baseline_equity is not None
                else "unavailable"
            )
        pnl_for_return = (
            account_net_change
            if account_net_change is not None
            else run_actual_pnl
        )
        pnl_source = (
            "account_equity_delta"
            if account_net_change is not None
            else "confirmed_pair_fills"
        )
        return_pct = (
            pnl_for_return / capital_usd * Decimal("100")
            if pnl_for_return is not None
            and capital_usd is not None
            and capital_usd > 0
            else None
        )
        daily_return_pct = (
            daily_actual_pnl / capital_usd * Decimal("100")
            if daily_actual_pnl is not None
            and capital_usd is not None
            and capital_usd > 0
            else None
        )
        started_at = (
            getattr(
                self,
                "live_inventory_pnl_account_baseline_at",
                None,
            )
            or getattr(
                self,
                "live_inventory_pnl_tracking_started_at",
                None,
            )
        )
        started = parse_utc_iso(started_at)
        finished = parse_utc_iso(captured_at)
        covered_beijing_days = beijing_calendar_days(started, finished)
        elapsed_days = covered_beijing_days
        annualized_pct = (
            return_pct * Decimal("365") / elapsed_days
            if return_pct is not None
            and elapsed_days is not None
            and elapsed_days > 0
            else None
        )
        latest_risk = getattr(
            self,
            "live_inventory_account_risk_latest_context",
            {},
        )
        return {
            "asset": asset.upper(),
            "lot_id": lot_id,
            "summary_status": (
                "complete"
                if account_snapshot_flat
                and combined_equity_usd is not None
                and baseline_equity is not None
                and cycle_actual_pnl is not None
                else "partial"
            ),
            "account_snapshot_flat": account_snapshot_flat,
            "cycle_actual_pnl_usd": decimal_to_str(cycle_actual_pnl),
            "cycle_actual_pnl_bps": actual_payload.get("actual_pnl_bps"),
            "exit_gradient_tier": actual_payload.get("exit_gradient_tier"),
            "market_gradient_tier": actual_payload.get(
                "market_gradient_tier"
            ),
            "closed_child_lots": actual_payload.get(
                "portfolio_component_lot_count"
            ),
            "remaining_child_lots": actual_payload.get(
                "remaining_child_lots"
            ),
            "remaining_notional_usd": actual_payload.get(
                "remaining_notional_usd"
            ),
            "run_actual_pnl_usd": decimal_to_str(run_actual_pnl),
            "beijing_day": (
                getattr(self, "live_inventory_pnl_beijing_day", None)
                or beijing_day(finished)
            ),
            "reporting_timezone": PNL_REPORTING_TIMEZONE,
            "beijing_day_actual_pnl_usd": decimal_to_str(daily_actual_pnl),
            "beijing_day_return_pct": decimal_to_str(daily_return_pct),
            "beijing_day_completed_cycles": getattr(
                self,
                "live_inventory_pnl_daily_completed_cycles",
                None,
            ),
            "completed_cycles": (
                getattr(
                    self,
                    "live_inventory_pnl_tracking_completed_cycles",
                    None,
                )
                if getattr(
                    self,
                    "live_inventory_pnl_tracking_completed_cycles",
                    None,
                )
                is not None
                else getattr(
                    self,
                    "live_inventory_completed_cycles",
                    None,
                )
            ),
            "variational_equity_usd": decimal_to_str(
                variational_equity_usd
            ),
            "lighter_equity_usd": decimal_to_str(lighter_equity_usd),
            "combined_equity_usd": decimal_to_str(combined_equity_usd),
            "account_baseline_equity_usd": decimal_to_str(baseline_equity),
            "account_raw_change_usd": decimal_to_str(raw_account_change),
            "external_cashflow_usd": decimal_to_str(external_cashflow),
            "account_net_change_usd": decimal_to_str(account_net_change),
            "account_minus_fill_pnl_usd": decimal_to_str(
                account_net_change - run_actual_pnl
                if account_net_change is not None and run_actual_pnl is not None
                else None
            ),
            "capital_usd": decimal_to_str(capital_usd),
            "capital_source": capital_source,
            "return_pnl_source": pnl_source,
            "return_pct": decimal_to_str(return_pct),
            "elapsed_days": decimal_to_str(elapsed_days),
            "covered_beijing_days": decimal_to_str(
                covered_beijing_days
            ),
            "annualized_simple_pct": decimal_to_str(annualized_pct),
            "annualized_reliability": (
                "unavailable"
                if annualized_pct is None
                else "sample_under_30_days"
                if elapsed_days is not None and elapsed_days < 30
                else "observable"
                if elapsed_days is not None
                else "unavailable"
            ),
            "summary_captured_at": captured_at,
            "variational_margin_usage_pct": latest_risk.get(
                "variational_maintenance_margin_usage_pct"
            ),
            "lighter_margin_usage_pct": latest_risk.get(
                "lighter_maintenance_margin_usage_pct"
            ),
            "max_projected_venue_leverage": latest_risk.get(
                "max_projected_venue_leverage"
            ),
        }

    def schedule_live_inventory_account_snapshot(
        self,
        *,
        stage: str,
        asset: str,
        lot_id: Any = None,
    ) -> None:
        task = asyncio.create_task(
            self.capture_live_inventory_account_snapshot(
                stage=stage,
                asset=asset,
                lot_id=lot_id,
                settle_seconds=(2.0 if stage == "entry_confirmed" else 0.5),
            ),
            name=f"live_inventory_account_snapshot:{stage}:{lot_id}",
        )
        tasks = getattr(self, "live_inventory_account_snapshot_tasks", None)
        if tasks is None:
            tasks = set()
            self.live_inventory_account_snapshot_tasks = tasks
        tasks.add(task)

        def account_snapshot_done(completed: asyncio.Task[None]) -> None:
            tasks.discard(completed)
            if completed.cancelled():
                return
            error = completed.exception()
            if error is not None:
                self.logger.warning(
                    "live_inventory_account_snapshot_failed stage=%s lot_id=%s error=%s",
                    stage,
                    lot_id,
                    type(error).__name__,
                )

        task.add_done_callback(account_snapshot_done)

    @staticmethod
    def extract_lighter_position_qty(account_result: dict[str, Any] | None, *, asset: str) -> Decimal | None:
        if not isinstance(account_result, dict):
            return None
        accounts = account_result.get("accounts")
        if not isinstance(accounts, list):
            return None
        asset = asset.upper()
        for account in accounts:
            if not isinstance(account, dict):
                continue
            positions = account.get("positions")
            if not isinstance(positions, list):
                continue
            for position in positions:
                if not isinstance(position, dict):
                    continue
                symbol = str(position.get("symbol") or "").upper()
                if symbol != asset and not symbol.startswith(f"{asset}-"):
                    continue
                qty = to_decimal(position.get("position"))
                if qty is None:
                    return None
                sign = to_decimal(position.get("sign"))
                if sign is not None and sign != 0:
                    return abs(qty) * (Decimal("1") if sign > 0 else Decimal("-1"))
                return qty
        return Decimal("0")

    async def reconcile_live_inventory_startup_state(self) -> None:
        if not self.live_inventory_reconcile_on_start:
            await self.append_live_inventory_log(
                "live_inventory_startup_reconcile_skipped",
                {"reason": "disabled_by_config", "open_lots_total": len(self.live_inventory_open_lots)},
            )
            return
        asset = self.live_inventory_state_asset()
        variational_positions_result = None
        variational_position_qty = None
        lighter_account_result = None
        lighter_position_qty = None
        reconciliation_errors: dict[str, str] = {}
        try:
            variational_positions_result = await self.fetch_variational_positions()
            if (
                not isinstance(variational_positions_result, dict)
                or variational_positions_result.get("ok") is False
            ):
                raise RuntimeError(f"invalid response: {variational_positions_result}")
            variational_position_qty = self.extract_variational_position_qty(
                variational_positions_result,
                asset=asset,
            )
        except Exception as exc:
            reconciliation_errors["variational"] = str(exc)
        try:
            lighter_account_result = await self.fetch_lighter_account()
            lighter_position_qty = self.extract_lighter_position_qty(
                lighter_account_result,
                asset=asset,
            )
        except Exception as exc:
            reconciliation_errors["lighter"] = str(exc)

        if reconciliation_errors or variational_position_qty is None or lighter_position_qty is None:
            await self.require_live_inventory_manual_review(
                asset=asset,
                reason="startup_reconcile_exchange_position_check_failed",
                context={
                    "errors": reconciliation_errors,
                    "open_lots": self.live_inventory_open_lots,
                    "variational_position_qty": decimal_to_str(variational_position_qty),
                    "lighter_position_qty": decimal_to_str(lighter_position_qty),
                    "action": "confirm both exchange positions manually before restart",
                },
            )
            raise RuntimeError("Live inventory startup reconcile failed: could not verify both exchange positions")

        expected_qty = sum((to_decimal(lot.get("qty")) or Decimal("0")) for lot in self.live_inventory_open_lots)
        tolerance = self.live_inventory_position_qty_tolerance(expected_qty)
        var_abs = abs(variational_position_qty)
        lighter_abs = abs(lighter_position_qty)

        if not self.live_inventory_open_lots:
            if var_abs > tolerance or lighter_abs > tolerance:
                await self.require_live_inventory_manual_review(
                    asset=asset,
                    reason="startup_reconcile_local_flat_but_exchange_position_open",
                    context={
                        "variational_position_qty": decimal_to_str(variational_position_qty),
                        "lighter_position_qty": decimal_to_str(lighter_position_qty),
                        "qty_tolerance": decimal_to_str(tolerance),
                        "variational_positions_result": variational_positions_result,
                        "lighter_account_result": lighter_account_result,
                        "action": "do not start; inspect and flatten both venues manually",
                    },
                )
                raise RuntimeError("Live inventory startup reconcile failed: exchange position exists while local state is flat")
            await self.capture_live_inventory_account_snapshot(
                stage="startup_flat",
                asset=asset,
                lighter_account_result=lighter_account_result,
            )
            await self.append_live_inventory_log(
                "live_inventory_startup_reconcile_ok",
                {
                    "status": "both_exchanges_flat",
                    "asset": asset,
                    "variational_position_qty": decimal_to_str(variational_position_qty),
                    "lighter_position_qty": decimal_to_str(lighter_position_qty),
                },
            )
            return

        open_directions = {
            str(lot.get("direction") or "")
            for lot in self.live_inventory_open_lots
        }
        expected_direction = next(iter(open_directions)) if len(open_directions) == 1 else None
        expected_lighter_sign = (
            Decimal("1")
            if expected_direction == DIRECTION_SHORT_VAR_LONG_LIGHTER
            else Decimal("-1")
            if expected_direction == DIRECTION_LONG_VAR_SHORT_LIGHTER
            else None
        )
        lighter_direction_matches = (
            expected_lighter_sign is not None
            and lighter_position_qty * expected_lighter_sign > 0
        )
        if (
            expected_qty <= 0
            or expected_direction is None
            or abs(var_abs - expected_qty) > tolerance
            or abs(lighter_abs - expected_qty) > tolerance
            or not lighter_direction_matches
        ):
            await self.require_live_inventory_manual_review(
                asset=asset,
                reason="startup_reconcile_exchange_position_mismatch",
                context={
                    "open_lots": self.live_inventory_open_lots,
                    "expected_open_qty": decimal_to_str(expected_qty),
                    "expected_direction": expected_direction,
                    "expected_lighter_sign": decimal_to_str(expected_lighter_sign),
                    "variational_position_qty": decimal_to_str(variational_position_qty),
                    "lighter_position_qty": decimal_to_str(lighter_position_qty),
                    "qty_tolerance": decimal_to_str(tolerance),
                    "variational_positions_result": variational_positions_result,
                    "lighter_account_result": lighter_account_result,
                    "action": "confirm both exchange positions and local lots before resuming",
                },
            )
            raise RuntimeError("Live inventory startup reconcile failed: exchange quantities do not match local open lots")
        await self.capture_live_inventory_account_snapshot(
            stage="startup_open",
            asset=asset,
            lighter_account_result=lighter_account_result,
        )
        await self.append_live_inventory_log(
            "live_inventory_startup_reconcile_ok",
            {
                "status": "open_state_matches_both_exchanges",
                "asset": asset,
                "open_lots_total": len(self.live_inventory_open_lots),
                "expected_open_qty": decimal_to_str(expected_qty),
                "variational_position_qty": decimal_to_str(variational_position_qty),
                "lighter_position_qty": decimal_to_str(lighter_position_qty),
            },
        )
        # A verified resume supersedes a stale manual-review marker from a
        # transient data outage. Persist immediately so operators and future
        # restarts see the same open state that this runtime is managing.
        await self.persist_live_inventory_memory(
            reason="startup_open_state_reconciled"
        )

    async def persist_live_inventory_memory(self, *, reason: str) -> None:
        pending_actions = self.pending_live_inventory_actions_payload()
        await self.write_live_inventory_state_async(
            {
                "status": live_inventory_state_status(
                    open_lots=self.live_inventory_open_lots,
                    pending_actions=pending_actions,
                ),
                "run_id": self.live_inventory_run_id,
                "asset": self.live_inventory_state_asset(),
                "next_lot_id": self.live_inventory_next_lot_id,
                "open_lots": self.live_inventory_open_lots,
                "pending_actions": pending_actions,
                "realized_pnl_usd": decimal_to_str(self.live_inventory_realized_pnl_usd),
                "completed_cycles": self.live_inventory_completed_cycles,
                "reason": reason,
                "maintenance_drain_requested": bool(
                    getattr(
                        self,
                        "live_inventory_maintenance_drain_requested",
                        False,
                    )
                ),
                "maintenance_drain_requested_at": (
                    getattr(
                        self,
                        "live_inventory_maintenance_drain_requested_at",
                        None,
                    )
                ),
                **self.live_inventory_v4_episode_payload(),
                "v4_shadow_tranche": getattr(
                    self, "live_inventory_v4_shadow_tranche", None
                ),
                "v4_shadow_tranches": self.live_inventory_basis_v4_shadow_tranches_state(),
                "v4_shadow_completed_keys": sorted(
                    getattr(self, "live_inventory_v4_shadow_completed_keys", set())
                ),
                "v4_shadow_completed_episode_id": (
                    getattr(
                        self,
                        "live_inventory_v4_shadow_completed_episode_id",
                        None,
                    )
                ),
            }
        )

    async def require_live_inventory_manual_review(
        self,
        *,
        asset: str,
        reason: str,
        context: dict[str, Any] | None = None,
    ) -> None:
        pending_actions = self.pending_live_inventory_actions_payload()
        await self.write_live_inventory_state_async(
            {
                "status": "manual_review_required",
                "run_id": self.live_inventory_run_id,
                "asset": asset,
                "next_lot_id": self.live_inventory_next_lot_id,
                "open_lots": self.live_inventory_open_lots,
                "pending_actions": pending_actions,
                "realized_pnl_usd": decimal_to_str(self.live_inventory_realized_pnl_usd),
                "completed_cycles": self.live_inventory_completed_cycles,
                "manual_review_reason": reason,
                "manual_review_context": context or {},
                "action": "stop_live_inventory_until_manual_flat_confirmed",
                **self.live_inventory_v4_episode_payload(),
            }
        )
        await self.append_live_inventory_log(
            "live_inventory_manual_review_required",
            {
                "asset": asset,
                "reason": reason,
                "manual_review_context": context or {},
                "open_lots_total": len(self.live_inventory_open_lots),
                "completed_cycles": self.live_inventory_completed_cycles,
                "action": "stop_live_inventory_until_manual_flat_confirmed",
            },
        )
        self.logger.warning(
            "live_inventory_manual_review_required asset=%s reason=%s open_lots=%s completed_cycles=%s action=stop_live_inventory_until_manual_flat_confirmed",
            asset,
            reason,
            len(self.live_inventory_open_lots),
            self.live_inventory_completed_cycles,
        )
        if getattr(self, "shutdown_reason", None) is None:
            self.shutdown_reason = f"manual_review_required:{reason}"
        self.stop_flag = True

    async def block_live_inventory_entry(self, *, asset: str, reason: str, context: dict[str, Any]) -> None:
        pending_actions = self.pending_live_inventory_actions_payload()
        await self.write_live_inventory_state_async(
            {
                "status": live_inventory_state_status(
                    open_lots=self.live_inventory_open_lots,
                    pending_actions=pending_actions,
                ),
                "run_id": self.live_inventory_run_id,
                "asset": asset,
                "next_lot_id": self.live_inventory_next_lot_id,
                "open_lots": self.live_inventory_open_lots,
                "pending_actions": pending_actions,
                "realized_pnl_usd": decimal_to_str(self.live_inventory_realized_pnl_usd),
                "completed_cycles": self.live_inventory_completed_cycles,
                "last_blocked_reason": reason,
                "last_blocked_context": context,
                **self.live_inventory_v4_episode_payload(),
            }
        )
        await self.append_live_inventory_log(
            "live_inventory_entry_blocked",
            {
                "asset": asset,
                "reason": reason,
                "blocked_context": context,
                "open_lots_total": len(self.live_inventory_open_lots),
                "completed_cycles": self.live_inventory_completed_cycles,
            },
        )

    async def poll_live_inventory_maintenance_control(self) -> None:
        if not self.is_live_inventory_enabled() or self.live_inventory_dry_decisions:
            return
        control_path = getattr(self, "live_inventory_control_file", None)
        if control_path is None:
            return
        if not getattr(
            self,
            "live_inventory_maintenance_drain_requested",
            False,
        ):
            control = await asyncio.to_thread(read_json, control_path)
            if not maintenance_control_targets_runtime(
                control,
                process_id=os.getpid(),
                run_id=self.live_inventory_run_id,
                asset=self.live_inventory_state_asset(),
            ):
                return
            self.live_inventory_maintenance_drain_requested = True
            self.live_inventory_maintenance_drain_requested_at = str(
                control.get("requested_at") or utc_now()
            )
            self.live_inventory_maintenance_control_payload = dict(control)
        if not getattr(
            self,
            "live_inventory_maintenance_drain_announced",
            False,
        ):
            if self.live_inventory_maintenance_drain_requested_at is None:
                self.live_inventory_maintenance_drain_requested_at = utc_now()
            if not self.live_inventory_maintenance_control_payload:
                self.live_inventory_maintenance_control_payload = {
                    "schema_version": 1,
                    "action": "drain_after_flat",
                    "status": "requested",
                    "asset": self.live_inventory_state_asset(),
                    "target_pid": os.getpid(),
                    "target_run_id": self.live_inventory_run_id,
                    "requested_at": (
                        self.live_inventory_maintenance_drain_requested_at
                    ),
                    "request_source": "startup_resume_and_drain",
                }
                await asyncio.to_thread(
                    write_json_atomic,
                    control_path,
                    self.live_inventory_maintenance_control_payload,
                )
            self.live_inventory_basis_entry_confirm_counts.clear()
            gradient_window = getattr(
                self,
                "live_inventory_v4_gradient_entry_tier_window",
                None,
            )
            if gradient_window is not None:
                gradient_window.clear()
            await self.persist_live_inventory_memory(
                reason="maintenance_drain_requested"
            )
            await self.append_live_inventory_log(
                "live_inventory_maintenance_drain_requested",
                {
                    "asset": self.live_inventory_state_asset(),
                    "action": "block_new_entries_manage_existing_positions",
                    "open_lots_total": len(self.live_inventory_open_lots),
                    "pending_actions_total": len(
                        self.pending_live_inventory_actions_payload()
                    ),
                    "requested_at": self.live_inventory_maintenance_drain_requested_at,
                },
            )
            self.live_inventory_maintenance_drain_announced = True
        pending_actions = self.pending_live_inventory_actions_payload()
        if self.live_inventory_open_lots or pending_actions:
            return
        now = time.monotonic()
        if (
            now
            - getattr(
                self,
                "live_inventory_maintenance_last_flat_check_monotonic",
                0.0,
            )
            < 3.0
        ):
            return
        self.live_inventory_maintenance_last_flat_check_monotonic = now
        asset = self.live_inventory_state_asset()
        try:
            variational_positions = await self.fetch_variational_positions()
            if (
                not isinstance(variational_positions, dict)
                or variational_positions.get("ok") is False
            ):
                raise RuntimeError("invalid_variational_positions_response")
            variational_qty = self.extract_variational_position_qty(
                variational_positions,
                asset=asset,
            )
            lighter_account = await self.fetch_lighter_account()
            lighter_qty = self.extract_lighter_position_qty(
                lighter_account,
                asset=asset,
            )
            if variational_qty is None or lighter_qty is None:
                raise RuntimeError("exchange_position_quantity_unavailable")
        except Exception as exc:
            if now - getattr(
                self,
                "live_inventory_maintenance_last_block_log_monotonic",
                0.0,
            ) >= 30.0:
                self.live_inventory_maintenance_last_block_log_monotonic = now
                await self.append_live_inventory_log(
                    "live_inventory_maintenance_drain_blocked",
                    {
                        "asset": asset,
                        "reason": "exchange_flat_confirmation_failed",
                        "error": type(exc).__name__,
                        "action": "keep_entries_blocked_and_retry",
                    },
                )
            return
        tolerance = self.live_inventory_position_qty_tolerance(Decimal("0"))
        if abs(variational_qty) > tolerance or abs(lighter_qty) > tolerance:
            if now - getattr(
                self,
                "live_inventory_maintenance_last_block_log_monotonic",
                0.0,
            ) >= 30.0:
                self.live_inventory_maintenance_last_block_log_monotonic = now
                await self.append_live_inventory_log(
                    "live_inventory_maintenance_drain_blocked",
                    {
                        "asset": asset,
                        "reason": "exchange_positions_not_flat",
                        "variational_position_qty": decimal_to_str(
                            variational_qty
                        ),
                        "lighter_position_qty": decimal_to_str(lighter_qty),
                        "action": "keep_entries_blocked_and_retry",
                    },
                )
            return
        await self.capture_live_inventory_account_snapshot(
            stage="maintenance_flat",
            asset=asset,
            lighter_account_result=lighter_account,
        )
        await self.persist_live_inventory_memory(
            reason="maintenance_drain_completed"
        )
        completed_at = utc_now()
        completed_control = {
            **getattr(
                self,
                "live_inventory_maintenance_control_payload",
                {},
            ),
            "status": "completed",
            "completed_at": completed_at,
            "variational_position_qty": decimal_to_str(variational_qty),
            "lighter_position_qty": decimal_to_str(lighter_qty),
        }
        await asyncio.to_thread(
            write_json_atomic,
            control_path,
            completed_control,
        )
        await self.append_live_inventory_log(
            "live_inventory_maintenance_drain_completed",
            {
                "asset": asset,
                "action": "runtime_stop_for_maintenance",
                "open_lots_total": 0,
                "pending_actions_total": 0,
                "variational_position_qty": decimal_to_str(variational_qty),
                "lighter_position_qty": decimal_to_str(lighter_qty),
                "completed_at": completed_at,
            },
        )
        self.shutdown_reason = "maintenance_drain_completed"
        self.stop_flag = True

    async def maybe_timeout_pending_live_inventory_var_entry(self, *, asset: str) -> bool:
        now_monotonic = time.monotonic()
        for item in list(getattr(self, "pending_live_inventory_var_fill_matches", [])):
            if item.asset.upper() != asset.upper() or item.role not in {"live_inventory_entry_pending_lighter", "live_inventory_entry_pending_var_fill"}:
                continue
            age_seconds = now_monotonic - item.created_at_monotonic
            resolved = await self.maybe_resolve_pending_live_inventory_var_entry_from_orders(
                item=item,
                age_seconds=age_seconds,
            )
            if resolved:
                return True
            if age_seconds < self.auto_live_match_window_seconds:
                continue
            self.remove_pending_live_inventory_var_fill_match(
                asset=item.asset,
                lot_id=item.lot_id,
                role=item.role,
            )
            positions_result = None
            position_qty = None
            position_check_error = None
            try:
                positions_result = await self.fetch_variational_positions()
                position_qty = self.extract_variational_position_qty(positions_result, asset=item.asset)
            except Exception as exc:
                position_check_error = str(exc)
            position_abs = abs(position_qty) if position_qty is not None else None
            reason = (
                "basis_entry_var_fill_timeout_position_detected"
                if position_abs is not None and position_abs > Decimal("0")
                else "basis_entry_var_fill_timeout"
            )
            await self.require_live_inventory_manual_review(
                asset=item.asset,
                reason=reason,
                context={
                    "lot_id": item.lot_id,
                    "side": item.side,
                    "qty": decimal_to_str(item.qty),
                    "age_seconds": age_seconds,
                    "timeout_seconds": self.auto_live_match_window_seconds,
                    "variational_position_qty": decimal_to_str(position_qty),
                    "variational_position_check_error": position_check_error,
                    "variational_positions_result": positions_result,
                    "pending_context": item.context or {},
                    "action": "confirm_variational_order_status_and_position_manually",
                },
            )
            return True
        return False

    async def maybe_resolve_pending_live_inventory_var_entry_from_orders(
        self,
        *,
        item: PendingLiveInventoryVarFillMatch,
        age_seconds: float,
    ) -> bool:
        context = item.context or {}
        rfq_id = str(context.get("rfq_id") or "").strip()
        if not rfq_id:
            return False
        now_monotonic = time.monotonic()
        last_check = context.get("orders_v2_last_check_monotonic")
        if isinstance(last_check, (int, float)) and now_monotonic - float(last_check) < 1.0:
            return False
        context["orders_v2_last_check_monotonic"] = now_monotonic
        item.context = context

        try:
            orders_result = await self.fetch_variational_orders(
                asset=item.asset,
                status="canceled,cleared,rejected",
                limit=20,
            )
        except Exception as exc:
            context["orders_v2_last_error"] = str(exc)
            return False

        order = self.find_variational_order_by_rfq_id(orders_result, rfq_id=rfq_id)
        if order is None:
            context["orders_v2_last_result"] = "rfq_not_found"
            return False

        status = str(order.get("status") or "").strip().lower()
        if status == "cleared":
            price = to_decimal(order.get("price"))
            qty = to_decimal(order.get("qty")) or item.qty
            if price is None or qty <= 0:
                self.remove_pending_live_inventory_var_fill_match(
                    asset=item.asset,
                    lot_id=item.lot_id,
                    role=item.role,
                )
                await self.require_live_inventory_manual_review(
                    asset=item.asset,
                    reason="basis_entry_var_order_cleared_missing_fill_details",
                    context={"lot_id": item.lot_id, "rfq_id": rfq_id, "order": order, "orders_result": orders_result},
                )
                return True
            item.qty = qty
            record = OrderLifecycle(
                trade_key=f"var_order:{order.get('order_id') or rfq_id}",
                trade_id=str(order.get("order_id") or rfq_id),
                side=str(order.get("side") or item.side).lower(),
                qty=qty,
                asset=item.asset.upper(),
                mode=self.mode,
                last_variational_status="filled",
                var_fill_price=price,
                var_fill_ts_iso=str(order.get("execution_timestamp") or order.get("created_at") or utc_now()),
                live_var_fill_seen_at_iso=utc_now(),
                live_var_fill_seen_monotonic=time.monotonic(),
                matched_variational_trade_id=str(order.get("order_id") or rfq_id),
                auto_live_cycle_id=item.lot_id,
                auto_live_role=item.role,
                auto_live_merge_path="orders_v2_confirmed_var_fill",
            )
            self.remove_pending_live_inventory_var_fill_match(asset=item.asset, lot_id=item.lot_id, role=item.role)
            await self.append_order_log("variational_fill", record.to_payload())
            await self.complete_live_inventory_entry_after_var_fill(
                match=item,
                record=record,
                fill_payload={**record.to_payload(), "variational_order": order},
            )
            return True

        if status in {"rejected", "canceled", "cancelled"}:
            self.remove_pending_live_inventory_var_fill_match(asset=item.asset, lot_id=item.lot_id, role=item.role)
            clearing_status = str(order.get("clearing_status") or "").strip().lower()
            if clearing_status == "rejected_failed_taker_funding":
                self.live_inventory_var_reject_cooldown_until[(item.asset.upper(), item.side.lower())] = (
                    time.monotonic() + self.live_inventory_var_reject_cooldown_seconds
                )
            if bool(context.get("lighter_started")):
                await self.require_live_inventory_manual_review(
                    asset=item.asset,
                    reason=f"basis_var_entry_order_{status}_after_concurrent_lighter_submit",
                    context={
                        "lot_id": item.lot_id,
                        "rfq_id": rfq_id,
                        "order": order,
                        "orders_result": orders_result,
                        "pending_context": context,
                        "action": "confirm_lighter_position_and_flatten_if_needed",
                    },
                )
                return True
            await self.persist_live_inventory_memory(reason=f"basis_var_entry_order_{status}")
            await self.write_live_inventory_state_async(
                {
                    "status": live_inventory_state_status(
                        open_lots=self.live_inventory_open_lots,
                        pending_actions=[],
                    ),
                    "asset": item.asset.upper(),
                    "next_lot_id": self.live_inventory_next_lot_id,
                    "open_lots": self.live_inventory_open_lots,
                    "pending_actions": [],
                    "realized_pnl_usd": decimal_to_str(self.live_inventory_realized_pnl_usd),
                    "completed_cycles": self.live_inventory_completed_cycles,
                    "last_rejected_reason": f"variational_order_{status}",
                    "last_rejected_context": {"lot_id": item.lot_id, "rfq_id": rfq_id, "order": order},
                }
            )
            await self.append_live_inventory_log(
                "live_inventory_var_entry_final_rejected",
                {
                    "asset": item.asset.upper(),
                    "lot_id": item.lot_id,
                    "side": item.side,
                    "qty": decimal_to_str(item.qty),
                    "age_seconds": age_seconds,
                    "rfq_id": rfq_id,
                    "status": status,
                    "clearing_status": order.get("clearing_status"),
                    "cancel_reason": order.get("cancel_reason"),
                    "failed_risk_checks": order.get("failed_risk_checks"),
                    "order": order,
                    "cooldown_seconds": self.live_inventory_var_reject_cooldown_seconds if clearing_status == "rejected_failed_taker_funding" else None,
                    "action": "removed_pending_without_lighter_hedge",
                },
            )
            return True
        context["orders_v2_last_result"] = f"unhandled_status:{status or 'missing'}"
        return False

    @staticmethod
    def live_inventory_pair_pnl(
        *,
        direction: str,
        qty: Decimal,
        entry_var_price: Decimal,
        entry_lighter_price: Decimal,
        exit_var_price: Decimal,
        exit_lighter_price: Decimal,
    ) -> tuple[Decimal, Decimal, Decimal]:
        return VariationalToLighterRuntime.live_inventory_pair_pnl_by_leg_qty(
            direction=direction,
            var_qty=qty,
            lighter_qty=qty,
            entry_var_price=entry_var_price,
            entry_lighter_price=entry_lighter_price,
            exit_var_price=exit_var_price,
            exit_lighter_price=exit_lighter_price,
        )

    @staticmethod
    def live_inventory_pair_pnl_by_leg_qty(
        *,
        direction: str,
        var_qty: Decimal,
        lighter_qty: Decimal,
        entry_var_price: Decimal,
        entry_lighter_price: Decimal,
        exit_var_price: Decimal,
        exit_lighter_price: Decimal,
    ) -> tuple[Decimal, Decimal, Decimal]:
        if direction == DIRECTION_LONG_VAR_SHORT_LIGHTER:
            var_leg_pnl = (exit_var_price - entry_var_price) * var_qty
            lighter_leg_pnl = (entry_lighter_price - exit_lighter_price) * lighter_qty
        else:
            var_leg_pnl = (entry_var_price - exit_var_price) * var_qty
            lighter_leg_pnl = (exit_lighter_price - entry_lighter_price) * lighter_qty
        return var_leg_pnl, lighter_leg_pnl, var_leg_pnl + lighter_leg_pnl

    def live_inventory_v4_aggregate_exit_context(
        self,
        *,
        lots: list[dict[str, Any]],
        var_exit_price: Decimal,
        lighter_exit_price: Decimal,
    ) -> dict[str, Any]:
        total_pnl = Decimal("0")
        total_notional = Decimal("0")
        total_qty = Decimal("0")
        lot_ids: list[str] = []
        directions = {str(lot.get("direction") or "") for lot in lots}
        if len(directions) != 1:
            return {"ready": False, "reason": "mixed_or_missing_directions"}
        direction = next(iter(directions))
        if direction not in {
            DIRECTION_LONG_VAR_SHORT_LIGHTER,
            DIRECTION_SHORT_VAR_LONG_LIGHTER,
        }:
            return {"ready": False, "reason": "unknown_direction"}
        for lot in lots:
            qty = to_decimal(lot.get("qty"))
            entry_var_price = to_decimal(lot.get("entry_var_fill_price"))
            entry_lighter_price = to_decimal(lot.get("entry_lighter_fill_price"))
            if (
                qty is None
                or qty <= 0
                or entry_var_price is None
                or entry_var_price <= 0
                or entry_lighter_price is None
                or entry_lighter_price <= 0
                or not self.live_inventory_entry_cost_confirmed(lot)
            ):
                return {
                    "ready": False,
                    "reason": "lot_final_fill_cost_pending",
                    "lot_id": lot.get("lot_id"),
                }
            _, _, pnl = self.live_inventory_pair_pnl(
                direction=direction,
                qty=qty,
                entry_var_price=entry_var_price,
                entry_lighter_price=entry_lighter_price,
                exit_var_price=var_exit_price,
                exit_lighter_price=lighter_exit_price,
            )
            total_pnl += pnl
            total_notional += qty * entry_var_price
            total_qty += qty
            lot_ids.append(
                self.live_inventory_normalized_lot_id(lot.get("lot_id"))
            )
        return {
            "ready": bool(total_notional > 0 and lot_ids),
            "reason": None,
            "direction": direction,
            "lot_ids": lot_ids,
            "lot_count": len(lot_ids),
            "total_qty": decimal_to_str(total_qty),
            "total_notional_usd": decimal_to_str(total_notional),
            "aggregate_executable_pnl_usd": decimal_to_str(total_pnl),
            "aggregate_executable_pnl_bps": decimal_to_str(
                total_pnl / total_notional * Decimal("10000")
            ),
        }

    def live_inventory_v4_merge_lots_for_atomic_exit(
        self,
        lots: list[dict[str, Any]],
    ) -> dict[str, Any]:
        """Merge same-direction confirmed lots into one executable basket."""
        if not lots:
            raise ValueError("cannot merge an empty lot basket")
        directions = {str(lot.get("direction") or "") for lot in lots}
        if len(directions) != 1:
            raise ValueError("cannot merge mixed-direction lots")
        if not all(self.live_inventory_entry_cost_confirmed(lot) for lot in lots):
            raise ValueError("cannot merge lots with pending entry costs")
        quantities = [to_decimal(lot.get("qty")) for lot in lots]
        var_prices = [to_decimal(lot.get("entry_var_fill_price")) for lot in lots]
        lighter_prices = [
            to_decimal(lot.get("entry_lighter_fill_price")) for lot in lots
        ]
        if any(value is None or value <= 0 for value in quantities):
            raise ValueError("cannot merge lots with invalid quantity")
        if any(value is None or value <= 0 for value in var_prices):
            raise ValueError("cannot merge lots with invalid Variational fill")
        if any(value is None or value <= 0 for value in lighter_prices):
            raise ValueError("cannot merge lots with invalid Lighter fill")
        total_qty = sum((value for value in quantities if value is not None), Decimal("0"))
        weighted_var = sum(
            (
                qty * price
                for qty, price in zip(quantities, var_prices)
                if qty is not None and price is not None
            ),
            Decimal("0"),
        ) / total_qty
        weighted_lighter = sum(
            (
                qty * price
                for qty, price in zip(quantities, lighter_prices)
                if qty is not None and price is not None
            ),
            Decimal("0"),
        ) / total_qty
        ordered = sorted(
            lots,
            key=lambda lot: (
                int(lot.get("entered_sample_index") or 0),
                str(lot.get("entered_at") or ""),
            ),
        )
        first = dict(ordered[0])
        component_ids = [
            self.live_inventory_normalized_lot_id(lot.get("lot_id"))
            for lot in lots
        ]
        mfe_values = [
            value
            for lot in lots
            if (value := to_decimal(lot.get("shadow_mfe_pnl_bps"))) is not None
        ]
        mae_values = [
            value
            for lot in lots
            if (value := to_decimal(lot.get("shadow_mae_pnl_bps"))) is not None
        ]
        first.update(
            {
                "qty": decimal_to_str(total_qty),
                "entry_var_fill_price": decimal_to_str(weighted_var),
                "entry_lighter_fill_price": decimal_to_str(weighted_lighter),
                "entry_var_final_fill_qty": decimal_to_str(total_qty),
                "entry_lighter_final_fill_qty": decimal_to_str(total_qty),
                "entry_var_price_source": "final_fill",
                "entry_lighter_price_source": "final_fill",
                "entry_cost_status": "final_fills_confirmed",
                "portfolio_atomic_exit": True,
                "portfolio_component_lot_ids": component_ids,
                "portfolio_component_lot_count": len(component_ids),
                "portfolio_component_lots": [
                    {
                        "lot_id": lot.get("lot_id"),
                        "qty": lot.get("qty"),
                        "entry_var_fill_price": lot.get("entry_var_fill_price"),
                        "entry_lighter_fill_price": lot.get(
                            "entry_lighter_fill_price"
                        ),
                        "tranche_index": lot.get("tranche_index"),
                        "entry_gradient_tier": lot.get("entry_gradient_tier"),
                    }
                    for lot in lots
                ],
                "shadow_mfe_pnl_bps": decimal_to_str(max(mfe_values))
                if mfe_values
                else None,
                "shadow_mae_pnl_bps": decimal_to_str(min(mae_values))
                if mae_values
                else None,
            }
        )
        return first

    @staticmethod
    def live_inventory_basis_v4_shadow_level_key(value: Decimal) -> str:
        return decimal_to_str(value.quantize(Decimal("0.00"))) or "0.00"

    def live_inventory_basis_v4_shadow_tranches_state(
        self,
    ) -> dict[str, dict[str, Any]]:
        tranches = getattr(self, "live_inventory_v4_shadow_tranches", None)
        if not isinstance(tranches, dict):
            tranches = {}
        legacy = getattr(self, "live_inventory_v4_shadow_tranche", None)
        if isinstance(legacy, dict):
            improvement = (
                to_decimal(legacy.get("basis_improvement_trigger_bps"))
                or LIVE_INVENTORY_BASIS_V4_SHADOW_TRANCHE_IMPROVEMENT_BPS
            )
            tranches.setdefault(
                self.live_inventory_basis_v4_shadow_level_key(improvement),
                legacy,
            )
        self.live_inventory_v4_shadow_tranches = tranches
        legacy_key = self.live_inventory_basis_v4_shadow_level_key(
            LIVE_INVENTORY_BASIS_V4_SHADOW_TRANCHE_IMPROVEMENT_BPS
        )
        self.live_inventory_v4_shadow_tranche = tranches.get(legacy_key)
        return tranches

    @staticmethod
    def live_inventory_basis_v4_shadow_completion_key(
        episode_id: str,
        level_key: str,
    ) -> str:
        return f"{episode_id}:{level_key}"

    def reset_live_inventory_basis_v4_shadow_gradient(self) -> None:
        self.live_inventory_v4_shadow_tranche = None
        self.live_inventory_v4_shadow_tranches = {}
        self.live_inventory_v4_shadow_completed_keys = set()
        self.live_inventory_v4_shadow_completed_episode_id = None

    def live_inventory_basis_v4_shadow_tranche_pnl(
        self,
        *,
        shadow: dict[str, Any],
        exit_var_price: Decimal,
        exit_lighter_price: Decimal,
    ) -> tuple[Decimal | None, Decimal | None]:
        qty = to_decimal(shadow.get("qty"))
        entry_var_price = to_decimal(shadow.get("entry_var_price"))
        entry_lighter_price = to_decimal(shadow.get("entry_lighter_price"))
        if (
            qty is None
            or qty <= 0
            or entry_var_price is None
            or entry_var_price <= 0
            or entry_lighter_price is None
        ):
            return None, None
        _, _, pnl = self.live_inventory_pair_pnl(
            direction=str(shadow.get("direction") or ""),
            qty=qty,
            entry_var_price=entry_var_price,
            entry_lighter_price=entry_lighter_price,
            exit_var_price=exit_var_price,
            exit_lighter_price=exit_lighter_price,
        )
        notional = qty * entry_var_price
        pnl_bps = pnl / notional * Decimal("10000") if notional else None
        return pnl, pnl_bps

    async def close_live_inventory_basis_v4_shadow_tranche(
        self,
        *,
        asset: str,
        reason: str,
        exit_var_price: Decimal,
        exit_lighter_price: Decimal,
        confirmation_mode: str | None = None,
        level_key: str | None = None,
    ) -> bool:
        tranches = self.live_inventory_basis_v4_shadow_tranches_state()
        if level_key is None:
            level_key = self.live_inventory_basis_v4_shadow_level_key(
                LIVE_INVENTORY_BASIS_V4_SHADOW_TRANCHE_IMPROVEMENT_BPS
            )
            if level_key not in tranches and len(tranches) == 1:
                level_key = next(iter(tranches))
        shadow = tranches.get(level_key)
        if not isinstance(shadow, dict):
            return False
        pnl, pnl_bps = self.live_inventory_basis_v4_shadow_tranche_pnl(
            shadow=shadow,
            exit_var_price=exit_var_price,
            exit_lighter_price=exit_lighter_price,
        )
        entered_at = self._parse_iso_ts(str(shadow.get("entered_at") or ""))
        holding_seconds = (
            max(0.0, (datetime.now(timezone.utc) - entered_at).total_seconds())
            if entered_at is not None
            else None
        )
        episode_id = str(shadow.get("episode_id") or "") or None
        await self.append_live_inventory_log(
            "live_inventory_v4_shadow_tranche_exited",
            {
                "asset": asset,
                "episode_id": episode_id,
                "tranche_index": shadow.get("tranche_index"),
                "basis_improvement_trigger_bps": shadow.get(
                    "basis_improvement_trigger_bps"
                ),
                "direction": shadow.get("direction"),
                "reason": reason,
                "exit_confirmation_mode": confirmation_mode,
                "qty": shadow.get("qty"),
                "notional_usd": shadow.get("notional_usd"),
                "entry_basis_bps": shadow.get("entry_basis_bps"),
                "entry_edge_bps": shadow.get("entry_edge_bps"),
                "exit_var_price": decimal_to_str(exit_var_price),
                "exit_lighter_price": decimal_to_str(exit_lighter_price),
                "shadow_pnl_usd": decimal_to_str(pnl),
                "shadow_pnl_bps": decimal_to_str(pnl_bps),
                "holding_seconds": holding_seconds,
                "shadow_mfe_pnl_bps": shadow.get("mfe_pnl_bps"),
                "shadow_mae_pnl_bps": shadow.get("mae_pnl_bps"),
                "effective_min_exit_pnl_bps": decimal_to_str(
                    self.live_inventory_basis_v4_effective_exit_target_bps()
                ),
                "real_orders_submitted": 0,
            },
        )
        if episode_id:
            completed = getattr(
                self, "live_inventory_v4_shadow_completed_keys", set()
            )
            if not isinstance(completed, set):
                completed = set(completed or [])
            completed.add(
                self.live_inventory_basis_v4_shadow_completion_key(
                    episode_id,
                    level_key,
                )
            )
            self.live_inventory_v4_shadow_completed_keys = completed
        tranches.pop(level_key, None)
        self.live_inventory_v4_shadow_tranches = tranches
        legacy_key = self.live_inventory_basis_v4_shadow_level_key(
            LIVE_INVENTORY_BASIS_V4_SHADOW_TRANCHE_IMPROVEMENT_BPS
        )
        self.live_inventory_v4_shadow_tranche = tranches.get(legacy_key)
        if level_key == legacy_key:
            self.live_inventory_v4_shadow_completed_episode_id = episode_id
        await self.persist_live_inventory_memory(reason=f"v4_shadow_tranche_{reason}")
        return True

    async def close_all_live_inventory_basis_v4_shadow_tranches(
        self,
        *,
        asset: str,
        reason: str,
        exit_var_price: Decimal,
        exit_lighter_price: Decimal,
    ) -> bool:
        closed = False
        for level_key in list(self.live_inventory_basis_v4_shadow_tranches_state()):
            closed = (
                await self.close_live_inventory_basis_v4_shadow_tranche(
                    asset=asset,
                    reason=reason,
                    exit_var_price=exit_var_price,
                    exit_lighter_price=exit_lighter_price,
                    level_key=level_key,
                )
                or closed
            )
        return closed

    async def maybe_update_live_inventory_basis_v4_shadow_gradient(
        self,
        *,
        asset: str,
        sample_index: int,
        basis_bps: Decimal,
        short_edge_bps: Decimal,
        entry_threshold_bps: Decimal | None,
        var_bid: Decimal,
        var_ask: Decimal,
        lighter_buy_price: Decimal,
        lighter_sell_price: Decimal,
        warm: bool,
        var_quote_age_ok: bool,
        lighter_book_age_ok: bool,
        basis_sample_move_ok: bool,
    ) -> None:
        if not getattr(self, "live_inventory_basis_v4_shadow_gradient", False):
            return
        tranches = self.live_inventory_basis_v4_shadow_tranches_state()
        if tranches:
            if not var_quote_age_ok or not lighter_book_age_ok:
                for shadow in tranches.values():
                    self.live_inventory_basis_v4_reset_exit_confirmation(shadow)
                return
            for level_key, shadow in list(tranches.items()):
                _, pnl_bps = self.live_inventory_basis_v4_shadow_tranche_pnl(
                    shadow=shadow,
                    exit_var_price=var_ask,
                    exit_lighter_price=lighter_sell_price,
                )
                if pnl_bps is None:
                    continue
                prior_mfe = to_decimal(shadow.get("mfe_pnl_bps"))
                prior_mae = to_decimal(shadow.get("mae_pnl_bps"))
                shadow["mfe_pnl_bps"] = decimal_to_str(
                    pnl_bps if prior_mfe is None else max(prior_mfe, pnl_bps)
                )
                shadow["mae_pnl_bps"] = decimal_to_str(
                    pnl_bps if prior_mae is None else min(prior_mae, pnl_bps)
                )
                shadow["last_pnl_bps"] = decimal_to_str(pnl_bps)
                target_bps = self.live_inventory_basis_v4_effective_exit_target_bps()
                strong_context = self.live_inventory_basis_v4_strong_single_context(
                    effective_min_exit_pnl_bps=target_bps
                )
                strong_threshold_bps = strong_context["threshold_bps"]
                strong_values = [
                    value
                    for value in (
                        to_decimal(item)
                        for item in list(
                            shadow.get("v4_exit_strong_stability_values") or []
                        )
                    )
                    if value is not None
                ]
                strong_values.append(pnl_bps)
                strong_values = strong_values[
                    -LIVE_INVENTORY_BASIS_V4_EXIT_STRONG_SINGLE_STABILITY_SAMPLES:
                ]
                shadow["v4_exit_strong_stability_values"] = [
                    decimal_to_str(value) for value in strong_values
                ]
                strong_range_bps = (
                    max(strong_values) - min(strong_values)
                    if len(strong_values)
                    >= LIVE_INVENTORY_BASIS_V4_EXIT_STRONG_SINGLE_STABILITY_SAMPLES
                    else None
                )
                normal_confirmed, _ = self.live_inventory_basis_v4_confirm_exit_candidate(
                    shadow,
                    eligible=pnl_bps >= target_bps,
                )
                strong_confirmed = bool(
                    not normal_confirmed
                    and strong_context["enabled"]
                    and pnl_bps >= strong_threshold_bps
                    and strong_range_bps is not None
                    and strong_range_bps
                    <= LIVE_INVENTORY_BASIS_V4_EXIT_STRONG_SINGLE_MAX_RANGE_BPS
                )
                entered_at = self._parse_iso_ts(str(shadow.get("entered_at") or ""))
                holding_seconds = (
                    max(0.0, (datetime.now(timezone.utc) - entered_at).total_seconds())
                    if entered_at is not None
                    else 0.0
                )
                reason = None
                confirmation_mode = None
                if pnl_bps <= -self.live_inventory_max_unrealized_loss_bps:
                    reason = "shadow_max_unrealized_loss_bps"
                elif strong_confirmed:
                    reason = "shadow_v4_executable_net_target_reached"
                    confirmation_mode = "strong_single"
                elif normal_confirmed:
                    reason = "shadow_v4_executable_net_target_reached"
                    confirmation_mode = "two_of_three"
                if reason is not None:
                    await self.close_live_inventory_basis_v4_shadow_tranche(
                        asset=asset,
                        reason=reason,
                        exit_var_price=var_ask,
                        exit_lighter_price=lighter_sell_price,
                        confirmation_mode=confirmation_mode,
                        level_key=level_key,
                    )

        if len(getattr(self, "live_inventory_open_lots", [])) != 1:
            return
        real_lot = self.live_inventory_open_lots[0]
        episode_id = str(real_lot.get("episode_id") or "") or None
        if (
            episode_id is None
            or str(real_lot.get("direction") or "")
            != DIRECTION_SHORT_VAR_LONG_LIGHTER
            or real_lot.get("entry_kind") != "basis_v4_eth_short_p97_5"
            or not self.live_inventory_entry_cost_confirmed(real_lot)
            or getattr(self, "pending_live_inventory_var_fill_matches", [])
        ):
            return
        if (
            entry_threshold_bps is None
            or short_edge_bps <= entry_threshold_bps
            or not warm
            or not var_quote_age_ok
            or not lighter_book_age_ok
            or not basis_sample_move_ok
        ):
            return
        real_entry_basis_bps = to_decimal(real_lot.get("entry_basis_bps"))
        if real_entry_basis_bps is None:
            return
        completed = getattr(self, "live_inventory_v4_shadow_completed_keys", set())
        if not isinstance(completed, set):
            completed = set(completed or [])
        entered = False
        tranches = self.live_inventory_basis_v4_shadow_tranches_state()
        for improvement_bps in LIVE_INVENTORY_BASIS_V4_SHADOW_TRANCHE_IMPROVEMENT_LEVELS_BPS:
            level_key = self.live_inventory_basis_v4_shadow_level_key(improvement_bps)
            completion_key = self.live_inventory_basis_v4_shadow_completion_key(
                episode_id,
                level_key,
            )
            addon_threshold_bps = real_entry_basis_bps + improvement_bps
            if (
                level_key in tranches
                or completion_key in completed
                or basis_bps < addon_threshold_bps
            ):
                continue
            qty = self.live_inventory_lot_notional_usd / var_bid
            shadow = {
                "episode_id": episode_id,
                "tranche_index": LIVE_INVENTORY_BASIS_V4_SHADOW_TRANCHE_INDEX,
                "basis_improvement_trigger_bps": decimal_to_str(improvement_bps),
                "direction": DIRECTION_SHORT_VAR_LONG_LIGHTER,
                "qty": decimal_to_str(qty),
                "notional_usd": decimal_to_str(self.live_inventory_lot_notional_usd),
                "entry_var_price": decimal_to_str(var_bid),
                "entry_lighter_price": decimal_to_str(lighter_buy_price),
                "entry_basis_bps": decimal_to_str(basis_bps),
                "entry_edge_bps": decimal_to_str(short_edge_bps),
                "entry_threshold_bps": decimal_to_str(entry_threshold_bps),
                "addon_threshold_bps": decimal_to_str(addon_threshold_bps),
                "entered_at": utc_now(),
                "entered_sample_index": sample_index,
                "v4_exit_confirmation_count": 0,
            }
            tranches[level_key] = shadow
            await self.append_live_inventory_log(
                "live_inventory_v4_shadow_tranche_entered",
                {
                    "asset": asset,
                    **shadow,
                    "basis_improvement_bps": decimal_to_str(
                        basis_bps - real_entry_basis_bps
                    ),
                    "real_lot_id": real_lot.get("lot_id"),
                    "real_orders_submitted": 0,
                },
            )
            entered = True
        self.live_inventory_v4_shadow_tranches = tranches
        legacy_key = self.live_inventory_basis_v4_shadow_level_key(
            LIVE_INVENTORY_BASIS_V4_SHADOW_TRANCHE_IMPROVEMENT_BPS
        )
        self.live_inventory_v4_shadow_tranche = tranches.get(legacy_key)
        if entered:
            await self.persist_live_inventory_memory(reason="v4_shadow_tranches_entered")

    def live_inventory_common_order_qty(self, *, asset: str, qty: Decimal) -> Decimal:
        var_quantum = VARIATIONAL_API_AMOUNT_QUANTUM_BY_ASSET.get(
            str(asset or "").upper(),
            VARIATIONAL_API_AMOUNT_QUANTUM,
        )
        base_amount_multiplier = int(getattr(self, "base_amount_multiplier", 0) or 0)
        lighter_quantum = (
            Decimal("1") / Decimal(base_amount_multiplier)
            if base_amount_multiplier > 0
            else var_quantum
        )
        common_quantum = max(var_quantum, lighter_quantum)
        units = (qty / common_quantum).to_integral_value(rounding=ROUND_DOWN)
        return units * common_quantum

    @staticmethod
    def live_inventory_price_drift_bps(actual: Decimal | None, estimated: Decimal | None) -> Decimal | None:
        if actual is None or estimated is None or estimated == 0:
            return None
        return ((actual - estimated) / estimated) * Decimal("10000")

    @staticmethod
    def variational_api_order_quote_fields(side: str, result: dict[str, Any] | None) -> dict[str, Any]:
        if not isinstance(result, dict):
            return {}
        payload = result.get("result") if isinstance(result.get("result"), dict) else result
        bid = to_decimal(payload.get("bid"))
        ask = to_decimal(payload.get("ask"))
        side_upper = side.strip().upper()
        execution_price = ask if side_upper == "BUY" else bid
        return {
            "quote_id": payload.get("quoteId") or payload.get("quote_id"),
            "quote_bid": decimal_to_str(bid),
            "quote_ask": decimal_to_str(ask),
            "quote_mark_price": payload.get("markPrice") or payload.get("mark_price"),
            "quote_timestamp": payload.get("quoteTimestamp") or payload.get("timestamp"),
            "quote_execution_price": decimal_to_str(execution_price),
        }

    @staticmethod
    def live_inventory_pair_edge_bps(
        *,
        direction: str,
        var_price: Decimal | None,
        lighter_price: Decimal | None,
    ) -> Decimal | None:
        if var_price is None or lighter_price is None or var_price == 0:
            return None
        if direction == DIRECTION_LONG_VAR_SHORT_LIGHTER:
            return ((lighter_price - var_price) / var_price) * Decimal("10000")
        if direction == DIRECTION_SHORT_VAR_LONG_LIGHTER:
            return ((var_price - lighter_price) / var_price) * Decimal("10000")
        return None

    @staticmethod
    def live_inventory_roundtrip_pnl_bps(
        *,
        direction: str,
        var_entry_price: Decimal,
        lighter_entry_price: Decimal,
        var_exit_price: Decimal,
        lighter_exit_price: Decimal,
    ) -> Decimal:
        if var_entry_price <= 0:
            raise ValueError("var_entry_price must be > 0")
        if direction == DIRECTION_LONG_VAR_SHORT_LIGHTER:
            pnl_per_unit = (var_exit_price - var_entry_price) + (lighter_entry_price - lighter_exit_price)
        elif direction == DIRECTION_SHORT_VAR_LONG_LIGHTER:
            pnl_per_unit = (var_entry_price - var_exit_price) + (lighter_exit_price - lighter_entry_price)
        else:
            raise ValueError(f"unsupported direction: {direction}")
        return pnl_per_unit / var_entry_price * Decimal("10000")

    @staticmethod
    def live_inventory_basis_direction_signal(direction: str, z: Decimal) -> Decimal:
        if direction == DIRECTION_SHORT_VAR_LONG_LIGHTER:
            return z
        if direction == DIRECTION_LONG_VAR_SHORT_LIGHTER:
            return -z
        raise ValueError(f"unsupported direction: {direction}")

    def live_inventory_basis_reversion_execution_reserve_bps(self, direction: str) -> Decimal:
        if direction == DIRECTION_LONG_VAR_SHORT_LIGHTER:
            return getattr(
                self,
                "live_inventory_basis_reversion_long_execution_reserve_bps",
                Decimal("4.5"),
            )
        if direction == DIRECTION_SHORT_VAR_LONG_LIGHTER:
            return getattr(
                self,
                "live_inventory_basis_reversion_short_execution_reserve_bps",
                Decimal("3.5"),
            )
        raise ValueError(f"unsupported direction: {direction}")

    def live_inventory_basis_reversion_medians(
        self,
        *,
        now: float,
        direction: str,
    ) -> dict[int, Decimal | None]:
        value_index = 1 if direction == DIRECTION_LONG_VAR_SHORT_LIGHTER else 2
        medians: dict[int, Decimal | None] = {}
        for window_seconds in (300, 1800, 3600):
            cutoff = now - window_seconds
            values = [
                Decimal(str(row[value_index]))
                for row in self.live_inventory_basis_reversion_history
                if row[0] >= cutoff and row[value_index] is not None
            ]
            medians[window_seconds] = median(values) if values else None
        return medians

    def record_live_inventory_basis_reversion_edges(
        self,
        *,
        now: float,
        long_edge_bps: Decimal | None,
        short_edge_bps: Decimal | None,
    ) -> None:
        self.live_inventory_basis_reversion_history.append(
            (
                now,
                None if long_edge_bps is None else float(long_edge_bps),
                None if short_edge_bps is None else float(short_edge_bps),
            )
        )
        cutoff = now - 3600.0
        while self.live_inventory_basis_reversion_history and self.live_inventory_basis_reversion_history[0][0] < cutoff:
            self.live_inventory_basis_reversion_history.popleft()

    @staticmethod
    def live_inventory_basis_v4_percentile(
        values: list[Decimal],
        pct: Decimal = LIVE_INVENTORY_BASIS_V4_ENTRY_PERCENTILE,
    ) -> Decimal | None:
        if not values:
            return None
        ordered = sorted(values)
        index = int(
            (Decimal(len(ordered) - 1) * pct / Decimal("100")).to_integral_value(
                rounding=ROUND_HALF_UP
            )
        )
        return ordered[max(0, min(index, len(ordered) - 1))]

    def live_inventory_basis_v4_window_stats(
        self,
        *,
        now: float,
        window_seconds: int,
        percentile: Decimal,
        min_effective_seconds: int,
        min_coverage_seconds: int,
        require_contiguous: bool,
    ) -> dict[str, Any]:
        cutoff = now - window_seconds
        rows = []
        for row in reversed(self.live_inventory_basis_v4_history):
            if row[0] <= cutoff:
                break
            rows.append(row)
        rows.reverse()
        values = [value for _, value in rows]
        coverage_seconds = max(0.0, now - rows[0][0]) if rows else 0.0
        effective_seconds = min(
            len(rows) * LIVE_INVENTORY_BASIS_V4_HISTORY_SAMPLE_SECONDS,
            window_seconds,
        )
        max_gap_seconds = max(
            (
                current[0] - previous[0]
                for previous, current in zip(rows, rows[1:])
            ),
            default=0.0,
        )
        median_bps = median(values) if values else None
        mad_bps = (
            median([abs(value - median_bps) for value in values])
            if median_bps is not None
            else None
        )
        threshold_bps = self.live_inventory_basis_v4_percentile(
            values,
            percentile,
        )
        ready = bool(
            len(rows) >= LIVE_INVENTORY_BASIS_V4_MIN_HISTORY_SAMPLES
            and effective_seconds >= min_effective_seconds
            and coverage_seconds >= min_coverage_seconds
            and (
                not require_contiguous
                or max_gap_seconds <= LIVE_INVENTORY_BASIS_V4_MAX_SAMPLE_GAP_SECONDS
            )
        )
        return {
            "window_seconds": window_seconds,
            "count": len(rows),
            "coverage_seconds": f"{coverage_seconds:.3f}",
            "effective_seconds": effective_seconds,
            "max_sample_gap_seconds": f"{max_gap_seconds:.3f}",
            "percentile": decimal_to_str(percentile),
            "threshold_bps": decimal_to_str(threshold_bps),
            "median_bps": decimal_to_str(median_bps),
            "mad_bps": decimal_to_str(mad_bps),
            "ready": ready,
        }

    def live_inventory_basis_v4_anchor_projection(self, *, now: float) -> dict[str, Any]:
        cached_at = float(
            getattr(self, "live_inventory_basis_v4_projection_cached_at", 0.0)
            or 0.0
        )
        cached = getattr(self, "live_inventory_basis_v4_projection_cache", {})
        if cached and now - cached_at < 300.0:
            return dict(cached)

        rows = deque(
            row
            for row in self.live_inventory_basis_v4_history
            if row[0] > now - LIVE_INVENTORY_BASIS_V4_ANCHOR_WINDOW_SECONDS
        )
        projected_seconds: int | None = None
        for elapsed in range(
            0,
            LIVE_INVENTORY_BASIS_V4_ANCHOR_WINDOW_SECONDS
            + LIVE_INVENTORY_BASIS_V4_HISTORY_SAMPLE_SECONDS,
            LIVE_INVENTORY_BASIS_V4_HISTORY_SAMPLE_SECONDS,
        ):
            future = now + elapsed
            cutoff = future - LIVE_INVENTORY_BASIS_V4_ANCHOR_WINDOW_SECONDS
            while rows and rows[0][0] <= cutoff:
                rows.popleft()
            if elapsed:
                rows.append((future, Decimal("0")))
            coverage_seconds = max(0.0, future - rows[0][0]) if rows else 0.0
            effective_seconds = min(
                len(rows) * LIVE_INVENTORY_BASIS_V4_HISTORY_SAMPLE_SECONDS,
                LIVE_INVENTORY_BASIS_V4_ANCHOR_WINDOW_SECONDS,
            )
            if (
                len(rows) >= LIVE_INVENTORY_BASIS_V4_MIN_HISTORY_SAMPLES
                and Decimal(str(coverage_seconds))
                >= Decimal(LIVE_INVENTORY_BASIS_V4_ANCHOR_WINDOW_SECONDS)
                * LIVE_INVENTORY_BASIS_V4_MIN_WINDOW_COVERAGE
                and effective_seconds
                >= LIVE_INVENTORY_BASIS_V4_MIN_ANCHOR_EFFECTIVE_SECONDS
            ):
                projected_seconds = elapsed
                break

        projected_at = (
            datetime.fromtimestamp(now + projected_seconds, tz=timezone.utc).isoformat()
            if projected_seconds is not None
            else None
        )
        result = {
            "v4_anchor_projected_ready_seconds": projected_seconds,
            "v4_anchor_projected_ready_at": projected_at,
            "v4_anchor_projection_assumption": "continuous_valid_30s_samples",
        }
        self.live_inventory_basis_v4_projection_cached_at = now
        self.live_inventory_basis_v4_projection_cache = dict(result)
        return result

    def load_live_inventory_basis_v4_history(self, *, asset: str) -> dict[str, Any]:
        self.live_inventory_basis_v4_history.clear()
        self.live_inventory_basis_v4_history_ready = False
        self.live_inventory_basis_v4_history_reason = "insufficient_rolling_7d_anchor"
        self.live_inventory_basis_v4_threshold_cached_at = 0.0
        self.live_inventory_basis_v4_threshold_cache = None
        self.live_inventory_basis_v4_shadow_cached_at = 0.0
        self.live_inventory_basis_v4_shadow_cache = {}
        now = datetime.now(timezone.utc).timestamp()
        cutoff = now - LIVE_INVENTORY_BASIS_V4_LONG_WINDOW_SECONDS
        next_sample_at = cutoff
        source_rows = read_basis_samples(
            self.output_dir / "basis_samples",
            limit=100000,
            asset_filter=asset,
            sample_kind_filter="baseline",
            sample_quality_filter="valid",
        )
        for row in source_rows:
            logged_at = self._parse_iso_ts(str(row.get("logged_at") or ""))
            edge_bps = to_decimal(row.get("short_edge_bps"))
            if logged_at is None or edge_bps is None:
                continue
            timestamp = logged_at.timestamp()
            if timestamp < cutoff or timestamp >= now or timestamp < next_sample_at:
                continue
            self.live_inventory_basis_v4_history.append((timestamp, edge_bps))
            next_sample_at = timestamp + LIVE_INVENTORY_BASIS_V4_HISTORY_SAMPLE_SECONDS
        latest_at = (
            self.live_inventory_basis_v4_history[-1][0]
            if self.live_inventory_basis_v4_history
            else None
        )
        latest_age_seconds = None if latest_at is None else max(0.0, now - latest_at)
        if (
            latest_age_seconds is not None
            and latest_age_seconds <= LIVE_INVENTORY_BASIS_V4_MAX_SAMPLE_GAP_SECONDS
        ):
            threshold, context = self.live_inventory_basis_v4_entry_threshold(now=now)
            self.live_inventory_basis_v4_history_ready = threshold is not None
            if threshold is not None:
                self.live_inventory_basis_v4_history_reason = "ready"
            elif not context.get("v4_anchor_ready"):
                self.live_inventory_basis_v4_history_reason = "insufficient_rolling_7d_anchor"
            else:
                self.live_inventory_basis_v4_history_reason = "recent_1h_health_not_ready"
        else:
            context = {}
            self.live_inventory_basis_v4_history_reason = "history_latest_sample_stale"
        self.live_inventory_basis_v4_next_history_sample_at = (
            (latest_at + LIVE_INVENTORY_BASIS_V4_HISTORY_SAMPLE_SECONDS)
            if latest_at is not None
            else now
        )
        return {
            "profile": self.live_inventory_basis_v4_profile,
            "asset": asset,
            "source_rows": len(source_rows),
            "history_samples": len(self.live_inventory_basis_v4_history),
            "latest_age_seconds": latest_age_seconds,
            "ready": self.live_inventory_basis_v4_history_ready,
            "reason": self.live_inventory_basis_v4_history_reason,
            **context,
        }

    def live_inventory_basis_v4_entry_threshold(
        self,
        *,
        now: float,
    ) -> tuple[Decimal | None, dict[str, Any]]:
        cached = getattr(
            self,
            "live_inventory_basis_v4_threshold_cache",
            None,
        )
        cached_at = float(
            getattr(
                self,
                "live_inventory_basis_v4_threshold_cached_at",
                0.0,
            )
            or 0.0
        )
        if (
            cached is not None
            and now - cached_at < LIVE_INVENTORY_BASIS_V4_THRESHOLD_CACHE_SECONDS
        ):
            return cached[0], dict(cached[1])

        def finish(
            threshold_bps: Decimal | None,
            threshold_context: dict[str, Any],
        ) -> tuple[Decimal | None, dict[str, Any]]:
            self.live_inventory_basis_v4_threshold_cached_at = now
            self.live_inventory_basis_v4_threshold_cache = (
                threshold_bps,
                dict(threshold_context),
            )
            return threshold_bps, threshold_context

        anchor_cutoff = now - LIVE_INVENTORY_BASIS_V4_ANCHOR_WINDOW_SECONDS
        anchor_rows = []
        for row in reversed(self.live_inventory_basis_v4_history):
            if row[0] <= anchor_cutoff:
                break
            anchor_rows.append(row)
        anchor_rows.reverse()
        anchor_coverage_seconds = (
            max(0.0, now - anchor_rows[0][0]) if anchor_rows else 0.0
        )
        anchor_max_gap_seconds = max(
            (
                current[0] - previous[0]
                for previous, current in zip(anchor_rows, anchor_rows[1:])
            ),
            default=0.0,
        )
        anchor_effective_seconds = min(
            len(anchor_rows) * LIVE_INVENTORY_BASIS_V4_HISTORY_SAMPLE_SECONDS,
            LIVE_INVENTORY_BASIS_V4_ANCHOR_WINDOW_SECONDS,
        )
        anchor_missing_effective_seconds = max(
            0,
            LIVE_INVENTORY_BASIS_V4_MIN_ANCHOR_EFFECTIVE_SECONDS
            - anchor_effective_seconds,
        )
        anchor_ready = (
            len(anchor_rows) >= LIVE_INVENTORY_BASIS_V4_MIN_HISTORY_SAMPLES
            and Decimal(str(anchor_coverage_seconds))
            >= Decimal(LIVE_INVENTORY_BASIS_V4_ANCHOR_WINDOW_SECONDS)
            * LIVE_INVENTORY_BASIS_V4_MIN_WINDOW_COVERAGE
            and anchor_effective_seconds
            >= LIVE_INVENTORY_BASIS_V4_MIN_ANCHOR_EFFECTIVE_SECONDS
        )

        health_cutoff = now - LIVE_INVENTORY_BASIS_V4_HEALTH_WINDOW_SECONDS
        health_rows = [row for row in anchor_rows if row[0] > health_cutoff]
        health_coverage_seconds = (
            max(0.0, now - health_rows[0][0]) if health_rows else 0.0
        )
        health_max_gap_seconds = max(
            (
                current[0] - previous[0]
                for previous, current in zip(health_rows, health_rows[1:])
            ),
            default=0.0,
        )
        health_ready_observed = (
            len(health_rows) >= LIVE_INVENTORY_BASIS_V4_MIN_HISTORY_SAMPLES
            and Decimal(str(health_coverage_seconds))
            >= Decimal(LIVE_INVENTORY_BASIS_V4_HEALTH_WINDOW_SECONDS)
            * LIVE_INVENTORY_BASIS_V4_MIN_WINDOW_COVERAGE
            and health_max_gap_seconds
            <= LIVE_INVENTORY_BASIS_V4_MAX_SAMPLE_GAP_SECONDS
        )
        health_gate_bypassed = bool(
            getattr(
                self,
                "live_inventory_basis_v4_test_skip_recent_health",
                False,
            )
        )
        health_ready = health_ready_observed or health_gate_bypassed
        fast_context = self.live_inventory_basis_v4_window_stats(
            now=now,
            window_seconds=LIVE_INVENTORY_BASIS_V4_FAST_WINDOW_SECONDS,
            percentile=LIVE_INVENTORY_BASIS_V4_FAST_ENTRY_PERCENTILE,
            min_effective_seconds=LIVE_INVENTORY_BASIS_V4_FAST_MIN_EFFECTIVE_SECONDS,
            min_coverage_seconds=LIVE_INVENTORY_BASIS_V4_FAST_MIN_EFFECTIVE_SECONDS,
            require_contiguous=True,
        )
        shadow_cached_at = float(
            getattr(self, "live_inventory_basis_v4_shadow_cached_at", 0.0)
            or 0.0
        )
        shadow_cache = getattr(
            self,
            "live_inventory_basis_v4_shadow_cache",
            {},
        )
        if (
            shadow_cache
            and now - shadow_cached_at
            < LIVE_INVENTORY_BASIS_V4_SHADOW_CACHE_SECONDS
        ):
            mid_context = dict(shadow_cache["mid"])
            long_context = dict(shadow_cache["long"])
        else:
            mid_context = self.live_inventory_basis_v4_window_stats(
                now=now,
                window_seconds=LIVE_INVENTORY_BASIS_V4_MID_WINDOW_SECONDS,
                percentile=LIVE_INVENTORY_BASIS_V4_ENTRY_PERCENTILE,
                min_effective_seconds=5 * 86400,
                min_coverage_seconds=int(
                    LIVE_INVENTORY_BASIS_V4_MID_WINDOW_SECONDS
                    * float(LIVE_INVENTORY_BASIS_V4_MIN_WINDOW_COVERAGE)
                ),
                require_contiguous=False,
            )
            long_context = self.live_inventory_basis_v4_window_stats(
                now=now,
                window_seconds=LIVE_INVENTORY_BASIS_V4_LONG_WINDOW_SECONDS,
                percentile=LIVE_INVENTORY_BASIS_V4_ENTRY_PERCENTILE,
                min_effective_seconds=10 * 86400,
                min_coverage_seconds=int(
                    LIVE_INVENTORY_BASIS_V4_LONG_WINDOW_SECONDS
                    * float(LIVE_INVENTORY_BASIS_V4_MIN_WINDOW_COVERAGE)
                ),
                require_contiguous=False,
            )
            self.live_inventory_basis_v4_shadow_cached_at = now
            self.live_inventory_basis_v4_shadow_cache = {
                "mid": dict(mid_context),
                "long": dict(long_context),
            }
        context = {
            "v4_history_samples": len(self.live_inventory_basis_v4_history),
            "v4_anchor_window_seconds": LIVE_INVENTORY_BASIS_V4_ANCHOR_WINDOW_SECONDS,
            "v4_anchor_count": len(anchor_rows),
            "v4_anchor_coverage_seconds": f"{anchor_coverage_seconds:.3f}",
            "v4_anchor_effective_seconds": anchor_effective_seconds,
            "v4_anchor_min_effective_seconds": LIVE_INVENTORY_BASIS_V4_MIN_ANCHOR_EFFECTIVE_SECONDS,
            "v4_anchor_missing_effective_seconds": anchor_missing_effective_seconds,
            "v4_anchor_progress_pct": f"{min(100.0, anchor_effective_seconds / LIVE_INVENTORY_BASIS_V4_MIN_ANCHOR_EFFECTIVE_SECONDS * 100):.2f}",
            "v4_anchor_max_sample_gap_seconds": f"{anchor_max_gap_seconds:.3f}",
            "v4_anchor_ready": anchor_ready,
            "v4_health_window_seconds": LIVE_INVENTORY_BASIS_V4_HEALTH_WINDOW_SECONDS,
            "v4_health_count": len(health_rows),
            "v4_health_coverage_seconds": f"{health_coverage_seconds:.3f}",
            "v4_health_max_sample_gap_seconds": f"{health_max_gap_seconds:.3f}",
            "v4_health_ready": health_ready,
            "v4_health_ready_observed": health_ready_observed,
            "v4_health_gate_bypassed": health_gate_bypassed,
            **{
                f"v4_fast_{key}": value
                for key, value in fast_context.items()
            },
            **{
                f"v4_mid_{key}": value
                for key, value in mid_context.items()
            },
            **{
                f"v4_long_{key}": value
                for key, value in long_context.items()
            },
            # Compatibility fields used by the existing analyzer.
            "v4_mature_windows": (
                [LIVE_INVENTORY_BASIS_V4_ANCHOR_WINDOW_SECONDS]
                if anchor_ready and health_ready
                else []
            ),
            "v4_baseline_window_seconds": LIVE_INVENTORY_BASIS_V4_ANCHOR_WINDOW_SECONDS,
            "v4_baseline_count": len(anchor_rows),
            "v4_baseline_coverage_seconds": f"{anchor_coverage_seconds:.3f}",
            "v4_baseline_max_sample_gap_seconds": f"{anchor_max_gap_seconds:.3f}",
            **self.live_inventory_basis_v4_anchor_projection(now=now),
        }
        if not anchor_ready or not health_ready:
            return finish(None, context)

        values = [edge_bps for _, edge_bps in anchor_rows]
        anchor_threshold = self.live_inventory_basis_v4_percentile(values)
        if anchor_threshold is None:
            return finish(None, context)
        fast_threshold = to_decimal(fast_context.get("threshold_bps"))
        raw_threshold = (
            max(anchor_threshold, fast_threshold)
            if fast_context["ready"] and fast_threshold is not None
            else anchor_threshold
        )
        weekend_context = v4_weekend_regime_context(now)
        if weekend_context["v4_weekend_transition_active"]:
            transition_candidates = [raw_threshold]
            for window_context in (mid_context, long_context):
                window_threshold = to_decimal(window_context.get("threshold_bps"))
                if window_context.get("ready") and window_threshold is not None:
                    transition_candidates.append(window_threshold)
            raw_threshold = max(transition_candidates)
        entry_execution_reserve_bps = (
            self.live_inventory_basis_v4_entry_execution_reserve_bps()
        )
        threshold = raw_threshold + entry_execution_reserve_bps
        market_noise_bps = self.percentile_decimal(
            [
                abs(value)
                for value in getattr(
                    self,
                    "live_inventory_basis_sample_move_bps_samples",
                    [],
                )
            ],
            80,
        )
        ladder_slippages = [
            value
            for item in getattr(
                self,
                "live_inventory_latest_basis_size_ladder",
                [],
            )
            if (
                value := to_decimal(
                    (item.get("short_entry_lighter_depth") or {}).get(
                        "slippage_bps"
                    )
                )
            )
            is not None
        ]
        incremental_depth_cost_bps = max(
            (
                abs(right - left)
                for left, right in zip(
                    ladder_slippages,
                    ladder_slippages[1:],
                )
            ),
            default=Decimal("0"),
        )
        recent_pair_execution_error_bps = self.percentile_decimal(
            getattr(self, "live_inventory_execution_loss_bps_samples", []),
            80,
        )
        gradient_thresholds = v4_real_gradient_thresholds(
            history_values=values,
            base_threshold_bps=threshold,
            entry_execution_reserve_bps=entry_execution_reserve_bps,
            actual_market_noise_bps=market_noise_bps,
            incremental_depth_cost_bps=incremental_depth_cost_bps,
            recent_pair_execution_error_bps=recent_pair_execution_error_bps,
        )
        return finish(threshold, {
            **context,
            **weekend_context,
            "v4_entry_percentile": decimal_to_str(
                LIVE_INVENTORY_BASIS_V4_ENTRY_PERCENTILE
            ),
            "v4_7d_entry_threshold_bps": decimal_to_str(anchor_threshold),
            "v4_fast_threshold_applied": bool(
                fast_context["ready"]
                and fast_threshold is not None
                and fast_threshold > anchor_threshold
            ),
            "v4_raw_entry_threshold_bps": decimal_to_str(raw_threshold),
            "v4_entry_execution_reserve_bps": decimal_to_str(
                entry_execution_reserve_bps
            ),
            **self.live_inventory_basis_v4_entry_calibration_payload(),
            "v4_entry_threshold_bps": decimal_to_str(threshold),
            "v4_real_gradient_tier_percentiles": [
                decimal_to_str(value)
                for value in LIVE_INVENTORY_BASIS_V4_REAL_GRADIENT_PERCENTILES
            ],
            "v4_real_gradient_tier_thresholds_bps": [
                decimal_to_str(value) for value in gradient_thresholds
            ],
            "v4_real_gradient_market_noise_bps": decimal_to_str(
                market_noise_bps
            ),
            "v4_real_gradient_incremental_depth_cost_bps": decimal_to_str(
                incremental_depth_cost_bps
            ),
            "v4_real_gradient_pair_execution_error_bps": decimal_to_str(
                recent_pair_execution_error_bps
            ),
        })

    def record_live_inventory_basis_v4_edge(
        self,
        *,
        now: float,
        short_edge_bps: Decimal,
    ) -> bool:
        if now < self.live_inventory_basis_v4_next_history_sample_at:
            return False
        self.live_inventory_basis_v4_history.append((now, short_edge_bps))
        self.live_inventory_basis_v4_next_history_sample_at = (
            now + LIVE_INVENTORY_BASIS_V4_HISTORY_SAMPLE_SECONDS
        )
        cutoff = now - LIVE_INVENTORY_BASIS_V4_LONG_WINDOW_SECONDS
        while (
            self.live_inventory_basis_v4_history
            and self.live_inventory_basis_v4_history[0][0] <= cutoff
        ):
            self.live_inventory_basis_v4_history.popleft()
        return True

    def live_inventory_basis_v4_update_rearm(
        self,
        *,
        short_edge_bps: Decimal,
        entry_threshold_bps: Decimal | None,
    ) -> tuple[bool, dict[str, Any]]:
        required = bool(
            getattr(self, "live_inventory_v4_rearm_required", False)
        )
        threshold = (
            entry_threshold_bps
            if entry_threshold_bps is not None
            else getattr(
                self,
                "live_inventory_v4_rearm_threshold_bps",
                None,
            )
        )
        reset_threshold = (
            threshold - LIVE_INVENTORY_BASIS_V4_REARM_BUFFER_BPS
            if threshold is not None
            else None
        )
        if not required or getattr(self, "live_inventory_open_lots", []):
            return False, {
                **self.live_inventory_v4_episode_payload(),
                "v4_rearm_reset_threshold_bps": decimal_to_str(reset_threshold),
                "v4_rearm_signal_below_reset": False,
            }
        below_reset = bool(
            reset_threshold is not None and short_edge_bps <= reset_threshold
        )
        if below_reset:
            self.live_inventory_v4_rearm_confirmation_count += 1
        else:
            self.live_inventory_v4_rearm_confirmation_count = 0
        rearmed = (
            self.live_inventory_v4_rearm_confirmation_count
            >= LIVE_INVENTORY_BASIS_V4_REARM_CONFIRM_SAMPLES
        )
        if rearmed:
            self.live_inventory_v4_rearm_required = False
            self.live_inventory_v4_rearm_confirmation_count = 0
            self.live_inventory_v4_rearm_reason = None
            self.live_inventory_v4_rearm_threshold_bps = None
            self.live_inventory_v4_episode_id = None
            self.live_inventory_v4_next_tranche_index = 1
            self.live_inventory_v4_gradient_tier_states = {
                tier: {"armed": True, "reset_seen": False}
                for tier in range(
                    1,
                    LIVE_INVENTORY_BASIS_V4_REAL_GRADIENT_MAX_TIERS + 1,
                )
            }
            tier_window = getattr(
                self,
                "live_inventory_v4_gradient_entry_tier_window",
                None,
            )
            if isinstance(tier_window, deque):
                tier_window.clear()
            self.reset_live_inventory_basis_v4_shadow_gradient()
        return rearmed, {
            **self.live_inventory_v4_episode_payload(),
            "v4_rearm_reset_threshold_bps": decimal_to_str(reset_threshold),
            "v4_rearm_signal_below_reset": below_reset,
        }

    def live_inventory_basis_v4_active_gradient_tier(
        self,
        *,
        raw_tier: int,
        edge_bps: Decimal,
        thresholds_bps: list[Decimal],
    ) -> int:
        window = getattr(
            self,
            "live_inventory_v4_gradient_entry_tier_window",
            None,
        )
        if not isinstance(window, deque):
            window = deque(
                maxlen=(
                    LIVE_INVENTORY_BASIS_V4_REAL_GRADIENT_ENTRY_CONFIRM_WINDOW_SAMPLES
                )
            )
            self.live_inventory_v4_gradient_entry_tier_window = window
        window.append(max(0, int(raw_tier)))
        confirmed_tier = v4_real_gradient_confirmed_tier(
            window,
            latest_tier=raw_tier,
        )
        states = getattr(self, "live_inventory_v4_gradient_tier_states", None)
        if not isinstance(states, dict):
            states = {}
            self.live_inventory_v4_gradient_tier_states = states
        active_tier = 0
        for tier, threshold in enumerate(thresholds_bps, start=1):
            state = states.setdefault(
                tier,
                {"armed": True, "reset_seen": False},
            )
            if not state.get("armed", True):
                if edge_bps < threshold:
                    state["reset_seen"] = True
                if state.get("reset_seen") and confirmed_tier >= tier:
                    state["armed"] = True
                    state["reset_seen"] = False
                    state["rearmed_at"] = utc_now()
            if state.get("armed", True) and confirmed_tier >= tier:
                active_tier = tier
        return active_tier

    def mark_live_inventory_gradient_tier_closed(
        self,
        *,
        tier: int | None,
        edge_bps: Decimal,
        thresholds_bps: list[Decimal],
    ) -> None:
        if tier is None or tier <= 0 or tier > len(thresholds_bps):
            return
        states = getattr(self, "live_inventory_v4_gradient_tier_states", None)
        if not isinstance(states, dict):
            states = {}
            self.live_inventory_v4_gradient_tier_states = states
        threshold = thresholds_bps[tier - 1]
        states[tier] = {
            "armed": False,
            "reset_seen": edge_bps < threshold,
            "closed_at": utc_now(),
        }

    def require_live_inventory_basis_v4_rearm(
        self,
        *,
        exit_reason: str,
        entry_threshold_bps: Decimal | None,
    ) -> None:
        self.live_inventory_v4_rearm_required = True
        self.live_inventory_v4_rearm_confirmation_count = 0
        self.live_inventory_v4_rearm_reason = exit_reason
        self.live_inventory_v4_rearm_threshold_bps = entry_threshold_bps
        self.live_inventory_v4_last_exit_reason = exit_reason
        self.live_inventory_v4_last_exit_at = utc_now()
        self.live_inventory_v4_next_tranche_index = 1
        if exit_reason == "max_unrealized_loss_bps":
            self.live_inventory_v4_batch_halted_reason = (
                "v4_batch_halted_after_stop_loss"
            )

    def live_inventory_basis_abs_entry_ok(self, *, direction: str, basis_bps: Decimal, threshold_bps: Decimal | None = None) -> bool:
        threshold = self.live_inventory_basis_min_abs_entry_bps if threshold_bps is None else threshold_bps
        if threshold <= 0:
            return True
        if direction == DIRECTION_LONG_VAR_SHORT_LIGHTER:
            return basis_bps <= -threshold
        if direction == DIRECTION_SHORT_VAR_LONG_LIGHTER:
            return basis_bps >= threshold
        raise ValueError(f"unsupported direction: {direction}")

    async def live_inventory_lighter_slippage_bps(self, *, lighter_side: str, qty: Decimal) -> tuple[Decimal | None, Decimal | None]:
        depth = await self.estimate_lighter_fill_details(lighter_side, qty)
        estimated_fill = to_decimal(depth.get("estimated_fill_price"))
        reference = to_decimal(depth.get("reference_price"))
        if estimated_fill is None or reference is None:
            return None, None
        if lighter_side.strip().upper() == "BUY":
            slippage_bps = ((estimated_fill - reference) / reference) * Decimal("10000") if reference else None
        else:
            slippage_bps = ((reference - estimated_fill) / reference) * Decimal("10000") if reference else None
        if slippage_bps is not None and slippage_bps < 0:
            slippage_bps = Decimal("0")
        return estimated_fill, slippage_bps

    async def live_inventory_lighter_depth_context(self, *, lighter_side: str, qty: Decimal) -> dict[str, Any]:
        depth = await self.estimate_lighter_fill_details(lighter_side, qty)
        estimated_fill = to_decimal(depth.get("estimated_fill_price"))
        reference = to_decimal(depth.get("reference_price"))
        slippage_bps: Decimal | None = None
        if estimated_fill is not None and reference is not None:
            if lighter_side.strip().upper() == "BUY":
                slippage_bps = ((estimated_fill - reference) / reference) * Decimal("10000") if reference else None
            else:
                slippage_bps = ((reference - estimated_fill) / reference) * Decimal("10000") if reference else None
            if slippage_bps is not None and slippage_bps < 0:
                slippage_bps = Decimal("0")
        return {**depth, "slippage_bps": decimal_to_str(slippage_bps)}

    async def live_inventory_basis_refreshed_exit_context(
        self,
        *,
        asset: str,
        direction: str,
        qty: Decimal,
        entry_var_price: Decimal,
        entry_lighter_price: Decimal,
        exit_lighter_side: str,
    ) -> dict[str, Any]:
        refreshed_quote, refresh_quote_ms = await self.fetch_live_inventory_basis_quote(
            asset=asset
        )
        refreshed_var_bid = (
            to_decimal(refreshed_quote.get("bid")) if refreshed_quote else None
        )
        refreshed_var_ask = (
            to_decimal(refreshed_quote.get("ask")) if refreshed_quote else None
        )
        lighter_best_bid, lighter_best_ask = await self.get_lighter_best_bid_ask()
        if (
            refreshed_var_bid is None
            or refreshed_var_ask is None
            or lighter_best_bid is None
            or lighter_best_ask is None
        ):
            return {
                "reason": "basis_exit_refresh_quote_unavailable",
                "refresh_quote_ms": refresh_quote_ms,
            }

        if direction == DIRECTION_LONG_VAR_SHORT_LIGHTER:
            refreshed_var_exit_price = refreshed_var_bid
            refreshed_lighter_top_price = lighter_best_ask
        else:
            refreshed_var_exit_price = refreshed_var_ask
            refreshed_lighter_top_price = lighter_best_bid
        _, _, refreshed_pnl = self.live_inventory_pair_pnl(
            direction=direction,
            qty=qty,
            entry_var_price=entry_var_price,
            entry_lighter_price=entry_lighter_price,
            exit_var_price=refreshed_var_exit_price,
            exit_lighter_price=refreshed_lighter_top_price,
        )
        notional = qty * entry_var_price
        refreshed_pnl_bps = (
            refreshed_pnl / notional * Decimal("10000") if notional else None
        )
        exit_lighter_depth = await self.live_inventory_lighter_depth_context(
            lighter_side=exit_lighter_side,
            qty=qty,
        )
        depth_exit_price = to_decimal(exit_lighter_depth.get("estimated_fill_price"))
        if depth_exit_price is None:
            return {
                "reason": "basis_exit_lighter_depth_insufficient",
                "refresh_quote_ms": refresh_quote_ms,
                "refreshed_var_exit_price": refreshed_var_exit_price,
                "refreshed_pnl_bps": refreshed_pnl_bps,
                "exit_lighter_depth": exit_lighter_depth,
            }
        _, _, executable_pnl = self.live_inventory_pair_pnl(
            direction=direction,
            qty=qty,
            entry_var_price=entry_var_price,
            entry_lighter_price=entry_lighter_price,
            exit_var_price=refreshed_var_exit_price,
            exit_lighter_price=depth_exit_price,
        )
        executable_pnl_bps = (
            executable_pnl / notional * Decimal("10000") if notional else None
        )
        return {
            "reason": None,
            "refresh_quote_ms": refresh_quote_ms,
            "refreshed_var_exit_price": refreshed_var_exit_price,
            "refreshed_lighter_top_price": refreshed_lighter_top_price,
            "refreshed_pnl_bps": refreshed_pnl_bps,
            "exit_lighter_depth": exit_lighter_depth,
            "executable_lighter_exit_price": depth_exit_price,
            "executable_pnl": executable_pnl,
            "executable_pnl_bps": executable_pnl_bps,
        }

    async def live_inventory_basis_v4_fast_refresh_exit_context(
        self,
        *,
        asset: str,
        lot: dict[str, Any],
        direction: str,
        qty: Decimal,
        entry_var_price: Decimal,
        entry_lighter_price: Decimal,
        exit_lighter_side: str,
        effective_min_exit_pnl_bps: Decimal,
    ) -> dict[str, Any]:
        started = time.monotonic()
        observations: list[dict[str, Any]] = []
        selected_context: dict[str, Any] | None = None
        last_block_reason = "v4_exit_confirmation_pending"
        max_refreshed_pnl_bps: Decimal | None = None
        max_executable_pnl_bps: Decimal | None = None
        confirmation_count = int(lot.get("v4_exit_confirmation_count") or 0)
        confirmation_mode: str | None = None
        strong_single_context = self.live_inventory_basis_v4_strong_single_context(
            effective_min_exit_pnl_bps=effective_min_exit_pnl_bps
        )
        strong_single_threshold_bps = strong_single_context["threshold_bps"]
        strong_stability_values = [
            value
            for value in (
                to_decimal(item)
                for item in list(
                    lot.get("v4_exit_strong_stability_values") or []
                )
            )
            if value is not None
        ][-LIVE_INVENTORY_BASIS_V4_EXIT_STRONG_SINGLE_STABILITY_SAMPLES:]

        for attempt in range(
            1, LIVE_INVENTORY_BASIS_V4_EXIT_FAST_REFRESH_ATTEMPTS + 1
        ):
            context = await self.live_inventory_basis_refreshed_exit_context(
                asset=asset,
                direction=direction,
                qty=qty,
                entry_var_price=entry_var_price,
                entry_lighter_price=entry_lighter_price,
                exit_lighter_side=exit_lighter_side,
            )
            refreshed_pnl_bps = to_decimal(context.get("refreshed_pnl_bps"))
            executable_pnl_bps = to_decimal(context.get("executable_pnl_bps"))
            if refreshed_pnl_bps is not None:
                max_refreshed_pnl_bps = (
                    refreshed_pnl_bps
                    if max_refreshed_pnl_bps is None
                    else max(max_refreshed_pnl_bps, refreshed_pnl_bps)
                )
            if executable_pnl_bps is not None:
                max_executable_pnl_bps = (
                    executable_pnl_bps
                    if max_executable_pnl_bps is None
                    else max(max_executable_pnl_bps, executable_pnl_bps)
                )
                prior_executable_mfe = to_decimal(
                    lot.get("executable_exit_mfe_pnl_bps")
                )
                lot["executable_exit_mfe_pnl_bps"] = decimal_to_str(
                    executable_pnl_bps
                    if prior_executable_mfe is None
                    else max(prior_executable_mfe, executable_pnl_bps)
                )

            observation_reason = context.get("reason")
            eligible = False
            if observation_reason is not None:
                last_block_reason = str(observation_reason)
            elif (
                refreshed_pnl_bps is None
                or refreshed_pnl_bps < effective_min_exit_pnl_bps
            ):
                last_block_reason = "basis_exit_refresh_pnl_below_threshold"
            elif (
                executable_pnl_bps is None
                or executable_pnl_bps < effective_min_exit_pnl_bps
            ):
                last_block_reason = "basis_exit_lighter_depth_pnl_below_threshold"
            else:
                eligible = True
                last_block_reason = "v4_exit_confirmation_pending"

            refresh_quote_ms = to_decimal(context.get("refresh_quote_ms"))
            lighter_slippage_bps = to_decimal(
                (context.get("exit_lighter_depth") or {}).get("slippage_bps")
            )
            if observation_reason is None and executable_pnl_bps is not None:
                strong_stability_values.append(executable_pnl_bps)
                strong_stability_values = strong_stability_values[
                    -LIVE_INVENTORY_BASIS_V4_EXIT_STRONG_SINGLE_STABILITY_SAMPLES:
                ]
                lot["v4_exit_strong_stability_values"] = [
                    decimal_to_str(value) for value in strong_stability_values
                ]
            strong_single_range_bps = (
                max(strong_stability_values) - min(strong_stability_values)
                if len(strong_stability_values)
                >= LIVE_INVENTORY_BASIS_V4_EXIT_STRONG_SINGLE_STABILITY_SAMPLES
                else None
            )
            strong_single_stable = bool(
                strong_single_range_bps is not None
                and strong_single_range_bps
                <= LIVE_INVENTORY_BASIS_V4_EXIT_STRONG_SINGLE_MAX_RANGE_BPS
            )
            strong_single_latency_ok = bool(
                refresh_quote_ms is not None
                and refresh_quote_ms
                <= LIVE_INVENTORY_BASIS_V4_EXIT_STRONG_SINGLE_MAX_REFRESH_MS
            )
            strong_single_depth_ok = bool(
                lighter_slippage_bps is not None
                and lighter_slippage_bps
                <= LIVE_INVENTORY_BASIS_V4_EXIT_STRONG_SINGLE_MAX_DEPTH_SLIPPAGE_BPS
            )

            confirmed, confirmation_count = (
                self.live_inventory_basis_v4_confirm_exit_candidate(
                    lot,
                    eligible=eligible,
                )
            )
            strong_single_confirmed = bool(
                not confirmed
                and strong_single_context["enabled"]
                and eligible
                and executable_pnl_bps is not None
                and executable_pnl_bps >= strong_single_threshold_bps
                and strong_single_stable
                and strong_single_latency_ok
                and strong_single_depth_ok
            )
            if strong_single_confirmed:
                confirmed = True
                confirmation_mode = "strong_single"
            elif confirmed:
                confirmation_mode = "two_of_three"
            observations.append(
                {
                    "attempt": attempt,
                    "reason": None if confirmed else last_block_reason,
                    "refresh_quote_ms": decimal_to_str(refresh_quote_ms),
                    "refreshed_pnl_bps": decimal_to_str(refreshed_pnl_bps),
                    "executable_pnl_bps": decimal_to_str(executable_pnl_bps),
                    "lighter_slippage_bps": decimal_to_str(
                        lighter_slippage_bps
                    ),
                    "confirmation_count": confirmation_count,
                    "confirmation_window": list(
                        lot.get("v4_exit_confirmation_window") or []
                    ),
                    "strong_single_threshold_bps": decimal_to_str(
                        strong_single_threshold_bps
                    ),
                    "strong_single_enabled": strong_single_context["enabled"],
                    "strong_single_sample_count": strong_single_context[
                        "sample_count"
                    ],
                    "strong_single_shortfall_reserve_bps": decimal_to_str(
                        strong_single_context["mode_reserve_bps"]
                    ),
                    "strong_single_range_bps": decimal_to_str(
                        strong_single_range_bps
                    ),
                    "strong_single_stable": strong_single_stable,
                    "strong_single_latency_ok": strong_single_latency_ok,
                    "strong_single_depth_ok": strong_single_depth_ok,
                    "confirmation_mode": confirmation_mode if confirmed else None,
                }
            )
            if confirmed:
                selected_context = context
                break
            # Do not amplify an exchange/extension failure into the runtime
            # fuse by issuing the remaining burst requests immediately.
            if observation_reason is not None:
                break
            if attempt < LIVE_INVENTORY_BASIS_V4_EXIT_FAST_REFRESH_ATTEMPTS:
                await asyncio.sleep(
                    LIVE_INVENTORY_BASIS_V4_EXIT_FAST_REFRESH_INTERVAL_SECONDS
                )

        return {
            "confirmed": selected_context is not None,
            "selected_context": selected_context,
            "observations": observations,
            "attempts": len(observations),
            "window_ms": Decimal(str((time.monotonic() - started) * 1000)),
            "last_block_reason": last_block_reason,
            "max_refreshed_pnl_bps": max_refreshed_pnl_bps,
            "max_executable_pnl_bps": max_executable_pnl_bps,
            "confirmation_count": confirmation_count,
            "confirmation_mode": confirmation_mode,
            "strong_single_threshold_bps": strong_single_threshold_bps,
            "strong_single_context": strong_single_context,
        }

    async def live_inventory_basis_size_ladder_context(
        self,
        *,
        var_bid: Decimal,
        var_ask: Decimal,
        stablecoin_context: dict[str, Any],
    ) -> list[dict[str, Any]]:
        ladder: list[dict[str, Any]] = []
        normalized_var_bid = self.normalize_usdc_price_to_usdt(var_bid, stablecoin_context)
        normalized_var_ask = self.normalize_usdc_price_to_usdt(var_ask, stablecoin_context)
        for notional in self.live_inventory_basis_size_ladder_notionals_usd:
            long_qty = notional / var_ask if var_ask else Decimal("0")
            short_qty = notional / var_bid if var_bid else Decimal("0")
            long_entry_depth = await self.live_inventory_lighter_depth_context(lighter_side="SELL", qty=long_qty)
            long_exit_depth = await self.live_inventory_lighter_depth_context(lighter_side="BUY", qty=long_qty)
            short_entry_depth = await self.live_inventory_lighter_depth_context(lighter_side="BUY", qty=short_qty)
            short_exit_depth = await self.live_inventory_lighter_depth_context(lighter_side="SELL", qty=short_qty)
            long_entry_price = to_decimal(long_entry_depth.get("estimated_fill_price"))
            long_exit_price = to_decimal(long_exit_depth.get("estimated_fill_price"))
            short_entry_price = to_decimal(short_entry_depth.get("estimated_fill_price"))
            short_exit_price = to_decimal(short_exit_depth.get("estimated_fill_price"))
            long_raw_edge = (
                self.live_inventory_pair_edge_bps(
                    direction=DIRECTION_LONG_VAR_SHORT_LIGHTER,
                    var_price=var_ask,
                    lighter_price=long_entry_price,
                )
                if long_entry_price is not None
                else None
            )
            short_raw_edge = (
                self.live_inventory_pair_edge_bps(
                    direction=DIRECTION_SHORT_VAR_LONG_LIGHTER,
                    var_price=var_bid,
                    lighter_price=short_entry_price,
                )
                if short_entry_price is not None
                else None
            )
            long_normalized_edge = (
                self.live_inventory_pair_edge_bps(
                    direction=DIRECTION_LONG_VAR_SHORT_LIGHTER,
                    var_price=normalized_var_ask,
                    lighter_price=long_entry_price,
                )
                if normalized_var_ask is not None and long_entry_price is not None
                else None
            )
            short_normalized_edge = (
                self.live_inventory_pair_edge_bps(
                    direction=DIRECTION_SHORT_VAR_LONG_LIGHTER,
                    var_price=normalized_var_bid,
                    lighter_price=short_entry_price,
                )
                if normalized_var_bid is not None and short_entry_price is not None
                else None
            )
            long_roundtrip = (
                self.live_inventory_roundtrip_pnl_bps(
                    direction=DIRECTION_LONG_VAR_SHORT_LIGHTER,
                    var_entry_price=var_ask,
                    lighter_entry_price=long_entry_price,
                    var_exit_price=var_bid,
                    lighter_exit_price=long_exit_price,
                )
                if long_entry_price is not None and long_exit_price is not None
                else None
            )
            short_roundtrip = (
                self.live_inventory_roundtrip_pnl_bps(
                    direction=DIRECTION_SHORT_VAR_LONG_LIGHTER,
                    var_entry_price=var_bid,
                    lighter_entry_price=short_entry_price,
                    var_exit_price=var_ask,
                    lighter_exit_price=short_exit_price,
                )
                if short_entry_price is not None and short_exit_price is not None
                else None
            )
            ladder.append(
                {
                    "notional_usd": decimal_to_str(notional),
                    "long_qty": decimal_to_str(long_qty),
                    "short_qty": decimal_to_str(short_qty),
                    "long_raw_edge_bps": decimal_to_str(long_raw_edge),
                    "short_raw_edge_bps": decimal_to_str(short_raw_edge),
                    "long_normalized_edge_bps": decimal_to_str(long_normalized_edge),
                    "short_normalized_edge_bps": decimal_to_str(short_normalized_edge),
                    "long_roundtrip_pnl_bps": decimal_to_str(long_roundtrip),
                    "short_roundtrip_pnl_bps": decimal_to_str(short_roundtrip),
                    "long_entry_lighter_depth": long_entry_depth,
                    "long_exit_lighter_depth": long_exit_depth,
                    "short_entry_lighter_depth": short_entry_depth,
                    "short_exit_lighter_depth": short_exit_depth,
                }
            )
        return ladder

    async def capture_live_inventory_basis_size_ladder_shadow(
        self,
        *,
        asset: str,
        sample_index: int,
        var_bid: Decimal,
        var_ask: Decimal,
        stablecoin_context: dict[str, Any],
    ) -> None:
        try:
            ladder = await self.live_inventory_basis_size_ladder_context(
                var_bid=var_bid,
                var_ask=var_ask,
                stablecoin_context=stablecoin_context,
            )
            self.live_inventory_latest_basis_size_ladder = list(ladder)
            await self.append_live_inventory_log(
                "live_inventory_size_ladder_shadow",
                {
                    "asset": asset,
                    "sample_index": sample_index,
                    "shadow_only": True,
                    "var_bid": decimal_to_str(var_bid),
                    "var_ask": decimal_to_str(var_ask),
                    "basis_size_ladder": ladder,
                },
            )
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            self.logger.warning(
                "live_inventory_size_ladder_shadow_failed asset=%s error=%s",
                asset,
                exc,
            )

    def schedule_live_inventory_basis_size_ladder_shadow(
        self,
        *,
        asset: str,
        sample_index: int,
        var_bid: Decimal,
        var_ask: Decimal,
        stablecoin_context: dict[str, Any],
    ) -> None:
        if not self.live_inventory_basis_size_ladder_notionals_usd:
            return
        now = time.monotonic()
        task = getattr(self, "live_inventory_size_ladder_shadow_task", None)
        last = float(
            getattr(
                self,
                "live_inventory_size_ladder_shadow_last_monotonic",
                0.0,
            )
            or 0.0
        )
        interval = 60.0 if getattr(self, "live_inventory_open_lots", []) else 300.0
        if now - last < interval or (task is not None and not task.done()):
            return
        self.live_inventory_size_ladder_shadow_last_monotonic = now
        self.live_inventory_size_ladder_shadow_task = asyncio.create_task(
            self.capture_live_inventory_basis_size_ladder_shadow(
                asset=asset,
                sample_index=sample_index,
                var_bid=var_bid,
                var_ask=var_ask,
                stablecoin_context=dict(stablecoin_context),
            )
        )

    async def record_live_inventory_basis_quote_failure(
        self,
        *,
        asset: str,
        error: Any,
        failure_kind: str,
        result: dict[str, Any] | None = None,
    ) -> None:
        raw_error_text = str(error or "unknown")
        raw_error_lower = raw_error_text.lower()
        extension_disconnected = (
            "no extension command client connected" in raw_error_lower
        )
        html_response = (
            "<!doctype html" in raw_error_lower
            or "<html" in raw_error_lower
        )
        fatal_failure_kind = (
            "variational_extension_disconnected"
            if extension_disconnected
            else "variational_html_response"
            if html_response
            else None
        )
        error_text = (
            fatal_failure_kind
            if fatal_failure_kind == "variational_html_response"
            else bounded_text(raw_error_text, max_chars=500)
        )
        if fatal_failure_kind is not None:
            previous_kind = getattr(
                self,
                "live_inventory_last_fatal_quote_failure_kind",
                None,
            )
            if previous_kind not in {None, fatal_failure_kind}:
                self.live_inventory_extension_disconnect_failures = 0
                self.live_inventory_extension_failure_started_monotonic = 0.0
            if self.live_inventory_extension_disconnect_failures == 0:
                self.live_inventory_extension_failure_started_monotonic = (
                    time.monotonic()
                )
            self.live_inventory_extension_disconnect_failures = (
                int(
                    getattr(
                        self,
                        "live_inventory_extension_disconnect_failures",
                        0,
                    )
                    or 0
                )
                + 1
            )
            self.live_inventory_last_fatal_quote_failure_kind = (
                fatal_failure_kind
            )
        else:
            self.live_inventory_extension_disconnect_failures = 0
            self.live_inventory_extension_failure_started_monotonic = 0.0
            self.live_inventory_last_fatal_quote_failure_kind = None
        failure_count = self.live_inventory_extension_disconnect_failures
        failure_elapsed_seconds = max(
            0.0,
            time.monotonic()
            - float(
                getattr(
                    self,
                    "live_inventory_extension_failure_started_monotonic",
                    0.0,
                )
                or 0.0
            ),
        )
        await self.append_live_inventory_log(
            "live_inventory_basis_quote_failed",
            {
                "asset": asset,
                "error": error_text,
                "error_original_chars": len(raw_error_text),
                "failure_kind": failure_kind,
                "extension_disconnected": extension_disconnected,
                "html_response": html_response,
                "fatal_quote_failure_kind": fatal_failure_kind,
                "extension_consecutive_failures": failure_count,
                "extension_failure_limit": LIVE_INVENTORY_EXTENSION_DISCONNECT_FAILURE_LIMIT,
                "extension_failure_elapsed_seconds": round(
                    failure_elapsed_seconds,
                    3,
                ),
                "open_position_grace_seconds": (
                    LIVE_INVENTORY_EXTENSION_OPEN_POSITION_GRACE_SECONDS
                ),
                "result_step": result.get("step") if isinstance(result, dict) else None,
            },
        )
        if (
            fatal_failure_kind is None
            or failure_count < LIVE_INVENTORY_EXTENSION_DISCONNECT_FAILURE_LIMIT
            or getattr(
                self,
                "live_inventory_extension_disconnect_fuse_triggered",
                False,
            )
            or (
                bool(self.live_inventory_open_lots)
                and failure_elapsed_seconds
                < LIVE_INVENTORY_EXTENSION_OPEN_POSITION_GRACE_SECONDS
            )
        ):
            return

        self.live_inventory_extension_disconnect_fuse_triggered = True
        self.shutdown_reason = fatal_failure_kind
        fuse_payload = {
            "asset": asset,
            "reason": self.shutdown_reason,
            "extension_consecutive_failures": failure_count,
            "extension_failure_limit": LIVE_INVENTORY_EXTENSION_DISCONNECT_FAILURE_LIMIT,
            "extension_failure_elapsed_seconds": round(
                failure_elapsed_seconds,
                3,
            ),
            "open_position_grace_seconds": (
                LIVE_INVENTORY_EXTENSION_OPEN_POSITION_GRACE_SECONDS
            ),
            "fatal_quote_failure_kind": fatal_failure_kind,
            "open_lots_total": len(self.live_inventory_open_lots),
            "action": (
                "manual_exchange_review_required"
                if self.live_inventory_open_lots
                else "auto_stop_flat"
            ),
        }
        await self.append_live_inventory_log(
            "live_inventory_runtime_fuse_triggered",
            fuse_payload,
        )
        self.logger.error(
            "live_inventory_runtime_fuse_triggered asset=%s reason=%s failures=%s open_lots=%s",
            asset,
            self.shutdown_reason,
            failure_count,
            len(self.live_inventory_open_lots),
        )
        if self.live_inventory_open_lots:
            await self.require_live_inventory_manual_review(
                asset=asset,
                reason=self.shutdown_reason,
                context=fuse_payload,
            )
        else:
            self.stop_flag = True

    async def maybe_enforce_live_disk_guard(self, *, asset: str) -> None:
        now = time.monotonic()
        last = float(
            getattr(self, "live_inventory_last_disk_check_monotonic", 0.0)
            or 0.0
        )
        if now - last < LIVE_DISK_CHECK_INTERVAL_SECONDS:
            return
        self.live_inventory_last_disk_check_monotonic = now
        free_gb = shutil.disk_usage(self.output_dir).free / (1024**3)
        if free_gb >= LIVE_DISK_WARN_FREE_GB:
            return
        if free_gb >= LIVE_DISK_STOP_FREE_GB:
            warning_last = float(
                getattr(
                    self,
                    "live_inventory_last_disk_warning_monotonic",
                    0.0,
                )
                or 0.0
            )
            if now - warning_last >= 3600.0 or warning_last == 0.0:
                self.live_inventory_last_disk_warning_monotonic = now
                self.logger.warning(
                    "live_inventory_disk_free_warning asset=%s free_gb=%.3f",
                    asset,
                    free_gb,
                )
                await self.append_live_inventory_log(
                    "live_inventory_disk_free_warning",
                    {
                        "asset": asset,
                        "disk_free_gb": f"{free_gb:.3f}",
                        "disk_stop_free_gb": LIVE_DISK_STOP_FREE_GB,
                    },
                )
            return

        if self.live_inventory_open_lots:
            self.logger.error(
                "live_inventory_disk_guard_deferred_until_flat asset=%s free_gb=%.3f open_lots=%s",
                asset,
                free_gb,
                len(self.live_inventory_open_lots),
            )
            return
        self.shutdown_reason = "disk_free_below_stop_threshold"
        await self.append_live_inventory_log(
            "live_inventory_runtime_fuse_triggered",
            {
                "asset": asset,
                "reason": self.shutdown_reason,
                "disk_free_gb": f"{free_gb:.3f}",
                "disk_stop_free_gb": LIVE_DISK_STOP_FREE_GB,
                "open_lots_total": 0,
                "action": "auto_stop_flat",
            },
        )
        self.logger.error(
            "live_inventory_runtime_fuse_triggered asset=%s reason=%s free_gb=%.3f",
            asset,
            self.shutdown_reason,
            free_gb,
        )
        self.stop_flag = True

    async def fetch_live_inventory_basis_quote(self, *, asset: str) -> tuple[dict[str, Any] | None, Decimal | None]:
        try:
            result, elapsed_ms = await self._timed_submit(
                self.send_variational_place_order(
                    asset=asset,
                    side="BUY",
                    amount=decimal_to_str(self.live_inventory_lot_notional_usd),
                    expected_min_btc_qty=None,
                    confirm=False,
                    reduce_only=False,
                )
            )
        except Exception as exc:
            await self.record_live_inventory_basis_quote_failure(
                asset=asset,
                error=f"quote_request_exception:{type(exc).__name__}:{exc}",
                failure_kind="request_exception",
            )
            return None, None
        if not result.get("ok"):
            await self.record_live_inventory_basis_quote_failure(
                asset=asset,
                error=result.get("error") or result.get("step") or "unknown",
                failure_kind="command_rejected",
                result=result,
            )
            return None, None
        payload = result.get("result") if isinstance(result.get("result"), dict) else result
        bid = to_decimal(payload.get("bid"))
        ask = to_decimal(payload.get("ask"))
        if bid is None or ask is None or bid <= 0 or ask <= 0:
            await self.record_live_inventory_basis_quote_failure(
                asset=asset,
                error="missing_or_invalid_bid_ask",
                failure_kind="invalid_quote",
                result=result,
            )
            return None, None
        self.live_inventory_extension_disconnect_failures = 0
        self.live_inventory_extension_failure_started_monotonic = 0.0
        return payload, Decimal(str(elapsed_ms))

    async def try_auto_close_unhedged_live_inventory_leg(
        self,
        *,
        asset: str,
        reason: str,
        var_side: str,
        qty: Decimal,
        var_price: Decimal,
        lot_id: int,
        close_var: bool = False,
        close_lighter: bool = False,
        force: bool = False,
    ) -> dict[str, Any]:
        enabled = self.live_inventory_basis_auto_close_unhedged or force
        result: dict[str, Any] = {"enabled": enabled, "reason": reason, "force": force}
        if not enabled:
            return result
        opposite_side = self._opposite_var_side(var_side)
        if close_var:
            var_amount = variational_api_amount_to_str(qty, asset=asset)
            try:
                close_result, close_ms = await self._timed_submit(
                    self.send_variational_place_order(
                        asset=asset,
                        side=opposite_side,
                        amount=var_amount,
                        expected_min_btc_qty=None,
                        confirm=True,
                        reduce_only=True,
                    )
                )
                result["var_close"] = {"ok": bool(close_result.get("ok")), "submit_ms": close_ms, "result": close_result}
            except Exception as exc:
                result["var_close"] = {"ok": False, "error": str(exc)}
        if close_lighter:
            try:
                (record, payload), close_ms = await self._timed_submit(
                    self.place_lighter_order_from_plan(
                        asset=asset,
                        side=opposite_side,
                        qty=qty,
                        var_fill_price=var_price,
                        cycle_id=lot_id,
                        role="live_inventory_auto_close_unhedged_lighter",
                        reduce_only=True,
                    )
                )
                result["lighter_close"] = {
                    "ok": self.auto_live_eager_hedge_started(record),
                    "submit_ms": close_ms,
                    "payload": payload,
                }
            except Exception as exc:
                result["lighter_close"] = {"ok": False, "error": str(exc)}
        await self.append_live_inventory_log(
            "live_inventory_auto_close_unhedged_attempted",
            {"asset": asset, "lot_id": lot_id, "var_side": var_side, "qty": decimal_to_str(qty), **result},
        )
        return result

    async def auto_close_live_inventory_manual_review_position_once(self) -> None:
        state = self.load_live_inventory_state()
        reason = str(state.get("manual_review_reason") or "")
        if reason != "basis_entry_lighter_actual_slippage_exceeds_limit":
            raise RuntimeError(f"manual-review auto-close refused for reason={reason or 'missing'}")
        context = state.get("manual_review_context") if isinstance(state.get("manual_review_context"), dict) else {}
        asset = str(state.get("asset") or context.get("asset") or self.live_inventory_state_asset()).upper()
        direction = str(context.get("direction") or "")
        qty = to_decimal(context.get("qty"))
        lighter_fill_price = to_decimal(context.get("entry_lighter_fill_price"))
        lot_id = int(context.get("lot_id") or state.get("next_lot_id") or 1)
        if direction not in {DIRECTION_LONG_VAR_SHORT_LIGHTER, DIRECTION_SHORT_VAR_LONG_LIGHTER}:
            raise RuntimeError(f"manual-review auto-close refused for unsupported direction={direction or 'missing'}")
        if qty is None or qty <= 0:
            raise RuntimeError(f"manual-review auto-close refused for invalid qty={context.get('qty')!r}")
        if lighter_fill_price is None or lighter_fill_price <= 0:
            raise RuntimeError("manual-review auto-close refused because entry_lighter_fill_price is missing")
        auto_close_context = await self.try_auto_close_unhedged_live_inventory_leg(
            asset=asset,
            reason="manual_review_recovery_basis_entry_lighter_actual_slippage_exceeds_limit",
            var_side=self._auto_live_direction_to_var_side(direction),
            qty=qty,
            var_price=lighter_fill_price,
            lot_id=lot_id,
            close_var=True,
            close_lighter=True,
            force=True,
        )
        await self.write_live_inventory_state_async(
            {
                "status": "manual_review_required",
                "asset": asset,
                "next_lot_id": state.get("next_lot_id") or self.live_inventory_next_lot_id,
                "open_lots": [],
                "pending_actions": [],
                "realized_pnl_usd": decimal_to_str(self.live_inventory_realized_pnl_usd),
                "completed_cycles": state.get("completed_cycles") or self.live_inventory_completed_cycles,
                "manual_review_reason": "manual_review_recovery_auto_close_attempted",
                "manual_review_context": {
                    "previous_manual_review_reason": reason,
                    "previous_manual_review_context": context,
                    "auto_close_unhedged": auto_close_context,
                    "action": "manual_confirm_flat_after_recovery_auto_close",
                },
                "action": "confirm_flat_then_restart_with_reset_state_after_manual_flat",
            }
        )
        await self.append_live_inventory_log(
            "live_inventory_manual_review_auto_close_attempted",
            {
                "asset": asset,
                "lot_id": lot_id,
                "direction": direction,
                "qty": decimal_to_str(qty),
                "previous_manual_review_reason": reason,
                "auto_close_unhedged": auto_close_context,
                "action": "manual_confirm_flat_after_recovery_auto_close",
            },
        )
        self.stop_flag = True

    async def complete_live_inventory_entry_after_var_fill(
        self,
        *,
        match: PendingLiveInventoryVarFillMatch,
        record: OrderLifecycle,
        fill_payload: dict[str, Any],
    ) -> None:
        context = match.context or {}
        asset = match.asset.upper()
        qty = match.qty
        lot_id = match.lot_id
        direction = str(context.get("direction") or "")
        var_fill_price = record.var_fill_price or to_decimal(fill_payload.get("variational_filled_price"))
        if var_fill_price is None:
            await self.require_live_inventory_manual_review(
                asset=asset,
                reason="basis_entry_var_fill_missing_price",
                context={"lot_id": lot_id, "direction": direction, "fill_payload": fill_payload},
            )
            return
        lighter_record_key = str(context.get("lighter_record_key") or "")
        lighter_record = self.records.get(lighter_record_key) if lighter_record_key else None
        lighter_payload = context.get("lighter_payload")
        lighter_submit_ms = context.get("lighter_submit_ms")
        if lighter_record is None and context.get("lighter_submitted_before_var_fill"):
            await self.require_live_inventory_manual_review(
                asset=asset,
                reason="basis_entry_concurrent_lighter_record_missing_after_var_fill",
                context={"lot_id": lot_id, "direction": direction, "qty": decimal_to_str(qty), "pending_context": context},
            )
            return
        if lighter_record is None:
            try:
                lighter_result, lighter_submit_ms = await self._timed_submit(
                    self.place_lighter_order_from_plan(
                        asset=asset,
                        side=str(context.get("var_side") or self._auto_live_direction_to_var_side(direction)),
                        qty=qty,
                        var_fill_price=var_fill_price,
                        cycle_id=lot_id,
                        role="live_inventory_entry",
                    )
                )
            except Exception as exc:
                await self.require_live_inventory_manual_review(
                    asset=asset,
                    reason=f"basis_entry_lighter_submit_after_var_fill_exception:{exc}",
                    context={"lot_id": lot_id, "direction": direction, "qty": decimal_to_str(qty)},
                )
                return
            lighter_record, lighter_payload = lighter_result
        if lighter_record is None or not self.auto_live_eager_hedge_started(lighter_record):
            await self.require_live_inventory_manual_review(
                asset=asset,
                reason="basis_entry_lighter_submit_after_var_fill_failed",
                context={"lot_id": lot_id, "direction": direction, "qty": decimal_to_str(qty), "lighter_payload": lighter_payload},
            )
            return
        entry_lighter_fill_timeout_seconds = self.live_inventory_entry_lighter_fill_timeout_seconds
        if not await self.wait_for_lighter_final_fill(
            lighter_record,
            timeout_seconds=entry_lighter_fill_timeout_seconds,
        ):
            async with self._record_lock:
                partial_lighter_fill = self.lighter_record_has_partial_fill(lighter_record)
                lighter_failure_reason = lighter_record.failure_reason or "lighter_final_fill_not_confirmed"
                lighter_record.hedge_error = (
                    f"Live inventory entry Lighter IOC had no confirmed fill after "
                    f"{entry_lighter_fill_timeout_seconds:.1f}s"
                    if not lighter_record.hedge_error
                    else lighter_record.hedge_error
                )
                lighter_record_payload = lighter_record.to_payload()
            await self.append_live_inventory_log(
                "live_inventory_entry_lighter_ioc_no_fill",
                {
                    "asset": asset,
                    "lot_id": lot_id,
                    "direction": direction,
                    "qty": decimal_to_str(qty),
                    "timeout_seconds": entry_lighter_fill_timeout_seconds,
                    "lighter_failure_reason": lighter_failure_reason,
                    "partial_lighter_fill": partial_lighter_fill,
                    "lighter_record": lighter_record_payload,
                    "lighter_payload": lighter_payload,
                    "action": "auto_close_unhedged_legs_then_manual_review" if partial_lighter_fill else "auto_close_unhedged_var_leg_then_manual_review",
                },
            )
            auto_close_context = await self.try_auto_close_unhedged_live_inventory_leg(
                asset=asset,
                reason="basis_entry_lighter_final_fill_not_confirmed_after_var_fill",
                var_side=str(context.get("var_side") or self._auto_live_direction_to_var_side(direction)),
                qty=qty,
                var_price=var_fill_price,
                lot_id=lot_id,
                close_var=True,
                close_lighter=partial_lighter_fill,
            )
            await self.require_live_inventory_manual_review(
                asset=asset,
                reason="basis_entry_lighter_final_fill_not_confirmed",
                context={
                    "lot_id": lot_id,
                    "direction": direction,
                    "qty": decimal_to_str(qty),
                    "lighter_payload": lighter_payload,
                    "lighter_record": lighter_record_payload,
                    "entry_lighter_fill_timeout_seconds": entry_lighter_fill_timeout_seconds,
                    "lighter_failure_reason": lighter_failure_reason,
                    "partial_lighter_fill": partial_lighter_fill,
                    "auto_close_unhedged": auto_close_context,
                    "action": "manual_confirm_or_flatten_unhedged_var_leg",
                },
            )
            return
        lighter_fill_price = lighter_record.lighter_fill_price
        estimated_entry_lighter_price = to_decimal(context.get("lighter_price"))
        entry_lighter_slippage_bps: Decimal | None = None
        if estimated_entry_lighter_price is not None:
            if direction == DIRECTION_LONG_VAR_SHORT_LIGHTER:
                entry_lighter_slippage_bps = ((estimated_entry_lighter_price - lighter_fill_price) / estimated_entry_lighter_price) * Decimal("10000")
            else:
                entry_lighter_slippage_bps = ((lighter_fill_price - estimated_entry_lighter_price) / estimated_entry_lighter_price) * Decimal("10000")
            if entry_lighter_slippage_bps is not None and entry_lighter_slippage_bps < 0:
                entry_lighter_slippage_bps = Decimal("0")
        if entry_lighter_slippage_bps is not None and entry_lighter_slippage_bps > self.live_inventory_max_lighter_slippage_bps:
            auto_close_context = await self.try_auto_close_unhedged_live_inventory_leg(
                asset=asset,
                reason="basis_entry_lighter_actual_slippage_exceeds_limit_after_both_legs_filled",
                var_side=str(context.get("var_side") or self._auto_live_direction_to_var_side(direction)),
                qty=qty,
                var_price=var_fill_price,
                lot_id=lot_id,
                close_var=True,
                close_lighter=True,
                force=True,
            )
            await self.require_live_inventory_manual_review(
                asset=asset,
                reason="basis_entry_lighter_actual_slippage_exceeds_limit",
                context={
                    "lot_id": lot_id,
                    "basis_trace_id": context.get("basis_trace_id"),
                    "direction": direction,
                    "qty": decimal_to_str(qty),
                    "estimated_entry_lighter_price": decimal_to_str(estimated_entry_lighter_price),
                    "entry_lighter_fill_price": decimal_to_str(lighter_fill_price),
                    "entry_lighter_slippage_bps": decimal_to_str(entry_lighter_slippage_bps),
                    "max_lighter_slippage_bps": decimal_to_str(self.live_inventory_max_lighter_slippage_bps),
                    "lighter_payload": lighter_payload,
                    "auto_close_unhedged": auto_close_context,
                    "action": "manual_confirm_auto_close_or_flatten_remaining_legs",
                },
            )
            return
        lot = {
            "lot_id": lot_id,
            "basis_trace_id": context.get("basis_trace_id"),
            "episode_id": context.get("episode_id"),
            "tranche_index": int(context.get("tranche_index") or 1),
            "signal_mode": LIVE_INVENTORY_SIGNAL_BASIS,
            "direction": direction,
            "qty": decimal_to_str(qty),
            "entry_var_fill_price": decimal_to_str(var_fill_price),
            "entry_lighter_fill_price": decimal_to_str(lighter_fill_price),
            "entry_estimated_var_price": context.get("var_price"),
            "entry_estimated_lighter_price": context.get("lighter_price"),
            "entry_var_final_fill_qty": decimal_to_str(record.qty),
            "entry_lighter_final_fill_qty": decimal_to_str(
                lighter_record.lighter_filled_base_amount
            ),
            "entry_var_price_source": "final_fill",
            "entry_lighter_price_source": "final_fill" if lighter_record.lighter_fill_price is not None else "estimated_snapshot",
            "entry_cost_status": "final_fills_confirmed" if lighter_record.lighter_fill_price is not None else "final_fills_pending",
            "entry_edge_bps": context.get("edge_bps"),
            "entry_roundtrip_pnl_bps": context.get("roundtrip_pnl_bps"),
            "entry_basis_bps": context.get("basis_bps"),
            "entry_z": context.get("z"),
            "entry_direction_signal": context.get("direction_signal"),
            "entry_normalized_edge_bps": context.get("normalized_edge_bps"),
            "entry_normalized_roundtrip_pnl_bps": context.get("normalized_roundtrip_pnl_bps"),
            "entry_stablecoin_edge_share": context.get("stablecoin_edge_share"),
            "entry_stablecoin_edge_adjustment_bps": context.get("stablecoin_edge_adjustment_bps"),
            "entry_stablecoin_filter_reason": context.get("stablecoin_filter_reason"),
            "entry_reversion_median_5m_bps": context.get("entry_reversion_median_5m_bps"),
            "entry_reversion_median_30m_bps": context.get("entry_reversion_median_30m_bps"),
            "entry_reversion_median_60m_bps": context.get("entry_reversion_median_60m_bps"),
            "entry_reversion_deviation_bps": context.get("entry_reversion_deviation_bps"),
            "entry_v4_profile": context.get("entry_v4_profile"),
            "entry_v4_threshold_bps": context.get("entry_v4_threshold_bps"),
            "entry_gradient_tier": context.get("entry_gradient_tier"),
            "entry_gradient_capacity_notional_usd": context.get(
                "entry_gradient_capacity_notional_usd"
            ),
            "entry_gradient_capacity_child_lots": context.get(
                "entry_gradient_capacity_child_lots"
            ),
            "entry_v4_baseline_window_seconds": context.get(
                "entry_v4_baseline_window_seconds"
            ),
            "entry_var_side": context.get("var_side"),
            "entry_var_order_quote_id": context.get("quote_id"),
            "entry_var_order_quote_bid": context.get("var_bid"),
            "entry_var_order_quote_ask": context.get("var_ask"),
            "entry_var_order_quote_timestamp": context.get("quote_timestamp"),
            "entry_var_order_quote_execution_price": context.get("var_price"),
            "entry_var_submit_ms": context.get("var_submit_ms"),
            "entry_lighter_submit_ms": lighter_submit_ms,
            "entry_lighter_record_key": lighter_record.trade_key,
            "entry_lighter_payload": lighter_payload,
            "entry_kind": context.get("entry_kind") or "basis_initial",
            "entered_at": utc_now(),
            "entered_sample_index": context.get("sample_index") or self.live_inventory_sample_index,
            "status": "open",
        }
        self.live_inventory_open_lots.append(lot)
        if getattr(self, "live_inventory_basis_v4_mode", False):
            self.live_inventory_v4_episode_id = lot.get("episode_id") or (
                getattr(self, "live_inventory_v4_episode_id", None)
            )
            self.live_inventory_v4_next_tranche_index = max(
                int(
                    getattr(
                        self,
                        "live_inventory_v4_next_tranche_index",
                        1,
                    )
                ),
                int(lot.get("tranche_index") or 1) + 1,
            )
        self.remember_live_inventory_final_pnl_lot(asset=asset, lot=lot)
        self.sync_live_inventory_open_lot_entry_cost(asset=asset, lot_id=lot_id)
        await self.persist_live_inventory_memory(reason="basis_entry_lighter_submitted_after_var_fill")
        await self.append_live_inventory_log(
            "live_inventory_entered",
            {
                "asset": asset,
                "sample_index": context.get("sample_index"),
                "lot_id": lot_id,
                "basis_trace_id": context.get("basis_trace_id"),
                "episode_id": lot.get("episode_id"),
                "tranche_index": lot.get("tranche_index"),
                "direction": direction,
                "qty": decimal_to_str(qty),
                "edge_bps": context.get("edge_bps"),
                "roundtrip_pnl_bps": context.get("roundtrip_pnl_bps"),
                "entry_basis_bps": context.get("basis_bps"),
                "entry_z": context.get("z"),
                "entry_direction_signal": context.get("direction_signal"),
                "entry_normalized_edge_bps": context.get("normalized_edge_bps"),
                "entry_normalized_roundtrip_pnl_bps": context.get("normalized_roundtrip_pnl_bps"),
                "entry_stablecoin_edge_share": context.get("stablecoin_edge_share"),
                "entry_stablecoin_edge_adjustment_bps": context.get("stablecoin_edge_adjustment_bps"),
                "entry_stablecoin_filter_reason": context.get("stablecoin_filter_reason"),
                "entry_reversion_median_5m_bps": context.get("entry_reversion_median_5m_bps"),
                "entry_reversion_median_30m_bps": context.get("entry_reversion_median_30m_bps"),
                "entry_reversion_median_60m_bps": context.get("entry_reversion_median_60m_bps"),
                "entry_reversion_deviation_bps": context.get("entry_reversion_deviation_bps"),
                "entry_kind": lot["entry_kind"],
                "entry_gradient_tier": lot.get("entry_gradient_tier"),
                "entry_gradient_capacity_notional_usd": lot.get(
                    "entry_gradient_capacity_notional_usd"
                ),
                "entry_gradient_capacity_child_lots": lot.get(
                    "entry_gradient_capacity_child_lots"
                ),
                "gradient_tier": lot.get("entry_gradient_tier"),
                "gradient_capacity_notional_usd": lot.get(
                    "entry_gradient_capacity_notional_usd"
                ),
                "gradient_capacity_child_lots": lot.get(
                    "entry_gradient_capacity_child_lots"
                ),
                "var_price": decimal_to_str(var_fill_price),
                "lighter_price": decimal_to_str(lighter_fill_price),
                "estimated_entry_lighter_price": decimal_to_str(estimated_entry_lighter_price),
                "entry_lighter_slippage_bps": decimal_to_str(entry_lighter_slippage_bps),
                "entry_lighter_depth": context.get("entry_lighter_depth"),
                "var_submit_ms": context.get("var_submit_ms"),
                "lighter_submit_ms": lighter_submit_ms,
                "open_lots_total": len(self.live_inventory_open_lots),
                "open_child_lots": len(self.live_inventory_open_lots),
                "open_notional_usd": decimal_to_str(
                    self.live_inventory_open_notional_usd()
                ),
                "realized_pnl_usd": decimal_to_str(self.live_inventory_realized_pnl_usd),
                "completed_cycles": self.live_inventory_completed_cycles,
                "entry_confirmation_mode": "concurrent_var_and_lighter_then_var_fill_confirmed" if context.get("lighter_submitted_before_var_fill") else "var_fill_then_lighter",
                "variational_equity_usd": context.get(
                    "variational_equity_usd"
                ),
                "lighter_equity_usd": context.get("lighter_equity_usd"),
                "combined_equity_usd": context.get("combined_equity_usd"),
                "variational_maintenance_margin_usage_pct": context.get(
                    "variational_maintenance_margin_usage_pct"
                ),
                "lighter_maintenance_margin_usage_pct": context.get(
                    "lighter_maintenance_margin_usage_pct"
                ),
                "max_projected_venue_leverage": context.get(
                    "max_projected_venue_leverage"
                ),
            },
        )
        await self.append_live_inventory_log(
            "live_inventory_execution_ledger",
            {
                "asset": asset,
                "lot_id": lot_id,
                "basis_trace_id": context.get("basis_trace_id"),
                "phase": "entry",
                "execution_stage": "final_fills_confirmed",
                "direction": direction,
                "qty": decimal_to_str(qty),
                "submit_mode": (
                    "concurrent"
                    if context.get("lighter_submitted_before_var_fill")
                    else "sequential"
                ),
                "var_submit_ms": context.get("var_submit_ms"),
                "lighter_submit_ms": lighter_submit_ms,
                "var_final_fill_price": decimal_to_str(var_fill_price),
                "lighter_final_fill_price": decimal_to_str(lighter_fill_price),
                "entry_lighter_slippage_bps": decimal_to_str(entry_lighter_slippage_bps),
                "entry_lighter_depth": context.get("entry_lighter_depth"),
                "var_result": context.get("var_result"),
                "lighter_payload": lighter_payload,
            },
        )

    async def maybe_append_live_inventory_actual_pnl(self, payload: dict[str, Any]) -> None:
        trade_key = str(payload.get("trade_key") or "")
        pending = self.pending_live_inventory_actual_pnl.pop(trade_key, None)
        if not pending:
            return

        planned_qty = to_decimal(pending.get("qty")) or Decimal("0")
        entry_var_qty = to_decimal(pending.get("entry_var_final_fill_qty")) or planned_qty
        exit_var_qty = to_decimal(pending.get("exit_var_final_fill_qty")) or planned_qty
        entry_lighter_qty = to_decimal(pending.get("entry_lighter_final_fill_qty")) or planned_qty
        exit_lighter_qty = to_decimal(payload.get("lighter_filled_base_amount")) or planned_qty
        var_qty = min(entry_var_qty, exit_var_qty)
        lighter_qty = min(entry_lighter_qty, exit_lighter_qty)
        var_roundtrip_qty_match = entry_var_qty == exit_var_qty
        lighter_roundtrip_qty_match = entry_lighter_qty == exit_lighter_qty
        entry_var_price = to_decimal(pending.get("entry_var_price"))
        entry_lighter_price = to_decimal(pending.get("entry_lighter_price"))
        exit_var_price = to_decimal(pending.get("exit_var_price"))
        exit_lighter_price = to_decimal(payload.get("lighter_filled_price"))
        if None in {entry_var_price, entry_lighter_price, exit_var_price, exit_lighter_price}:
            await self.append_live_inventory_log(
                "live_inventory_actual_pnl_pending",
                {
                    **pending,
                    "exit_lighter_payload": payload,
                    "actual_pnl_status": "missing_final_fill_price",
                },
            )
            return

        var_leg_pnl, lighter_leg_pnl, actual_pnl = self.live_inventory_pair_pnl_by_leg_qty(
            direction=str(pending.get("direction") or ""),
            var_qty=var_qty,
            lighter_qty=lighter_qty,
            entry_var_price=entry_var_price,
            entry_lighter_price=entry_lighter_price,
            exit_var_price=exit_var_price,
            exit_lighter_price=exit_lighter_price,
        )
        notional = var_qty * entry_var_price
        actual_pnl_bps = actual_pnl / notional * Decimal("10000") if notional else None
        estimated_pnl = to_decimal(pending.get("estimated_pnl_usd")) or Decimal("0")
        estimated_pnl_bps = to_decimal(pending.get("estimated_pnl_bps"))
        estimated_exit_lighter_price = to_decimal(pending.get("estimated_exit_lighter_price"))
        exit_lighter_slippage_bps: Decimal | None = None
        if estimated_exit_lighter_price is not None and exit_lighter_price is not None:
            if str(pending.get("direction") or "") == DIRECTION_LONG_VAR_SHORT_LIGHTER:
                exit_lighter_slippage_bps = ((exit_lighter_price - estimated_exit_lighter_price) / estimated_exit_lighter_price) * Decimal("10000")
            else:
                exit_lighter_slippage_bps = ((estimated_exit_lighter_price - exit_lighter_price) / estimated_exit_lighter_price) * Decimal("10000")
            if exit_lighter_slippage_bps is not None and exit_lighter_slippage_bps < 0:
                exit_lighter_slippage_bps = Decimal("0")
        pnl_shortfall_usd = estimated_pnl - actual_pnl
        var_fill_to_lighter_fill_ms = decimal_to_str(elapsed_iso_ms(
            payload.get("variational_filled_at"),
            payload.get("lighter_filled_at"),
        ))
        if estimated_pnl_bps is not None and actual_pnl_bps is not None:
            if not hasattr(self, "live_inventory_exit_estimate_shortfall_bps_samples"):
                self.live_inventory_exit_estimate_shortfall_bps_samples = deque(maxlen=20)
            shortfall_bps = estimated_pnl_bps - actual_pnl_bps
            self.live_inventory_exit_estimate_shortfall_bps_samples.append(
                max(shortfall_bps, Decimal("0"))
            )
            if pending.get("exit_confirmation_mode") == "strong_single":
                if not hasattr(
                    self,
                    "live_inventory_strong_single_shortfall_bps_samples",
                ):
                    self.live_inventory_strong_single_shortfall_bps_samples = (
                        deque(maxlen=20)
                    )
                self.live_inventory_strong_single_shortfall_bps_samples.append(
                    max(shortfall_bps, Decimal("0"))
                )
        direction = str(pending.get("direction") or "")
        if actual_pnl_bps is not None and direction in getattr(self, "live_inventory_actual_pnl_bps_by_direction", {}):
            self.live_inventory_actual_pnl_bps_by_direction[direction].append(actual_pnl_bps)
        latency_ms = to_decimal(var_fill_to_lighter_fill_ms)
        if latency_ms is not None and latency_ms >= 0:
            self.live_inventory_exit_fill_latency_ms_samples.append(latency_ms)
        self.live_inventory_realized_pnl_usd += actual_pnl - estimated_pnl
        if (
            getattr(self, "live_inventory_execution_calibration", False)
            and actual_pnl <= -getattr(self, "live_inventory_calibration_max_cycle_loss_usd", Decimal("0.10"))
        ):
            self.live_inventory_calibration_halted_reason = "calibration_max_cycle_loss_reached"
            await self.append_live_inventory_log(
                "live_inventory_calibration_loss_fuse_triggered",
                {
                    **pending,
                    "reason": self.live_inventory_calibration_halted_reason,
                    "actual_pnl_usd": decimal_to_str(actual_pnl),
                    "calibration_max_cycle_loss_usd": decimal_to_str(
                        getattr(self, "live_inventory_calibration_max_cycle_loss_usd", Decimal("0.10"))
                    ),
                },
            )
        actual_pnl_payload = {
            **pending,
            "actual_pnl_status": (
                "lighter_final_fill_confirmed"
                if var_roundtrip_qty_match and lighter_roundtrip_qty_match
                else "leg_quantity_mismatch_requires_reconciliation"
            ),
            "planned_qty": decimal_to_str(planned_qty),
            "entry_var_final_fill_qty": decimal_to_str(entry_var_qty),
            "exit_var_final_fill_qty": decimal_to_str(exit_var_qty),
            "actual_var_pnl_qty": decimal_to_str(var_qty),
            "entry_lighter_final_fill_qty": decimal_to_str(entry_lighter_qty),
            "exit_lighter_final_fill_qty": decimal_to_str(exit_lighter_qty),
            "actual_lighter_pnl_qty": decimal_to_str(lighter_qty),
            "var_roundtrip_qty_match": var_roundtrip_qty_match,
            "lighter_roundtrip_qty_match": lighter_roundtrip_qty_match,
            "cross_venue_entry_qty_delta": decimal_to_str(
                entry_var_qty - entry_lighter_qty
            ),
            "cross_venue_exit_qty_delta": decimal_to_str(
                exit_var_qty - exit_lighter_qty
            ),
            "exit_lighter_final_fill_price": decimal_to_str(
                exit_lighter_price
            ),
            "estimated_exit_lighter_price": decimal_to_str(
                estimated_exit_lighter_price
            ),
            "exit_lighter_slippage_bps": decimal_to_str(
                exit_lighter_slippage_bps
            ),
            "exit_lighter_slippage_exceeds_limit": bool(
                exit_lighter_slippage_bps is not None
                and exit_lighter_slippage_bps
                > self.live_inventory_max_lighter_slippage_bps
            ),
            "max_lighter_slippage_bps": decimal_to_str(
                self.live_inventory_max_lighter_slippage_bps
            ),
            "estimated_vs_actual_pnl_shortfall_usd": decimal_to_str(
                pnl_shortfall_usd
            ),
            "estimated_vs_actual_pnl_shortfall_bps": decimal_to_str(
                estimated_pnl_bps - actual_pnl_bps
                if estimated_pnl_bps is not None
                and actual_pnl_bps is not None
                else None
            ),
            "exit_var_fill_to_lighter_fill_ms": var_fill_to_lighter_fill_ms,
            "actual_var_leg_pnl_usd": decimal_to_str(var_leg_pnl),
            "actual_lighter_leg_pnl_usd": decimal_to_str(lighter_leg_pnl),
            "actual_pnl_usd": decimal_to_str(actual_pnl),
            "actual_pnl_bps": decimal_to_str(actual_pnl_bps),
            "exit_lighter_payload": payload,
        }
        self.live_inventory_last_actual_pnl_payload = actual_pnl_payload
        final_key = self.live_inventory_final_pnl_key(
            str(pending.get("asset") or ""),
            pending.get("lot_id"),
        )
        final_pending = self.pending_live_inventory_final_pnl.setdefault(
            final_key,
            {},
        )
        final_pending.update(
            {
                **{
                    key: value
                    for key, value in pending.items()
                    if key not in {"final_pnl_emitted"}
                },
                "asset": pending.get("asset"),
                "lot_id": pending.get("lot_id"),
                "direction": direction,
                "qty": decimal_to_str(planned_qty),
                "entry_var_final_fill_price": decimal_to_str(entry_var_price),
                "entry_lighter_final_fill_price": decimal_to_str(
                    entry_lighter_price
                ),
                "exit_var_final_fill_price": decimal_to_str(exit_var_price),
                "exit_lighter_final_fill_price": decimal_to_str(
                    exit_lighter_price
                ),
                "entry_var_final_fill_qty": decimal_to_str(entry_var_qty),
                "exit_var_final_fill_qty": decimal_to_str(exit_var_qty),
                "entry_lighter_final_fill_qty": decimal_to_str(
                    entry_lighter_qty
                ),
                "exit_lighter_final_fill_qty": decimal_to_str(
                    exit_lighter_qty
                ),
                "final_pnl_source": (
                    "actual_pnl_confirmed_fill_reconciliation"
                ),
                "actual_pnl_status": actual_pnl_payload[
                    "actual_pnl_status"
                ],
            }
        )
        await self.maybe_append_live_inventory_final_pnl(final_key)
        await self.append_live_inventory_log(
            "live_inventory_actual_pnl",
            actual_pnl_payload,
        )
        effective_target_bps = to_decimal(
            pending.get("effective_min_exit_pnl_bps")
        )
        strong_single_adverse_fill = bool(
            pending.get("exit_confirmation_mode") == "strong_single"
            and estimated_pnl_bps is not None
            and effective_target_bps is not None
            and estimated_pnl_bps >= effective_target_bps
            and actual_pnl_bps is not None
            and actual_pnl_bps < 0
        )
        if (
            strong_single_adverse_fill
            and getattr(self, "live_inventory_v4_strong_single_enabled", True)
        ):
            self.live_inventory_v4_strong_single_enabled = False
            self.live_inventory_v4_strong_single_disabled_reason = (
                "estimated_profitable_actual_loss"
            )
            self.live_inventory_v4_strong_single_disabled_at = utc_now()
            strong_context = (
                self.live_inventory_basis_v4_strong_single_context(
                    effective_min_exit_pnl_bps=effective_target_bps
                )
            )
            await self.append_live_inventory_log(
                "live_inventory_v4_strong_single_auto_disabled",
                {
                    **actual_pnl_payload,
                    "reason": self.live_inventory_v4_strong_single_disabled_reason,
                    "action": "fallback_to_latest_and_2_of_3",
                    "strong_single_disabled_at": (
                        self.live_inventory_v4_strong_single_disabled_at
                    ),
                    "strong_single_shortfall_sample_count": strong_context[
                        "sample_count"
                    ],
                    "strong_single_shortfall_raw_p80_bps": decimal_to_str(
                        strong_context["raw_p80_bps"]
                    ),
                    "strong_single_shortfall_reserve_bps": decimal_to_str(
                        strong_context["mode_reserve_bps"]
                    ),
                },
            )
        await self.persist_live_inventory_memory(reason="actual_pnl_final_fill_update")
        await self.maybe_auto_stop_completed_v4_cycle()

    async def register_live_inventory_actual_pnl(
        self,
        *,
        trade_key: str,
        pending: dict[str, Any],
        lighter_record: OrderLifecycle | None,
    ) -> bool:
        self.pending_live_inventory_actual_pnl[trade_key] = pending
        if lighter_record is not None and lighter_record.lighter_fill_ts_iso is not None:
            await self.maybe_append_live_inventory_actual_pnl(lighter_record.to_payload())
        return trade_key not in self.pending_live_inventory_actual_pnl

    @staticmethod
    def live_inventory_normalized_lot_id(lot_id: Any) -> str:
        normalized_lot_id = str(lot_id).strip()
        try:
            numeric_lot_id = Decimal(normalized_lot_id)
            if numeric_lot_id == numeric_lot_id.to_integral_value():
                normalized_lot_id = str(int(numeric_lot_id))
        except (InvalidOperation, ValueError):
            pass
        return normalized_lot_id

    @staticmethod
    def live_inventory_final_pnl_key(asset: str, lot_id: Any) -> str:
        return (
            f"{str(asset).strip().upper()}:"
            f"{VariationalToLighterRuntime.live_inventory_normalized_lot_id(lot_id)}"
        )

    def clear_finalized_live_inventory_final_pnl(
        self,
        *,
        asset: str,
        lot_id: Any,
    ) -> None:
        finalized_key = self.live_inventory_final_pnl_key(asset, lot_id)
        stale_keys = []
        for key, payload in getattr(
            self,
            "pending_live_inventory_final_pnl",
            {},
        ).items():
            payload_key = self.live_inventory_final_pnl_key(
                str(payload.get("asset") or asset),
                payload.get("lot_id"),
            )
            if key == finalized_key or payload_key == finalized_key:
                stale_keys.append(key)
        for key in stale_keys:
            self.pending_live_inventory_final_pnl.pop(key, None)

    def clear_completed_live_inventory_cycle_reconciliation(
        self,
        *,
        asset: str,
        lot_id: Any,
    ) -> dict[str, int]:
        normalized_lot_id = self.live_inventory_normalized_lot_id(lot_id)
        asset = asset.upper()

        pending_actual = getattr(self, "pending_live_inventory_actual_pnl", {})
        stale_actual_keys = [
            key
            for key, payload in pending_actual.items()
            if self.live_inventory_normalized_lot_id(payload.get("lot_id"))
            == normalized_lot_id
            and str(payload.get("asset") or asset).upper() == asset
        ]
        for key in stale_actual_keys:
            pending_actual.pop(key, None)

        final_before = len(getattr(self, "pending_live_inventory_final_pnl", {}))
        self.clear_finalized_live_inventory_final_pnl(
            asset=asset,
            lot_id=lot_id,
        )
        final_after = len(getattr(self, "pending_live_inventory_final_pnl", {}))

        pending_matches = getattr(self, "pending_live_inventory_var_fill_matches", [])
        retained_matches = [
            item
            for item in pending_matches
            if not (
                item.asset.upper() == asset
                and self.live_inventory_normalized_lot_id(item.lot_id)
                == normalized_lot_id
            )
        ]
        self.pending_live_inventory_var_fill_matches = retained_matches
        return {
            "pending_actual_pnl": len(stale_actual_keys),
            "pending_final_pnl": final_before - final_after,
            "pending_var_fill_matches": len(pending_matches) - len(retained_matches),
        }

    def prune_checkpointed_live_inventory_reconciliation(self) -> dict[str, int]:
        checkpointed_lot_ids = {
            self.live_inventory_normalized_lot_id(value)
            for value in getattr(
                self,
                "live_inventory_v4_checkpointed_lot_ids",
                set(),
            )
        }
        cleanup = {
            "pending_actual_pnl": 0,
            "pending_final_pnl": 0,
            "pending_var_fill_matches": 0,
        }
        if not checkpointed_lot_ids:
            return cleanup

        assets_by_lot: dict[str, set[str]] = {}
        for payload in getattr(self, "pending_live_inventory_actual_pnl", {}).values():
            normalized = self.live_inventory_normalized_lot_id(payload.get("lot_id"))
            if normalized in checkpointed_lot_ids:
                assets_by_lot.setdefault(normalized, set()).add(
                    str(payload.get("asset") or self.live_inventory_state_asset()).upper()
                )
        for payload in getattr(self, "pending_live_inventory_final_pnl", {}).values():
            normalized = self.live_inventory_normalized_lot_id(payload.get("lot_id"))
            if normalized in checkpointed_lot_ids:
                assets_by_lot.setdefault(normalized, set()).add(
                    str(payload.get("asset") or self.live_inventory_state_asset()).upper()
                )
        for item in getattr(self, "pending_live_inventory_var_fill_matches", []):
            normalized = self.live_inventory_normalized_lot_id(item.lot_id)
            if normalized in checkpointed_lot_ids:
                assets_by_lot.setdefault(normalized, set()).add(item.asset.upper())

        for normalized_lot_id, assets in assets_by_lot.items():
            for asset in assets:
                removed = self.clear_completed_live_inventory_cycle_reconciliation(
                    asset=asset,
                    lot_id=normalized_lot_id,
                )
                for key, count in removed.items():
                    cleanup[key] += count
        return cleanup

    def remember_live_inventory_final_pnl_lot(self, *, asset: str, lot: dict[str, Any]) -> None:
        lot_id = lot.get("lot_id")
        if lot_id is None:
            return
        if (
            getattr(self, "live_inventory_basis_v4_mode", False)
            and self.live_inventory_normalized_lot_id(lot_id)
            in {
                self.live_inventory_normalized_lot_id(value)
                for value in getattr(
                    self,
                    "live_inventory_v4_checkpointed_lot_ids",
                    set(),
                )
            }
        ):
            return
        key = self.live_inventory_final_pnl_key(asset, lot_id)
        pending = self.pending_live_inventory_final_pnl.setdefault(key, {})
        pending.update(
            {
                "asset": asset,
                "lot_id": lot_id,
                "direction": lot.get("direction"),
                "qty": lot.get("qty"),
                "entry_estimated_var_price": lot.get("entry_estimated_var_price")
                or lot.get("entry_var_fill_price"),
                "entry_estimated_lighter_price": lot.get(
                    "entry_estimated_lighter_price"
                )
                or lot.get("entry_lighter_fill_price"),
                "entry_signal_edge_bps": lot.get("entry_edge_bps"),
                "entry_snapshot_var_bid": lot.get("entry_snapshot_var_bid"),
                "entry_snapshot_var_ask": lot.get("entry_snapshot_var_ask"),
                "entry_snapshot_var_mid": lot.get("entry_snapshot_var_mid"),
                "entry_snapshot_var_buy_price": lot.get("entry_snapshot_var_buy_price"),
                "entry_snapshot_var_sell_price": lot.get("entry_snapshot_var_sell_price"),
                "entry_snapshot_var_full_spread_bps": lot.get("entry_snapshot_var_full_spread_bps"),
                "entry_snapshot_var_spread_source": lot.get("entry_snapshot_var_spread_source"),
                "entry_snapshot_var_timestamp": lot.get("entry_snapshot_var_timestamp"),
                "entry_snapshot_var_source_url": lot.get("entry_snapshot_var_source_url"),
                "entry_snapshot_var_source_stream": lot.get("entry_snapshot_var_source_stream"),
                "entry_initial_signal_edge_bps": lot.get("entry_initial_signal_edge_bps"),
                "entry_initial_snapshot_var_price": lot.get("entry_initial_snapshot_var_price"),
                "entry_refreshed_var_quote_ms": lot.get("entry_refreshed_var_quote_ms"),
                "entry_var_order_quote_id": lot.get("entry_var_order_quote_id"),
                "entry_var_order_quote_bid": lot.get("entry_var_order_quote_bid"),
                "entry_var_order_quote_ask": lot.get("entry_var_order_quote_ask"),
                "entry_var_order_quote_mark_price": lot.get("entry_var_order_quote_mark_price"),
                "entry_var_order_quote_timestamp": lot.get("entry_var_order_quote_timestamp"),
                "entry_var_order_quote_execution_price": lot.get("entry_var_order_quote_execution_price"),
                "entered_at": lot.get("entered_at"),
            }
        )
        # Some entry paths already have both venue fills when the lot is
        # created. Seed the final-fill ledger before syncing the open lot so
        # that confirmed costs cannot be downgraded back to pending.
        if lot.get("entry_var_price_source") == "final_fill":
            pending.update(
                {
                    "entry_var_final_fill_price": lot.get("entry_var_fill_price"),
                    "entry_var_final_fill_at": lot.get("entry_var_final_fill_at"),
                    "entry_var_final_fill_qty": lot.get("entry_var_final_fill_qty")
                    or lot.get("qty"),
                }
            )
        if lot.get("entry_lighter_price_source") == "final_fill":
            pending.update(
                {
                    "entry_lighter_final_fill_price": lot.get(
                        "entry_lighter_fill_price"
                    ),
                    "entry_lighter_final_fill_at": lot.get(
                        "entry_lighter_final_fill_at"
                    ),
                    "entry_lighter_final_fill_qty": lot.get(
                        "entry_lighter_final_fill_qty"
                    )
                    or lot.get("qty"),
                }
            )

    def sync_live_inventory_open_lot_entry_cost(self, *, asset: str, lot_id: Any) -> bool:
        open_lots = getattr(self, "live_inventory_open_lots", [])
        if lot_id is None or not open_lots:
            return False
        key = self.live_inventory_final_pnl_key(asset, lot_id)
        pending = self.pending_live_inventory_final_pnl.get(key) or {}
        entry_var_price = pending.get("entry_var_final_fill_price")
        entry_lighter_price = pending.get("entry_lighter_final_fill_price")
        entry_var_qty = pending.get("entry_var_final_fill_qty")
        entry_lighter_qty = pending.get("entry_lighter_final_fill_qty")
        updated = False
        for lot in open_lots:
            if str(lot.get("lot_id")) != str(lot_id):
                continue
            if entry_var_price is not None and lot.get("entry_var_fill_price") != entry_var_price:
                lot["entry_var_fill_price"] = entry_var_price
                lot["entry_var_final_fill_at"] = pending.get("entry_var_final_fill_at")
                updated = True
            if entry_var_price is not None and lot.get("entry_var_price_source") != "final_fill":
                lot["entry_var_price_source"] = "final_fill"
                lot["entry_var_final_fill_at"] = pending.get("entry_var_final_fill_at")
                updated = True
            if entry_lighter_price is not None and lot.get("entry_lighter_fill_price") != entry_lighter_price:
                lot["entry_lighter_fill_price"] = entry_lighter_price
                lot["entry_lighter_final_fill_at"] = pending.get("entry_lighter_final_fill_at")
                updated = True
            if entry_lighter_price is not None and lot.get("entry_lighter_price_source") != "final_fill":
                lot["entry_lighter_price_source"] = "final_fill"
                lot["entry_lighter_final_fill_at"] = pending.get("entry_lighter_final_fill_at")
                updated = True
            if entry_var_qty is not None and lot.get("entry_var_final_fill_qty") != entry_var_qty:
                lot["entry_var_final_fill_qty"] = entry_var_qty
                updated = True
            if entry_lighter_qty is not None and lot.get("entry_lighter_final_fill_qty") != entry_lighter_qty:
                lot["entry_lighter_final_fill_qty"] = entry_lighter_qty
                updated = True
            final_prices_available = (
                entry_var_price is not None and entry_lighter_price is not None
            )
            final_sources_already_confirmed = (
                lot.get("entry_var_price_source") == "final_fill"
                and lot.get("entry_lighter_price_source") == "final_fill"
                and to_decimal(lot.get("entry_var_fill_price")) is not None
                and to_decimal(lot.get("entry_lighter_fill_price")) is not None
            )
            cost_status = (
                "final_fills_confirmed"
                if final_prices_available or final_sources_already_confirmed
                else "final_fills_pending"
            )
            if lot.get("entry_cost_status") != cost_status:
                lot["entry_cost_status"] = cost_status
                updated = True
            break
        return updated

    @staticmethod
    def live_inventory_entry_cost_confirmed(lot: dict[str, Any]) -> bool:
        if lot.get("entry_cost_status") == "final_fills_confirmed":
            return True
        return (
            lot.get("entry_var_price_source") == "final_fill"
            and lot.get("entry_lighter_price_source") == "final_fill"
            and to_decimal(lot.get("entry_var_fill_price")) is not None
            and to_decimal(lot.get("entry_lighter_fill_price")) is not None
        )

    async def maybe_append_live_inventory_final_pnl_from_fill(self, payload: dict[str, Any]) -> None:
        role = str(payload.get("auto_live_role") or "")
        if role not in {"live_inventory_entry", "live_inventory_exit"}:
            return
        lot_id = payload.get("auto_live_cycle_id")
        asset = str(payload.get("asset") or "")
        if lot_id is None or not asset:
            return
        normalized_lot_id = self.live_inventory_normalized_lot_id(lot_id)
        checkpointed_lot_ids = {
            self.live_inventory_normalized_lot_id(value)
            for value in getattr(
                self,
                "live_inventory_v4_checkpointed_lot_ids",
                set(),
            )
        }
        if (
            getattr(self, "live_inventory_basis_v4_mode", False)
            and normalized_lot_id in checkpointed_lot_ids
        ):
            return

        key = self.live_inventory_final_pnl_key(asset, lot_id)
        pending = self.pending_live_inventory_final_pnl.setdefault(key, {"asset": asset, "lot_id": lot_id})
        pending.setdefault("qty", payload.get("qty"))
        if role == "live_inventory_entry":
            if payload.get("variational_filled_price") is not None and payload.get("synthetic_eager_fill") is False:
                pending["entry_var_final_fill_price"] = payload.get("variational_filled_price")
                pending["entry_var_final_fill_at"] = payload.get("variational_filled_at")
                pending["entry_var_final_fill_qty"] = payload.get("qty")
            if payload.get("lighter_filled_price") is not None:
                pending["entry_lighter_final_fill_price"] = payload.get("lighter_filled_price")
                pending["entry_lighter_final_fill_at"] = payload.get("lighter_filled_at")
                pending["entry_lighter_final_fill_qty"] = payload.get("lighter_filled_base_amount")
            if self.sync_live_inventory_open_lot_entry_cost(asset=asset, lot_id=lot_id):
                await self.persist_live_inventory_memory(reason="entry_final_fill_cost_update")
        else:
            if payload.get("variational_filled_price") is not None and payload.get("synthetic_eager_fill") is False:
                pending["exit_var_final_fill_price"] = payload.get("variational_filled_price")
                pending["exit_var_final_fill_at"] = payload.get("variational_filled_at")
                pending["exit_var_final_fill_qty"] = payload.get("qty")
            if payload.get("lighter_filled_price") is not None:
                pending["exit_lighter_final_fill_price"] = payload.get("lighter_filled_price")
                pending["exit_lighter_final_fill_at"] = payload.get("lighter_filled_at")
                pending["exit_lighter_final_fill_qty"] = payload.get("lighter_filled_base_amount")

        await self.maybe_append_live_inventory_final_pnl(key)

    async def maybe_append_live_inventory_final_pnl(self, key: str) -> None:
        pending = self.pending_live_inventory_final_pnl.get(key)
        if not pending or pending.get("final_pnl_emitted"):
            return
        if (
            getattr(self, "live_inventory_basis_v4_mode", False)
            and self.live_inventory_normalized_lot_id(pending.get("lot_id"))
            in {
                self.live_inventory_normalized_lot_id(value)
                for value in getattr(
                    self,
                    "live_inventory_v4_checkpointed_lot_ids",
                    set(),
                )
            }
        ):
            self.pending_live_inventory_final_pnl.pop(key, None)
            return

        qty = to_decimal(pending.get("qty"))
        direction = str(pending.get("direction") or "")
        entry_var_price = to_decimal(pending.get("entry_var_final_fill_price"))
        entry_lighter_price = to_decimal(pending.get("entry_lighter_final_fill_price"))
        exit_var_price = to_decimal(pending.get("exit_var_final_fill_price"))
        exit_lighter_price = to_decimal(pending.get("exit_lighter_final_fill_price"))
        if None in {qty, entry_var_price, entry_lighter_price, exit_var_price, exit_lighter_price} or not direction:
            return
        entry_var_qty = to_decimal(pending.get("entry_var_final_fill_qty")) or qty
        exit_var_qty = to_decimal(pending.get("exit_var_final_fill_qty")) or qty
        entry_lighter_qty = to_decimal(pending.get("entry_lighter_final_fill_qty")) or qty
        exit_lighter_qty = to_decimal(pending.get("exit_lighter_final_fill_qty")) or qty
        var_qty = min(entry_var_qty, exit_var_qty)
        lighter_qty = min(entry_lighter_qty, exit_lighter_qty)
        var_roundtrip_qty_match = entry_var_qty == exit_var_qty
        lighter_roundtrip_qty_match = entry_lighter_qty == exit_lighter_qty
        entry_estimated_var_price = to_decimal(pending.get("entry_estimated_var_price"))
        entry_estimated_lighter_price = to_decimal(pending.get("entry_estimated_lighter_price"))
        exit_estimated_var_price = to_decimal(pending.get("exit_estimated_var_price"))
        exit_estimated_lighter_price = to_decimal(pending.get("exit_estimated_lighter_price"))
        entry_snapshot_var_bid = to_decimal(pending.get("entry_snapshot_var_bid"))
        entry_snapshot_var_ask = to_decimal(pending.get("entry_snapshot_var_ask"))
        entry_snapshot_var_mid = to_decimal(pending.get("entry_snapshot_var_mid"))
        entry_snapshot_var_buy_price = to_decimal(pending.get("entry_snapshot_var_buy_price"))
        entry_snapshot_var_sell_price = to_decimal(pending.get("entry_snapshot_var_sell_price"))
        entry_var_order_quote_execution_price = to_decimal(pending.get("entry_var_order_quote_execution_price"))
        exit_var_order_quote_execution_price = to_decimal(pending.get("exit_var_order_quote_execution_price"))
        entry_signal_edge_bps = to_decimal(pending.get("entry_signal_edge_bps"))
        entry_estimated_edge_bps = self.live_inventory_pair_edge_bps(
            direction=direction,
            var_price=entry_estimated_var_price,
            lighter_price=entry_estimated_lighter_price,
        )
        entry_final_edge_bps = self.live_inventory_pair_edge_bps(
            direction=direction,
            var_price=entry_var_price,
            lighter_price=entry_lighter_price,
        )
        exit_estimated_edge_bps = self.live_inventory_pair_edge_bps(
            direction=direction,
            var_price=exit_estimated_var_price,
            lighter_price=exit_estimated_lighter_price,
        )
        exit_final_edge_bps = self.live_inventory_pair_edge_bps(
            direction=direction,
            var_price=exit_var_price,
            lighter_price=exit_lighter_price,
        )
        entry_edge_capture_loss_bps = None
        if entry_signal_edge_bps is not None and entry_final_edge_bps is not None:
            entry_edge_capture_loss_bps = entry_signal_edge_bps - entry_final_edge_bps
        final_spread_capture_bps = None
        if entry_final_edge_bps is not None and exit_final_edge_bps is not None:
            final_spread_capture_bps = entry_final_edge_bps - exit_final_edge_bps

        var_leg_pnl, lighter_leg_pnl, final_pnl = self.live_inventory_pair_pnl_by_leg_qty(
            direction=direction,
            var_qty=var_qty,
            lighter_qty=lighter_qty,
            entry_var_price=entry_var_price or Decimal("0"),
            entry_lighter_price=entry_lighter_price or Decimal("0"),
            exit_var_price=exit_var_price or Decimal("0"),
            exit_lighter_price=exit_lighter_price or Decimal("0"),
        )
        notional = var_qty * (entry_var_price or Decimal("0"))
        final_pnl_bps = final_pnl / notional * Decimal("10000") if notional else None
        if not hasattr(self, "live_inventory_execution_loss_bps_samples"):
            self.live_inventory_execution_loss_bps_samples = deque(maxlen=20)
        if (
            entry_edge_capture_loss_bps is not None
            and var_roundtrip_qty_match
            and lighter_roundtrip_qty_match
        ):
            self.live_inventory_execution_loss_bps_samples.append(
                max(entry_edge_capture_loss_bps, Decimal("0"))
            )
        pending["final_pnl_emitted"] = True
        final_pnl_payload = {
                **pending,
                "final_pnl_status": (
                    "var_and_lighter_final_fills_confirmed"
                    if var_roundtrip_qty_match and lighter_roundtrip_qty_match
                    else "leg_quantity_mismatch_requires_reconciliation"
                ),
                "planned_qty": decimal_to_str(qty),
                "entry_var_final_fill_qty": decimal_to_str(entry_var_qty),
                "exit_var_final_fill_qty": decimal_to_str(exit_var_qty),
                "final_var_pnl_qty": decimal_to_str(var_qty),
                "entry_lighter_final_fill_qty": decimal_to_str(entry_lighter_qty),
                "exit_lighter_final_fill_qty": decimal_to_str(exit_lighter_qty),
                "final_lighter_pnl_qty": decimal_to_str(lighter_qty),
                "var_roundtrip_qty_match": var_roundtrip_qty_match,
                "lighter_roundtrip_qty_match": lighter_roundtrip_qty_match,
                "cross_venue_entry_qty_delta": decimal_to_str(entry_var_qty - entry_lighter_qty),
                "cross_venue_exit_qty_delta": decimal_to_str(exit_var_qty - exit_lighter_qty),
                "final_var_leg_pnl_usd": decimal_to_str(var_leg_pnl),
                "final_lighter_leg_pnl_usd": decimal_to_str(lighter_leg_pnl),
                "final_pnl_usd": decimal_to_str(final_pnl),
                "final_pnl_bps": decimal_to_str(final_pnl_bps),
                "entry_estimated_edge_bps": decimal_to_str(entry_estimated_edge_bps),
                "entry_final_edge_bps": decimal_to_str(entry_final_edge_bps),
                "exit_estimated_edge_bps": decimal_to_str(exit_estimated_edge_bps),
                "exit_final_edge_bps": decimal_to_str(exit_final_edge_bps),
                "entry_edge_capture_loss_bps": decimal_to_str(entry_edge_capture_loss_bps),
                "final_spread_capture_bps": decimal_to_str(final_spread_capture_bps),
                "recent_execution_loss_buffer_bps": decimal_to_str(
                    self.live_inventory_recent_execution_loss_buffer_bps()
                ),
                "entry_var_final_vs_snapshot_bid_bps": decimal_to_str(
                    self.live_inventory_price_drift_bps(entry_var_price, entry_snapshot_var_bid)
                ),
                "entry_var_final_vs_snapshot_ask_bps": decimal_to_str(
                    self.live_inventory_price_drift_bps(entry_var_price, entry_snapshot_var_ask)
                ),
                "entry_var_final_vs_snapshot_mid_bps": decimal_to_str(
                    self.live_inventory_price_drift_bps(entry_var_price, entry_snapshot_var_mid)
                ),
                "entry_var_final_vs_snapshot_buy_bps": decimal_to_str(
                    self.live_inventory_price_drift_bps(entry_var_price, entry_snapshot_var_buy_price)
                ),
                "entry_var_final_vs_snapshot_sell_bps": decimal_to_str(
                    self.live_inventory_price_drift_bps(entry_var_price, entry_snapshot_var_sell_price)
                ),
                "entry_var_order_quote_vs_snapshot_buy_bps": decimal_to_str(
                    self.live_inventory_price_drift_bps(entry_var_order_quote_execution_price, entry_snapshot_var_buy_price)
                ),
                "entry_var_order_quote_vs_snapshot_sell_bps": decimal_to_str(
                    self.live_inventory_price_drift_bps(entry_var_order_quote_execution_price, entry_snapshot_var_sell_price)
                ),
                "entry_var_final_vs_order_quote_bps": decimal_to_str(
                    self.live_inventory_price_drift_bps(entry_var_price, entry_var_order_quote_execution_price)
                ),
                "entry_var_fill_drift_bps": decimal_to_str(
                    self.live_inventory_price_drift_bps(entry_var_price, entry_estimated_var_price)
                ),
                "entry_lighter_fill_drift_bps": decimal_to_str(
                    self.live_inventory_price_drift_bps(entry_lighter_price, entry_estimated_lighter_price)
                ),
                "exit_var_fill_drift_bps": decimal_to_str(
                    self.live_inventory_price_drift_bps(exit_var_price, exit_estimated_var_price)
                ),
                "exit_var_final_vs_order_quote_bps": decimal_to_str(
                    self.live_inventory_price_drift_bps(exit_var_price, exit_var_order_quote_execution_price)
                ),
                "exit_lighter_fill_drift_bps": decimal_to_str(
                    self.live_inventory_price_drift_bps(exit_lighter_price, exit_estimated_lighter_price)
                ),
            }
        await self.append_live_inventory_log(
            "live_inventory_final_pnl",
            final_pnl_payload,
        )
        await self.append_live_inventory_log(
            "live_inventory_execution_ledger",
            {
                **final_pnl_payload,
                "phase": "cycle",
                "execution_stage": "final_fills_confirmed",
            },
        )
        await self.maybe_auto_stop_completed_v4_cycle(final_pnl_payload)
    async def live_inventory_entry_preflight(
        self,
        *,
        asset: str,
        direction: str,
        var_side: str,
        qty: Decimal,
        var_price: Decimal,
        lighter_price: Decimal,
        edge_bps: Decimal | None,
        var_spread_bps: Decimal | None = None,
        var_snapshot_timestamp: str | None = None,
        min_entry_bps: Decimal | None = None,
        dynamic_entry_buffer_bps: Decimal | None = None,
        apply_dynamic_entry_floor: bool = True,
        enforce_entry_edge: bool = True,
    ) -> tuple[bool, str, dict[str, Any]]:
        var_snapshot_age_seconds = self._age_seconds_from_iso(var_snapshot_timestamp)
        notional = qty * lighter_price
        context = {
            "action": "entry",
            "direction": direction,
            "var_side": var_side,
            "qty": decimal_to_str(qty),
            "var_price": decimal_to_str(var_price),
            "lighter_price": decimal_to_str(lighter_price),
            "lighter_notional_usd": decimal_to_str(notional),
            "entry_edge_bps": decimal_to_str(edge_bps),
            "var_spread_bps": decimal_to_str(var_spread_bps),
            "var_snapshot_timestamp": var_snapshot_timestamp,
            "var_snapshot_age_seconds": f"{var_snapshot_age_seconds:.3f}" if var_snapshot_age_seconds is not None else None,
            "live_inventory_max_var_snapshot_age_seconds": f"{self.live_inventory_max_var_snapshot_age_seconds:.3f}",
            "live_inventory_max_var_spread_bps": decimal_to_str(self.live_inventory_max_var_spread_bps),
            "live_inventory_entry_bps": decimal_to_str(self.live_inventory_entry_bps),
            "live_inventory_dynamic_entry_buffer_bps": decimal_to_str(self.live_inventory_dynamic_entry_buffer_bps),
            "live_inventory_max_lighter_slippage_bps": decimal_to_str(self.live_inventory_max_lighter_slippage_bps),
            "live_inventory_lighter_submit_slippage_bps": decimal_to_str(
                getattr(
                    self,
                    "live_inventory_lighter_submit_slippage_bps",
                    self.live_inventory_max_lighter_slippage_bps,
                )
            ),
            "live_inventory_lighter_exit_submit_slippage_bps": decimal_to_str(
                getattr(self, "live_inventory_lighter_exit_submit_slippage_bps", self.live_inventory_max_lighter_slippage_bps)
            ),
            "live_inventory_recent_execution_loss_buffer_bps": decimal_to_str(
                self.live_inventory_recent_execution_loss_buffer_bps()
            ),
            "live_inventory_required_entry_bps": None,
            "live_inventory_dynamic_entry_floor_applied": apply_dynamic_entry_floor,
            "lighter_side": None,
            "lighter_estimated_fill_price": None,
            "lighter_order_book_slippage_bps": None,
            "lighter_order_book_depth": None,
            "precheck_edge_bps": None,
            "lighter_min_base_amount": decimal_to_str(self.lighter_min_base_amount),
            "lighter_min_quote_amount": decimal_to_str(self.lighter_min_quote_amount),
            "live_max_notional_usd": decimal_to_str(self.live_max_notional_usd),
            "live_cooldown_remaining_seconds": None,
        }
        if var_spread_bps is not None and var_spread_bps > self.live_inventory_max_var_spread_bps:
            return False, "var_spread_exceeds_live_inventory_limit", context
        if var_snapshot_age_seconds is None or var_snapshot_age_seconds > self.live_inventory_max_var_snapshot_age_seconds:
            return False, "variational_quote_snapshot_stale", context
        last_submit_monotonic = self.last_live_submit_monotonic_by_asset.get(asset.upper())
        if last_submit_monotonic is not None:
            cooldown_elapsed = time.monotonic() - last_submit_monotonic
            if cooldown_elapsed < self.live_cooldown_seconds:
                remaining = self.live_cooldown_seconds - cooldown_elapsed
                context["live_cooldown_remaining_seconds"] = f"{remaining:.3f}"
                return False, "live_cooldown_active", context
        ok, reason, precheck_edge_bps = await self.auto_live_lighter_precheck(
            asset=asset,
            var_side=var_side,
            qty=qty,
            var_fill_price=var_price,
        )
        context["precheck_edge_bps"] = decimal_to_str(precheck_edge_bps)
        if not ok:
            return False, reason, context

        lighter_side = "SELL" if var_side.strip().upper() == "BUY" else "BUY"
        lighter_depth = await self.live_inventory_lighter_depth_context(
            lighter_side=lighter_side,
            qty=qty,
        )
        lighter_estimated_fill_price = to_decimal(lighter_depth.get("estimated_fill_price"))
        lighter_slippage_bps = to_decimal(lighter_depth.get("slippage_bps"))
        context["lighter_side"] = lighter_side
        context["lighter_estimated_fill_price"] = decimal_to_str(lighter_estimated_fill_price)
        context["lighter_order_book_slippage_bps"] = decimal_to_str(lighter_slippage_bps)
        context["lighter_order_book_depth"] = lighter_depth
        if lighter_estimated_fill_price is None or lighter_slippage_bps is None:
            return False, "lighter_order_book_depth_insufficient", context
        if lighter_slippage_bps > self.live_inventory_max_lighter_slippage_bps:
            return False, "lighter_slippage_exceeds_live_inventory_limit", context

        required_entry_bps = min_entry_bps if min_entry_bps is not None else self.live_inventory_entry_bps
        dynamic_buffer = dynamic_entry_buffer_bps if dynamic_entry_buffer_bps is not None else self.live_inventory_dynamic_entry_buffer_bps
        recent_execution_loss_buffer_bps = Decimal("0")
        if not self.live_inventory_ignore_recent_execution_loss_buffer_for_diagnostics:
            recent_execution_loss_buffer_bps = self.live_inventory_recent_execution_loss_buffer_bps()
        dynamic_required_entry_bps = (
            (var_spread_bps or Decimal("0"))
            + lighter_slippage_bps
            + recent_execution_loss_buffer_bps
            + dynamic_buffer
        )
        context["live_inventory_recent_execution_loss_buffer_bps"] = decimal_to_str(recent_execution_loss_buffer_bps)
        context["live_inventory_ignored_recent_execution_loss_buffer_for_diagnostics"] = (
            self.live_inventory_ignore_recent_execution_loss_buffer_for_diagnostics
        )
        if apply_dynamic_entry_floor and dynamic_required_entry_bps > required_entry_bps:
            required_entry_bps = dynamic_required_entry_bps
        context["live_inventory_required_entry_bps"] = decimal_to_str(required_entry_bps)
        context["live_inventory_required_entry_margin_bps"] = decimal_to_str(
            None if edge_bps is None else edge_bps - required_entry_bps
        )
        context["live_inventory_entry_edge_enforced"] = enforce_entry_edge
        if enforce_entry_edge and (edge_bps is None or edge_bps < required_entry_bps):
            return False, "edge_bps_below_dynamic_live_inventory_entry", context
        return True, "ok", context

    def auto_live_guard_reason(self) -> str | None:
        if self.auto_live_manual_review_required:
            return "manual_review_required"
        if self.auto_live_max_cycles > 0 and self.auto_live_completed_cycles >= self.auto_live_max_cycles:
            return "max_cycles_reached"
        if self.auto_live_last_closed_monotonic is not None:
            cooldown_elapsed = time.monotonic() - self.auto_live_last_closed_monotonic
            if cooldown_elapsed < self.auto_live_cooldown_seconds:
                return "cooldown_active"
        return None

    def maybe_log_auto_live_guard(self, reason: str) -> None:
        marker = (reason, self.auto_live_completed_cycles, self.auto_live_next_cycle_id)
        if self._last_auto_live_guard_log == marker:
            return
        self._last_auto_live_guard_log = marker
        remaining_seconds: float | None = None
        if reason == "cooldown_active" and self.auto_live_last_closed_monotonic is not None:
            elapsed = time.monotonic() - self.auto_live_last_closed_monotonic
            remaining_seconds = max(0.0, self.auto_live_cooldown_seconds - elapsed)
        if reason == "manual_review_required":
            position = self.auto_live_position
            self.logger.warning(
                "auto_live_manual_review_required cycle_id=%s asset=%s qty=%s reason=%s action=stop_auto_live_until_restart",
                position.cycle_id if position is not None else "-",
                position.asset if position is not None else "-",
                position.planned_qty if position is not None else "-",
                self.auto_live_manual_review_reason or (position.manual_review_reason if position is not None else None) or "unknown",
            )
            return
        self.logger.info(
            "auto_live_guard_blocked reason=%s next_cycle_id=%s completed_cycles=%s max_cycles=%s cooldown_remaining_seconds=%s",
            reason,
            self.auto_live_next_cycle_id,
            self.auto_live_completed_cycles,
            self.auto_live_max_cycles,
            f"{remaining_seconds:.3f}" if remaining_seconds is not None else "-",
        )

    def require_auto_live_manual_review(self, position: AutoLivePositionState | None, reason: str) -> None:
        already_required = self.auto_live_manual_review_required and self.auto_live_manual_review_reason == reason
        self.auto_live_manual_review_required = True
        self.auto_live_manual_review_reason = reason
        if position is not None:
            position.manual_review_required = True
            position.manual_review_reason = reason
            position.manual_review_logged = True
            self.write_auto_live_state(
                {
                    "status": "manual_review_required",
                    "asset": position.asset,
                    "cycle_id": position.cycle_id,
                    "direction": position.direction,
                    "qty": decimal_to_str(position.planned_qty),
                    "reason": reason,
                    "action": "stop_auto_live_until_restart",
                }
            )
        if not already_required:
            self._last_auto_live_guard_log = None
        self.maybe_log_auto_live_guard("manual_review_required")
        if already_required:
            return
        try:
            loop = asyncio.get_running_loop()
        except RuntimeError:
            return
        loop.create_task(
            self.append_order_log(
                "auto_live_manual_review_required",
                {
                    "record_kind": "auto_live_manual_review",
                    "mode": self.mode,
                    "asset": position.asset if position is not None else self.variational_ticker or self.ticker or "",
                    "auto_live_cycle_id": position.cycle_id if position is not None else None,
                    "direction": position.direction if position is not None else None,
                    "qty": decimal_to_str(position.planned_qty) if position is not None else None,
                    "reason": reason,
                    "rollback_action": "manual_review_required",
                    "action": "stop_auto_live_until_restart",
                },
            )
        )

    def should_log_auto_live_precheck_failure(
        self,
        kind: str,
        cycle_id: int,
        asset: str,
        side: str,
        reason: str | None,
        *,
        interval_seconds: float = 10.0,
    ) -> bool:
        key = (kind, cycle_id, asset.upper(), side.upper(), reason or "unknown")
        now = time.monotonic()
        last_logged_at = self._last_auto_live_precheck_failure_log.get(key)
        if last_logged_at is not None and now - last_logged_at < interval_seconds:
            return False
        self._last_auto_live_precheck_failure_log[key] = now
        return True

    def load_auto_live_state(self) -> dict[str, Any]:
        if self.auto_live_state_file is None or not self.auto_live_state_file.exists():
            return {"status": "flat"}
        try:
            with self.auto_live_state_file.open("r", encoding="utf-8") as handle:
                state = json.load(handle)
        except (OSError, json.JSONDecodeError) as exc:
            return {"status": "unknown", "reason": f"state_load_failed:{exc}"}
        if not isinstance(state, dict):
            return {"status": "unknown", "reason": "state_file_not_object"}
        status = str(state.get("status", "")).strip() or "unknown"
        return {**state, "status": status}

    def write_auto_live_state(self, state: dict[str, Any]) -> None:
        if self.auto_live_state_file is None:
            return
        row = {"updated_at": utc_now(), **state}
        self.auto_live_state_file.parent.mkdir(parents=True, exist_ok=True)
        tmp_path = self.auto_live_state_file.with_suffix(self.auto_live_state_file.suffix + ".tmp")
        tmp_path.write_text(json.dumps(row, ensure_ascii=True, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        tmp_path.replace(self.auto_live_state_file)

    async def write_auto_live_state_async(self, state: dict[str, Any]) -> None:
        await asyncio.to_thread(self.write_auto_live_state, state)

    def auto_live_state_summary(self, state: dict[str, Any]) -> str:
        status = clean_state_value(state.get("status"))
        parts = [f"status={status or 'unknown'}"]
        for key in ("asset", "cycle_id", "direction", "qty", "reason", "updated_at"):
            value = clean_state_value(state.get(key))
            if value:
                parts.append(f"{key}={value}")
        return " ".join(parts)

    def load_live_inventory_state(self) -> dict[str, Any]:
        if self.live_inventory_state_file is None or not self.live_inventory_state_file.exists():
            return {"status": "flat", "open_lots": []}
        try:
            with self.live_inventory_state_file.open("r", encoding="utf-8") as handle:
                state = json.load(handle)
        except (OSError, json.JSONDecodeError) as exc:
            return {"status": "unknown", "reason": f"state_load_failed:{exc}"}
        if not isinstance(state, dict):
            return {"status": "unknown", "reason": "state_file_not_object"}
        status = str(state.get("status", "")).strip() or "unknown"
        open_lots = state.get("open_lots") or []
        pending_actions = state.get("pending_actions") or []
        if status in {"flat", "open", "pending"}:
            status = live_inventory_state_status(
                open_lots=open_lots,
                pending_actions=pending_actions,
            )
        return {**state, "status": status}

    def write_live_inventory_state(self, state: dict[str, Any]) -> None:
        if self.live_inventory_state_file is None:
            return
        row = {"updated_at": utc_now(), **state}
        self.live_inventory_state_file.parent.mkdir(parents=True, exist_ok=True)
        tmp_path = self.live_inventory_state_file.with_suffix(self.live_inventory_state_file.suffix + ".tmp")
        tmp_path.write_text(json.dumps(row, ensure_ascii=True, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        tmp_path.replace(self.live_inventory_state_file)

    async def write_live_inventory_state_async(self, state: dict[str, Any]) -> None:
        await asyncio.to_thread(self.write_live_inventory_state, state)

    def live_inventory_state_summary(self, state: dict[str, Any]) -> str:
        status = clean_state_value(state.get("status"))
        parts = [f"status={status or 'unknown'}"]
        for key in ("asset", "next_lot_id", "manual_review_reason", "reason", "updated_at"):
            value = clean_state_value(state.get(key))
            if value:
                parts.append(f"{key}={value}")
        open_lots = state.get("open_lots")
        if isinstance(open_lots, list):
            parts.append(f"open_lots={len(open_lots)}")
        return " ".join(parts)

    @staticmethod
    def auto_live_eager_hedge_started(record: OrderLifecycle | None) -> bool:
        return record is not None and record.processing_stage in {STAGE_LIVE_SUBMIT_SENT, STAGE_LIGHTER_FILLED}

    async def wait_for_lighter_final_fill(
        self,
        record: OrderLifecycle | None,
        *,
        timeout_seconds: float | None = None,
    ) -> bool:
        if record is None:
            return False
        timeout = self.live_submit_timeout_seconds if timeout_seconds is None else timeout_seconds
        deadline = time.monotonic() + max(0.1, float(timeout))
        while time.monotonic() <= deadline:
            async with self._record_lock:
                if record.lighter_fill_ts_iso is not None and record.lighter_fill_price is not None:
                    return True
                if record.processing_stage in {STAGE_LIVE_SUBMIT_FAILED, STAGE_LIVE_SUBMIT_TIMED_OUT}:
                    return False
            await asyncio.sleep(0.01)
        return False

    def timing_logger(self) -> logging.Logger:
        return getattr(self, "logger", logging.getLogger(__name__))

    def log_auto_live_eager_hedge_timing(
        self,
        *,
        cycle_id: int,
        role: str,
        asset: str,
        side: str,
        signal_monotonic: float,
        task_created_monotonic: float | None,
        record: OrderLifecycle,
    ) -> None:
        self.timing_logger().info(
            "auto_live_eager_hedge_timing cycle_id=%s role=%s asset=%s side=%s record_key=%s "
            "signal_to_task_create_ms=%s task_create_to_plan_start_ms=%s plan_ms=%s "
            "plan_ready_to_submit_start_ms=%s submit_call_ms=%s signal_to_submit_sent_ms=%s",
            cycle_id,
            role,
            asset,
            side,
            record.trade_key,
            elapsed_ms_between_str(signal_monotonic, task_created_monotonic),
            elapsed_ms_between_str(task_created_monotonic, record.live_plan_started_monotonic),
            elapsed_ms_between_str(record.live_plan_started_monotonic, record.live_plan_ready_monotonic),
            elapsed_ms_between_str(record.live_plan_ready_monotonic, record.live_submit_started_monotonic),
            elapsed_ms_between_str(record.live_submit_started_monotonic, record.live_submit_sent_monotonic),
            elapsed_ms_between_str(signal_monotonic, record.live_submit_sent_monotonic),
        )

    async def auto_live_lighter_precheck(
        self,
        *,
        asset: str,
        var_side: str,
        qty: Decimal,
        var_fill_price: Decimal,
    ) -> tuple[bool, str, Decimal | None]:
        if self._lighter_order_book_is_stale():
            return False, "lighter_order_book_stale", None
        best_bid, best_ask = await self.get_lighter_best_bid_ask()
        if best_bid is None or best_ask is None:
            return False, "lighter_order_book_not_ready", None

        lighter_side = "SELL" if var_side.strip().upper() == "BUY" else "BUY"
        slippage = Decimal(str(HEDGE_SLIPPAGE_BPS)) / Decimal("10000")
        limit_price = best_ask * (Decimal("1") + slippage) if lighter_side == "BUY" else best_bid * (Decimal("1") - slippage)
        notional = qty * limit_price
        edge_bps = basis_points_diff(limit_price, var_fill_price)
        base_amount = int(qty * self.base_amount_multiplier)

        if base_amount <= 0:
            return False, "hedge_base_amount_rounds_to_zero", edge_bps
        if self.lighter_min_base_amount is not None and qty < self.lighter_min_base_amount:
            return False, "hedge_below_lighter_min_base_amount", edge_bps
        if base_amount > self.risk_guard_max_base_amount:
            return False, "hedge_base_amount_exceeds_risk_limit", edge_bps
        if edge_bps is not None and edge_bps > self.risk_guard_max_price_deviation_bps:
            return False, "hedge_price_deviation_exceeds_risk_limit", edge_bps
        if self.lighter_min_quote_amount is not None and notional < self.lighter_min_quote_amount:
            return False, "hedge_below_lighter_min_quote_amount", edge_bps
        if self.live_allowed_sides and var_side.strip().lower() not in self.live_allowed_sides:
            return False, "live_side_not_allowed", edge_bps
        if self.live_allowed_assets and asset.upper() not in self.live_allowed_assets:
            return False, "live_asset_not_allowed", edge_bps
        if self.live_max_qty > 0 and qty > self.live_max_qty:
            return False, "live_qty_exceeds_limit", edge_bps
        if self.live_max_notional_usd > 0 and notional > self.live_max_notional_usd:
            return False, "live_notional_exceeds_limit", edge_bps
        if edge_bps is not None and edge_bps < self.live_require_min_edge_bps:
            return False, "live_edge_bps_below_threshold", edge_bps
        return True, "ok", edge_bps

    def requires_lighter_market_data(self) -> bool:
        return self.is_dry_run_mode() or self.is_live_mode() or self.is_paper_mode()

    def requires_lighter_trading_credentials(self) -> bool:
        return self.is_live_mode()

